/**
 * Derive the sticky lifecycle value a milestone implies. `rendered` and `responded` are both
 * progress *within* `working`; they are told apart by the substate timestamp, not by this value.
 */
function lifecycleForMilestone(milestone: StepMilestone): StepLifecycle {
  switch (milestone) {
    case 'pending':
      return 'pending';
    case 'completed':
      return 'completed';
    case 'skipped':
      return 'skipped';
    default:
      return 'working';
  }
}

/**
 * Step lifecycles that may not be transitioned out of.
 *
 * `completed` was the only one until P4; `skipped` joins it because a step the mutation policy
 * retired must not be re-rendered by a later capture — the whole point of the skip is that the
 * client never sees it again.
 */
const TERMINAL_STEP_LIFECYCLES: ReadonlySet<StepLifecycle> = new Set<StepLifecycle>([
  'completed',
  'skipped',
]);

/** Step lifecycles that mean "this step has already been rendered, run, or retired". */
function hasStepStarted(state: StepLifecycle | undefined): boolean {
  return state !== undefined && state !== 'pending';
}

/**
 * Hard ceiling on ACCEPTED REMAINDERS per run, independent of how many distinct unknowns raised
 * an interrupt (plan §Interrupt payload: "a `maxInsertions`-style ceiling per run").
 *
 * Its own number rather than a reuse of `MAX_INSERTIONS_PER_RUN`: the two ceilings count
 * different acts (the SERVER inserting one investigation node vs the CALLER rewriting the plan)
 * and mirroring 3 is a coincidence of taste, not a shared rule — importing the other constant
 * would make a change to one silently retune the other, which is the reason
 * `DEFAULT_WORKFLOW_CAPS.maxInsertions` mirrors rather than imports it too.
 *
 * Enforced HERE rather than at the submission boundary because the count is recomputed from
 * persisted rows (`origin === 'remainder'`), so a resumed run and a cold-loaded one enforce the
 * same ceiling. A submission-declared NARROWING of it belongs to the caller, which can refuse
 * before calling; this is the floor no caller can widen.
 */
export const MAX_REMAINDERS_PER_RUN = 3;

/**
 * How many remainders a run has accepted: DISTINCT unknown ids among its `origin: 'remainder'`
 * nodes.
 *
 * One expression with two callers, deliberately. `refuseRemainder` measures the per-run cap with
 * it and `getRunTelemetry` reports `remaindersAccepted` with it (D-8), so the recorded number and
 * the ceiling it is measured against cannot come to mean different things — a remainder of four
 * nodes is ONE remainder to both.
 */
function countRemainderUnknownIds(nodes: readonly ChainNode[]): number {
  return new Set(
    nodes
      .filter((node) => node.origin === 'remainder')
      .map((node) => node.originUnknownId)
      .filter((id): id is string => id !== undefined)
  ).size;
}

/**
 * Turn a caller's remainder specs into run nodes with unique ids and remainder provenance.
 *
 * Ids are reserved against EVERY id the run currently carries — including the tail a
 * `'replace'` is about to remove. Freeing those ids for immediate reuse would let a replacement
 * mint a node with the id of the node it just deleted, and gate targets, execution records and
 * `executionOrder` entries address nodes by id: the new step would silently inherit the old
 * one's addressing. Reservation is also cumulative across the batch, so two specs asking for the
 * same id get two distinct nodes rather than one collision.
 *
 * A declared id is honoured when it is free and slugified/suffixed by `mintInsertionId` when it
 * is not; a spec with no id is minted from its `stepName`, exactly as an inserted node is.
 *
 * Every node carries `acceptedAtStep`, the ordinal the run stands on as it accepts them (R136):
 * the per-unknown-id cap reads it, because an appended node's own ordinal is not when it came.
 */
function mintRemainderNodes(
  specs: readonly RemainderNodeSpec[],
  existing: readonly ChainNode[],
  unknownId: string,
  acceptedAtStep: number
): ChainNode[] {
  const taken = existing.map((node) => node.id);
  return specs.map((spec) => {
    const id = mintInsertionId(spec.id ?? spec.stepName, taken);
    taken.push(id);
    return {
      id,
      promptId: spec.promptId,
      stepName: spec.stepName,
      origin: 'remainder' as const,
      originUnknownId: unknownId,
      acceptedAtStep,
      // A.5: the node's own declaration travels with it. Spread conditionally rather than bound
      // to `undefined`, because `exactOptionalPropertyTypes` rejects an explicit undefined and
      // the hook projection pins the resulting key set.
      ...(spec.args !== undefined ? { args: spec.args } : {}),
      ...(spec.delegated !== undefined ? { delegated: spec.delegated } : {}),
      ...(spec.inlineGateIds !== undefined && spec.inlineGateIds.length > 0
        ? { inlineGateIds: [...spec.inlineGateIds] }
        : {}),
    };
  });
}

/** Callback invoked when a session is cleared (cleanup or explicit). */
export type SessionClearedCallback = (
  sessionId: string,
  session: ChainSession
) => void | Promise<void>;

export interface ChainSessionStoreOptions {
  defaultSessionTimeoutMs?: number;
  reviewSessionTimeoutMs?: number;
  cleanupIntervalMs?: number;
  /**
   * Database the store persists through, supplied at construction.
   *
   * The constructor starts `initialize()` immediately, so a port that arrives only through
   * `setDatabasePort()` leaves the store observable without persistence until the setter runs —
   * and every start warned "persistence disabled" for a store that went on to persist. Supplying
   * it here makes the first initialization the real one. A `DatabasePort` passed as the positional
   * fourth argument takes precedence; that slot is the tests' injection point.
   */
  databasePort?: DatabasePort;
  /**
   * Workspace scope stamped on the `chain_sessions` hook projection.
   *
   * Distinct from `pidScope`: `chain_sessions.run_owner_pid` is the server PID, which isolates one
   * running server's rows from another's but says nothing about which project they belong to.
   * The scope columns answer that, and until this was supplied they were written NULL and
   * repaired by a startup backfill on the next boot.
   */
  defaultScope?: StateStoreOptions;
}

const DEFAULT_SESSION_TIMEOUT_MS = 24 * 60 * 60 * 1000;
const DEFAULT_REVIEW_SESSION_TIMEOUT_MS = 30 * 60 * 1000;
const DEFAULT_CLEANUP_INTERVAL_MS = 5 * 60 * 1000;
const MAX_RUN_HISTORY = 10;

/** What a removal released, queued until its persist returns (R93): see `releaseRemovedRuns`. */
interface RunRelease {
  sessionIds: string[];
  /** `keep` for an eviction (R116 amended): the claim moved the run, not what this workspace's
   * runs of the chain received (as of 2026-09-28 · flips when argument history is keyed by run). */
  argumentHistory: 'clear' | 'keep';
}

const emptyRunRelease = (argumentHistory: 'clear' | 'keep' = 'clear'): RunRelease => ({
  sessionIds: [],
  argumentHistory,
});

/**
 * Chain Session Store
 *
 * Coordinates session state between MCP protocol, step capture, and execution context tracking.
 * Provides session-aware context retrieval for chain execution.
 */
export class ChainSessionStore implements ChainSessionService {
  private logger: Logger;
  private textReferenceStore: TextReferenceStore;
  private argumentHistoryTracker?: ArgumentHistoryTracker;
  private activeSessions: Map<string, ChainSession> = new Map();
  private chainSessionMapping: Map<string, Set<string>> = new Map(); // chainId -> sessionIds
  private baseChainMapping: Map<string, string[]> = new Map(); // baseChainId -> ordered runIds
  private runChainToBase: Map<string, string> = new Map(); // runChainId -> baseChainId
  private runRegistry!: ChainRunRegistry;
  private readonly sessionClearedCallbacks: SessionClearedCallback[] = [];
  private readonly runEndedCallbacks: Array<(sessionId: string) => void> = [];
  private readonly defaultSessionTimeoutMs: number;
  private readonly reviewSessionTimeoutMs: number;
  private readonly cleanupIntervalMs: number;
  private cleanupIntervalHandle?: NodeJS.Timeout;
  private injectedDbEngine?: DatabasePort;
  private resolvedDbEngine?: DatabasePort;
  private readonly serverPid = String(process.pid);
  /**
   * Runs created since the last committed persist whose run number `chain_runs` has not yet
   * reserved (R62). The number a caller minted comes from this process's memory; the persist that
   * first writes the run re-reads every owner's rows and re-mints past them.
   */
  private readonly unreservedRuns = new Set<string>();
  /** The tail of the persists in flight: each waits for the one before it (see `persistSessionsOrThrow`). */
  private persistQueue: Promise<void> = Promise.resolve();
  private readonly pidScope: StateStoreOptions = { continuityScopeId: String(process.pid) };
  private readonly workspaceScope: StateStoreOptions | undefined;

  /**
   * Scope for `chain_runs` rows.
   *
   * Merged, not chosen: the PID decides `run_owner_pid` (which server owns the run) while the
   * workspace fills `workspace_id`/`organization_id` (which project it belongs to). They answer
   * different questions, and the registry resolves `run_owner_pid` from `continuityScopeId` first,
   * so adding the workspace keys cannot change run ownership. Passing `pidScope` alone — as this
   * did — left the scope columns NULL for a startup backfill to repair on the next boot.
   *
   * A getter rather than a constructor-computed field because `pidScope` is a field initializer
   * and `workspaceScope` is assigned in the constructor body.
   */
  private get runScope(): StateStoreOptions {
    return { ...this.pidScope, ...(this.workspaceScope ?? {}) };
  }
  private initPromise!: Promise<void>;
  private hookRegistry?: HookRegistryPort;
  private notificationEmitter?: McpNotificationEmitterPort;

  constructor(
    logger: Logger,
    textReferenceStore: TextReferenceStore,
    options: ChainSessionStoreOptions,
    dbEngineOrTracker?: DatabasePort | ArgumentHistoryTracker,
    sessionStore?: ChainRunRegistry
  ) {
    this.logger = logger;
    this.textReferenceStore = textReferenceStore;

    // Detect 4th arg type: DatabasePort (DI for tests) or ArgumentHistoryTracker
    if (dbEngineOrTracker instanceof ArgumentHistoryTracker) {
      this.argumentHistoryTracker = dbEngineOrTracker;
    } else if (dbEngineOrTracker !== undefined) {
      this.injectedDbEngine = dbEngineOrTracker;
    }
    // Read by `initialize()` below. Production passes the tracker positionally, so the port has
    // to travel in the options object rather than in the shared fourth slot.
    this.injectedDbEngine ??= options.databasePort;

    this.defaultSessionTimeoutMs = options.defaultSessionTimeoutMs ?? DEFAULT_SESSION_TIMEOUT_MS;
    this.reviewSessionTimeoutMs =
      options.reviewSessionTimeoutMs ?? DEFAULT_REVIEW_SESSION_TIMEOUT_MS;
    this.cleanupIntervalMs = options.cleanupIntervalMs ?? DEFAULT_CLEANUP_INTERVAL_MS;
    this.workspaceScope = options.defaultScope;

    // Store provided sessionStore or defer to initialize() for SQLite-backed default
    if (sessionStore) {
      this.runRegistry = sessionStore;
    }

    this.logger.debug('ChainSessionStore initialized with text reference manager integration');

    // Initialize asynchronously — store promise so callers can await it
    this.initPromise = this.initialize();
    this.startCleanupScheduler();
  }

  /**
   * Late-bind the run-lifecycle announcement channels (setter injection, matching
   * `setDatabasePort` above). Both are built by the composition root after this store, so
   * neither can travel through the constructor.
   */
  setRunAnnouncementChannels(channels: {
    hookRegistry?: HookRegistryPort;
    notificationEmitter?: McpNotificationEmitterPort;
  }): void {
    this.hookRegistry = channels.hookRegistry;
    this.notificationEmitter = channels.notificationEmitter;
  }

  /** Late-bind DatabasePort (setter injection, matching codebase convention). */
  setDatabasePort(db: DatabasePort): void {
    this.injectedDbEngine = db;
    this.resolvedDbEngine = db;
    // The constructor's initialize() runs synchronously to its early return when no port
    // was provided, permanently disabling persistence — and the runtime composition always
    // late-binds the port through this setter, so without re-arming here every fresh
    // server ran with chain-session persistence silently dead (observed live 2026-08-11:
    // "Failed to save sessions: Cannot read properties of undefined (reading 'save')" on
    // every persist, empty chain_runs/chain_sessions while a run was active). Chain onto
    // initPromise so callers awaiting init observe the completed late load.
    if (!this.runRegistry) {
      this.initPromise = this.initPromise
        .then(async () => {
          if (this.runRegistry) return;
          await db.initialize();
          this.runRegistry = new DirectChainRunRegistry(db);
          await this.runRegistry.ensureInitialized();
          this.cleanupStalePidRows();
          await this.loadSessions();
        })
        .catch((error) => {
          this.logger.warn(
            `ChainSessionStore: late DatabasePort initialization failed: ${
              error instanceof Error ? error.message : String(error)
            }`
          );
        });
    }
  }

  /**
   * Initialize the manager asynchronously
   */
  private async initialize(): Promise<void> {
    try {
      // Create SQLite-backed registry if no custom store was provided
      if (!this.runRegistry) {
        const dbManager = this.injectedDbEngine;
        if (!dbManager) {
          this.logger.warn('ChainSessionStore: no DatabasePort provided, persistence disabled');
          return;
        }
        await dbManager.initialize();
        this.resolvedDbEngine = dbManager;
        this.runRegistry = new DirectChainRunRegistry(dbManager);
      }
      await this.runRegistry.ensureInitialized();
      this.cleanupStalePidRows();
      await this.loadSessions();
    } catch (error) {
      this.logger.warn(
        `Failed to initialize ChainSessionStore: ${
          error instanceof Error ? error.message : String(error)
        }`
      );
    }
  }

  /**
   * Register a callback invoked when any session is cleared (explicit or stale cleanup).
   * Used by pipeline wiring to clean up cross-layer state (e.g., verify-state.db).
   */
  onSessionCleared(callback: SessionClearedCallback): void {
    this.sessionClearedCallbacks.push(callback);
  }

  /**
   * Register a callback invoked once a run ENDS: it reached a terminal status (completed, failed,
   * cancelled — {@link announceRunTerminal}) or its session was removed (clear, prune, stale
   * sweep, eviction after another server's claim — {@link releaseRemovedRuns}, once the removal persisted). A removed run may already have ended, so a callback
   * must tolerate a second call for the same session. Used to release what lives as long as a
   * run, such as its temporary gates (R47).
   */
  onRunEnded(callback: (sessionId: string) => void): void {
    this.runEndedCallbacks.push(callback);
  }

  private notifyRunEnded(sessionId: string): void {
    for (const callback of this.runEndedCallbacks) {
      try {
        callback(sessionId);
      } catch (error) {
        this.logger.warn(
          `Run-ended callback failed for ${sessionId}: ${
            error instanceof Error ? error.message : String(error)
          }`
        );
      }
    }
  }

  /**
   * Fire-and-forget cleanup scheduler (unref to avoid blocking shutdown)
   */
  private startCleanupScheduler(): void {
    if (this.cleanupIntervalHandle) {
      this.cleanupIntervalHandle.unref();
      return;
    }

    this.cleanupIntervalHandle = setInterval(() => {
      this.cleanupStaleSessions().catch((error) => {
        this.logger.warn(
          `Failed to run scheduled session cleanup: ${
            error instanceof Error ? error.message : String(error)
          }`
        );
      });
    }, this.cleanupIntervalMs);

    this.cleanupIntervalHandle.unref();
  }

  /**
   * Load sessions from file (for STDIO transport persistence)
   */
  private async loadSessions(): Promise<void> {
    try {
      const sessions = await this.runRegistry.load(this.runScope);

      for (const session of sessions) {
        if (!(session.state.stepStates instanceof Map)) {
          session.state.stepStates = new Map();
        }

        // All persisted sessions become dormant until explicitly resumed
        session.lifecycle = 'dormant';
        this.activeSessions.set(session.sessionId, session);
      }

      // The three mapping dictionaries are rebuilt, not loaded — they are indexes over the chain
      // ids the sessions already carry, and persisting a derivable index alongside its source is
      // how the two come to disagree. `chainSessionMapping` inverts `session.chainId`;
      // `ensureRunMappingConsistency` derives the base mappings from it via `stripRunNumber`,
      // exactly as `registerRunHistory` does on the write path.
      this.chainSessionMapping.clear();
      this.baseChainMapping.clear();
      this.runChainToBase.clear();
      for (const session of sessions) {
        const sessionIds = this.chainSessionMapping.get(session.chainId) ?? new Set<string>();
        sessionIds.add(session.sessionId);
        this.chainSessionMapping.set(session.chainId, sessionIds);
      }

      this.ensureRunMappingConsistency();

      this.logger.debug(
        `Loaded ${this.activeSessions.size} persisted chain runs from session store`
      );
    } catch (error) {
      this.logger.warn(
        `Failed to load persisted sessions: ${
          error instanceof Error ? error.message : String(error)
        }`
      );
    }
  }

  /**
   * Persist every live run, for a caller that awaits it (R74, P6.175).
   *
   * The store's save callers fall into three classes by where a failure goes. Every AWAITED
   * caller persists through {@link persistMutation}, which restores the memory it changed when
   * the save rejects (R87):
   *  - AWAITED (through this method, 21 mutators from `createSession` to
   *    `clearSessionsForChain`): any failure but a held lock rejects, and the rejection reaches
   *    the tool call as its error —
   *    no caller outside this file catches one, and the one that does
   *    (`endRunOfFailedStartCall`) is already answering a failed call. A held lock is logged and
   *    the call reports success, because the next persist rewrites the whole live set;
   *  - AWAITED, NOTHING SWALLOWED (`strict`, through {@link persistSessionsOrThrow}:
   *    `replaceRemainder`, `applyUnknownObservations`): the two writes whose own reply renders what was written, so
   *    even a held lock fails the call;
   *  - BACKGROUND ({@link persistSessionsAsync}, and `cleanup` at shutdown): no client is waiting,
   *    so the failure is logged with the context that started it.
   */
  private async saveSessions(): Promise<void> {
    await this.persistSessions();
  }

  /**
   * Persist chain sessions to durable storage. Wraps the SSOT per-row save and the
   * derived hook view in a single SQLite transaction so the two stay in
   * lockstep — either both committed or both rolled back.
   *
   * `chain_runs` + `chain_run_nodes` are the SSOT; `chain_sessions` (per-row) is a
   * projection of the active hook-relevant subset. See `projectToHookView` for
   * the projection contract.
   *
   * The live session objects are handed to the registry rather than a deep clone: the
   * registry writes columns and one residual document per run, so it reads each field once
   * and nothing outstays the synchronous write. The clone existed to turn `stepStates` into
   * an array for JSON, and `stepStates` is now rows.
   *
   * Log-and-continue survives for ONE failure class only: a lock another connection still held
   * after `STATE_DB_BUSY_TIMEOUT_MS` (`SQLITE_BUSY`/`SQLITE_LOCKED`, see
   * {@link isTransientLockError}). That class is transient because every persist writes the whole
   * live set, so the next one heals it. Everything else throws to the caller (R74): a constraint
   * violation recurs on every persist, so swallowing it once meant losing every save of the
   * process silently while the rows it collided with lived (P6.147). Callers that report a write
   * call {@link persistSessionsOrThrow}, which swallows nothing.
   */
  private async persistSessions(): Promise<void> {
    try {
      await this.persistSessionsOrThrow();
    } catch (error) {
      if (!isTransientLockError(error)) throw error;
      this.logger.error(
        `Failed to save sessions (lock held, the next persist rewrites them): ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  /**
   * The persist above, with the failure left for the caller to decide about.
   *
   * `architecture.md`'s state-mutation contract: persistence THROWS and the caller owns the
   * response. A caller whose reply renders what it wrote ("your remainder was applied") cannot
   * use {@link saveSessions}, which reports success over a held lock — the reply would show a
   * plan the rows do not hold, and the divergence would only surface on the next cold load.
   *
   * Persists run ONE AT A TIME. The write awaits `runRegistry.save` inside its transaction, so a
   * second persist starting in that gap (a fire-and-forget `persistSessionsAsync` from a lifecycle
   * promotion, say) met `cannot start a transaction within a transaction`, and its changes were
   * written by nobody. The swallow above hid that until R74 made it throw.
   */
  private persistSessionsOrThrow(): Promise<void> {
    const write = this.persistQueue.then(() => this.writeSessions());
    this.persistQueue = write.catch(() => undefined);
    return write;
  }

  /**
   * Persist what a mutator just changed, or put memory back where the rows are (R87, P6.185).
   *
   * The one path every awaited mutator persists through, in the state-mutation contract's order:
   * the mutator validates, takes its `snapshot`, mutates memory, and calls this; a persist that
   * rejects restores the snapshot and then rethrows, and the mutator logs success only once this
   * returns. Without the restore a rejected save left memory AHEAD of the rows, and a retry
   * answered from memory — a second `cancelChain` returned `true` from its "already cancelled"
   * early return and wrote nothing, so the run stayed `working` in `chain_runs` while this process
   * believed it cancelled. The rows are the truth: memory rolls back to them, never the reverse.
   *
   * `strict` persists through {@link persistSessionsOrThrow} (a held lock fails the call too);
   * otherwise through {@link saveSessions}, which reports success over a held lock — memory is
   * then kept, because the next persist writes the whole live set and heals the rows.
   */
  private async persistMutation(
    snapshot: MemorySnapshot,
    options: { strict?: boolean } = {}
  ): Promise<void> {
    try {
      await (options.strict === true ? this.persistSessionsOrThrow() : this.saveSessions());
    } catch (error) {
      snapshot.restore();
      this.logger.warn(
        `[ChainSessionStore] Save rejected; in-memory change rolled back: ${
          error instanceof Error ? error.message : String(error)
        }`
      );
      throw error;
    }
  }

  /**
   * A copy of one run's own state, restored IN PLACE: callers hold the session object itself
   * (`getSession` returns it), so a restore that swapped the map entry would leave them reading
   * the rejected change. The blueprint is shared, not copied: nothing after creation writes it.
   */
  private snapshotRun(session: ChainSession): MemorySnapshot {
    const { blueprint: _blueprint, ...own } = session;
    const copy = structuredClone(own);
    return {
      restore: () => {
        const target = session as unknown as Record<string, unknown>;
        for (const key of Object.keys(target)) {
          if (key !== 'blueprint' && !(key in copy)) delete target[key];
        }
        Object.assign(session, copy);
      },
    };
  }

  /**
   * A copy of WHICH runs this process holds and how they are indexed, for a mutator that adds or
   * removes a run (`createSession`, `clearSession`, `clearSessionsForChain`). The runs themselves
   * are kept by reference: adding or removing one does not change its contents.
   */
  private snapshotRunMembership(): MemorySnapshot {
    const sessions = new Map(this.activeSessions);
    const chainSessions = new Map(
      [...this.chainSessionMapping].map(([chainId, ids]) => [chainId, new Set(ids)] as const)
    );
    const baseChains = new Map(
      [...this.baseChainMapping].map(([baseId, runs]) => [baseId, [...runs]] as const)
    );
    const runToBase = new Map(this.runChainToBase);
    const unreserved = new Set(this.unreservedRuns);
    return {
      restore: () => {
        replaceMapContents(this.activeSessions, sessions);
        replaceMapContents(this.chainSessionMapping, chainSessions);
        replaceMapContents(this.baseChainMapping, baseChains);
        replaceMapContents(this.runChainToBase, runToBase);
        this.unreservedRuns.clear();
        for (const sessionId of unreserved) this.unreservedRuns.add(sessionId);
      },
    };
  }

  /** One transactional write of the live set; only {@link persistSessionsOrThrow} calls it. */
  private async writeSessions(): Promise<void> {
    const db = this.resolvedDbEngine;
    const sessions = Array.from(this.activeSessions.values());
    // An evicted session releases what a removed one does except its argument history, once this
    // persist returns (R116 amended).
    const evicted = emptyRunRelease('keep');
    if (!db) {
      // No DB engine wired — fall back to non-transactional save (test contexts).
      this.evictClaimedSessions(await this.runRegistry.save(sessions, this.runScope), evicted);
      this.unreservedRuns.clear();
      await this.releaseRemovedRuns(evicted);
      return;
    }
    // A run-number reservation reads `chain_runs` and then writes it: `immediate` makes the pair
    // one unit against another server's persist.
    const reserving = this.unreservedRuns.size > 0;
    db.beginTransaction(reserving ? 'immediate' : 'deferred');
    try {
      if (reserving) this.reserveRunNumbers(db);
      const claimedElsewhere = await this.runRegistry.save(sessions, this.runScope);
      // Evict BEFORE the projection so the hook view does not re-advertise a run this
      // process no longer owns.
      this.evictClaimedSessions(claimedElsewhere, evicted);
      this.projectToHookView(db);
      db.commit();
      if (reserving) this.unreservedRuns.clear();
    } catch (txError) {
      db.rollback();
      throw txError;
    }
    await this.releaseRemovedRuns(evicted);
  }

  /**
   * One chain-id space per `state.db` (R62): a new run's number is past the highest number ANY
   * owner's `chain_runs` row holds for its base chain id. The caller minted from this process's
   * memory, which cannot see a second live server's runs, so both servers minted `chain-x#1`.
   * Counted within the run's continuity scope, the unit every chain-id lookup filters by: a
   * `chain_id` resolves only among its own scope's runs, so another scope's `#1` names nothing here.
   * Must run inside the persist's `immediate` transaction, before the run's row is written.
   */
  private reserveRunNumbers(db: DatabasePort): void {
    for (const sessionId of this.unreservedRuns) {
      const session = this.activeSessions.get(sessionId);
      const minted = session === undefined ? undefined : parseRunNumber(session.chainId);
      if (session === undefined || minted === undefined) continue;
      const baseChainId = stripRunNumber(session.chainId);
      const held = db.query<{ chain_id: string }>(
        `SELECT chain_id FROM chain_runs
          WHERE base_chain_id = ? AND session_id != ?
            AND json_extract(state, '$.continuityScopeId') IS ?`,
        [baseChainId, sessionId, session.continuityScopeId ?? null]
      );
      const highest = Math.max(0, ...held.map((row) => parseRunNumber(row.chain_id) ?? 0));
      if (minted > highest) continue;
      this.renameNewRun(session, formatChainId(baseChainId, highest + 1));
    }
  }

  /**
   * Re-key a run no caller has addressed yet under its reserved chain id. The previous chain id
   * leaves the run indexes only when no other session still holds it (R123).
   */
  private renameNewRun(session: ChainSession, chainId: string): void {
    const previous = session.chainId;
    this.removeSessionFromRun(session.sessionId, previous);
    session.chainId = chainId;
    const sessionIds = this.chainSessionMapping.get(chainId) ?? new Set<string>();
    sessionIds.add(session.sessionId);
    this.chainSessionMapping.set(chainId, sessionIds);
    this.registerRunHistory(chainId);
    this.logger.debug(`[ChainSessionStore] Run ${previous} reserved as ${chainId}`);
  }

  /**
   * Project active canonical sessions into the per-row `chain_sessions` table.
   *
   * `chain_sessions` is a derived hook-read view of `chain_runs` + `chain_run_nodes`
   * (the SSOT). Those carry the full data model; this projection writes the active
   * hook-relevant subset as a single pre-shaped JSON row per run, so Python hooks get
   * the whole answer from one indexed PID-scoped SELECT rather than joining two tables
   * and re-deriving the ordinals themselves.
   *
   * Filter rule: a session is "active for hooks" while its run is not complete
   * (see `isSessionActiveForHooks`).
   * `run_owner_pid` is the server PID for cross-client isolation. `continuity_scope_id` is the
   * run's own scope: run numbers are counted per scope, so the PID, the chain id and the scope key
   * the row (R70).
   *
   * Owner rule (R61): the projection holds exactly the canonical owner's row for a run. A run this
   * process projects is one it owns in `chain_runs` (a claim rewrote the owner), so another PID's
   * row for the same run is the previous owner's, left stale; it is deleted here, keyed by chain id
   * AND the run's session id, because two servers mint run numbers independently and can both hold
   * a live `chain-x#1` of different runs.
   *
   * Must be called inside an active transaction. The caller (`persistSessions`)
   * owns the transaction boundary so blob save and projection succeed or fail
   * atomically.
   */
  private projectToHookView(db: DatabasePort): void {
    const activeRows = this.collectActiveSessionRows();
    db.run('DELETE FROM chain_sessions WHERE run_owner_pid = ?', [this.serverPid]);
    for (const row of activeRows) {
      db.run(
        `DELETE FROM chain_sessions
          WHERE chain_id = ? AND run_owner_pid != ? AND json_extract(state, '$.sessionId') = ?`,
        [row.chainId, this.serverPid, row.sessionId]
      );
      db.run(
        `INSERT INTO chain_sessions (run_owner_pid, organization_id, workspace_id, continuity_scope_id, chain_id, state, run_status, run_completed_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          this.serverPid,
          this.workspaceScope?.organizationId ?? null,
          this.workspaceScope?.workspaceId ?? null,
          row.continuityScopeId,
          row.chainId,
          row.state,
          row.runStatus,
          row.runCompletedAt,
        ]
      );
    }
  }

  /**
   * Collect active canonical sessions that need hook visibility.
   * A session is "active" while its run is not complete (`isSessionActiveForHooks`).
   */
  private collectActiveSessionRows(): Array<{
    sessionId: string;
    chainId: string;
    continuityScopeId: string;
    state: string;
    runStatus: ChainRunStatus;
    runCompletedAt: number | null;
  }> {
    const rows: Array<{
      sessionId: string;
      chainId: string;
      continuityScopeId: string;
      state: string;
      runStatus: ChainRunStatus;
      runCompletedAt: number | null;
    }> = [];
    for (const session of this.activeSessions.values()) {
      if (session.lifecycle !== 'canonical') continue;
      if (!this.isSessionActiveForHooks(session)) continue;
      const runStatus = session.runStatus;
      const shownNodeId = resolveShownReview(session);
      rows.push({
        sessionId: session.sessionId,
        chainId: session.chainId,
        // The run's own scope (R70): one process serving two workspaces holds `chain-x#1` in
        // each, so the projection's key needs it. Resolved as `createSession` resolves it.
        continuityScopeId: resolveContinuityScopeId(session),
        runStatus,
        runCompletedAt: session.runCompletedAt ?? null,
        state: JSON.stringify({
          sessionId: session.sessionId,
          chainId: session.chainId,
          // Positions, not identities: this blob is read by Python hooks across three repos,
          // and its integer keys are a cross-repo contract. Derived here so the store can be
          // node-keyed without the projection changing a byte.
          currentStep: currentOrdinal(session.state.nodes, session.state.currentNodeId),
          totalSteps: totalOf(session.state.nodes),
          lastActivity: session.lastActivity,
          // The key is the hooks' contract (`hooks/lib/db_reader.py`); the value is the review
          // the client is shown, read by the node `resolveShownReview` names.
          currentStepReview:
            shownNodeId === undefined ? null : (session.reviews?.[shownNodeId] ?? null),
          pendingShellVerification: session.pendingShellVerification ?? null,
          runStatus,
          runCompletedAt: session.runCompletedAt ?? null,
        }),
      });
    }
    return rows;
  }

  /**
   * Whether a session should be visible to hooks: exactly while the run is not complete (R30).
   * `isRunComplete` is the one derivation, so a run standing on its last step, and a run held
   * open after walking past it (`currentStep = totalSteps + 1`), both stay projected.
   */
  private isSessionActiveForHooks(session: ChainSession): boolean {
    return !isRunComplete(session);
  }

  /**
   * Collect run_owner_pid values from a table where the PID is dead (not alive).
   * Skips non-numeric IDs and optionally skips the current process PID.
   */
  // DB engine accessed via this.resolvedDbEngine (set in initialize or setDatabasePort)

  private collectDeadRunOwnerPids(db: DatabasePort, query: string, skipOwnPid: boolean): string[] {
    const rows = db.query<{ run_owner_pid: string }>(query);
    const dead: string[] = [];
    for (const row of rows) {
      const pid = parseInt(row.run_owner_pid, 10);
      if (isNaN(pid)) continue;
      if (skipOwnPid && row.run_owner_pid === this.serverPid) continue;
      try {
        process.kill(pid, 0);
      } catch {
        dead.push(row.run_owner_pid);
      }
    }
    return dead;
  }

  /**
   * Remove rows belonging to dead server processes from `chain_sessions` and from the
   * run tables. Called once at startup to prevent stale rows from blocking hooks or
   * consuming storage.
   *
   * The run-table delete is delegated to the registry rather than issued here. This module
   * deleting rows it does not own was a declared foreign-writer exception on the retired
   * blob table; recreating it against the new tables would have carried the exception across
   * a rewrite that could simply not need it.
   */
  private cleanupStalePidRows(): void {
    const db = this.resolvedDbEngine;
    if (!db) return;

    try {
      // Clean chain_sessions (per-row PID table for hooks)
      const staleSessions = this.collectDeadRunOwnerPids(
        db,
        'SELECT DISTINCT run_owner_pid FROM chain_sessions',
        false
      );
      for (const pid of staleSessions) {
        db.run('DELETE FROM chain_sessions WHERE run_owner_pid = ?', [pid]);
      }

      // Clean the PID-scoped run tables. The former `WHERE tenant_id = 'default'` sweep is gone
      // with the v20 rename: the column carries no DEFAULT, so nothing can mint a non-PID owner.
      const staleRuns = this.collectDeadRunOwnerPids(
        db,
        'SELECT DISTINCT run_owner_pid FROM chain_runs',
        true
      );
      this.runRegistry.deleteRunsForOwners(staleRuns);

      const totalCleaned = staleSessions.length + staleRuns.length;
      if (totalCleaned > 0) {
        this.logger.debug(`Cleaned up ${totalCleaned} stale PID rows from session/registry tables`);
      }
    } catch (error) {
      this.logger.debug(
        `cleanupStalePidRows failed: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }

  /** A background persist (lifecycle promotion): no caller waits, so a failure is logged. */
  private persistSessionsAsync(context: string): void {
    this.saveSessions().catch((error) => {
      this.logger.warn(
        `[ChainSessionStore] Failed to persist sessions (${context}): ${
          error instanceof Error ? error.message : String(error)
        }`
      );
    });
  }

  /**
   * Create a new chain session
   */
  async createSession(
    sessionId: string,
    chainId: string,
    totalSteps: number,
    originalArgs: Record<string, any> = {},
    options?: StateStoreOptions & { blueprint?: SessionBlueprint; nodes?: ChainNode[] }
  ): Promise<ChainSession> {
    await this.initPromise;
    const resolvedScope = options?.continuityScopeId ?? resolveContinuityScopeId(options);
    const nodes = this.resolveCreationNodes(chainId, totalSteps, options?.nodes);
    const snapshot = this.snapshotRunMembership();
    const session: ChainSession = {
      sessionId,
      chainId,
      state: {
        // A run starts standing at its first node; a zero-node run is complete on arrival.
        currentNodeId: nodes[0]?.id ?? null,
        nodes,
        lastUpdated: Date.now(),
        stepStates: new Map<string, StepMetadata>(),
      },
      executionOrder: [],
      startTime: Date.now(),
      lastActivity: Date.now(),
      originalArgs,
      continuityScopeId: resolvedScope,
      ...(options?.blueprint !== undefined && {
        blueprint: this.cloneBlueprint(options.blueprint),
      }),
      lifecycle: 'canonical',
      runStatus: 'working',
    };

    this.activeSessions.set(sessionId, session);

    // Track chain to session mapping
    if (!this.chainSessionMapping.has(chainId)) {
      this.chainSessionMapping.set(chainId, new Set());
    }
    this.chainSessionMapping.get(chainId)!.add(sessionId);

    const baseChainId = this.registerRunHistory(chainId);
    const release = emptyRunRelease();
    this.pruneExcessRuns(baseChainId, release);

    // The persist reserves the run number across every owner and may re-mint `session.chainId`
    // (R62): callers read the chain id off the returned session.
    this.unreservedRuns.add(sessionId);
    await this.persistMutation(snapshot);
    await this.releaseRemovedRuns(release);

    this.logger.debug(
      `Created chain session ${sessionId} for chain ${chainId} with ${totalSteps} steps`
    );
    return session;
  }

  /**
   * Resolve the frozen node list for a new run.
   *
   * Explicit `nodes` win — they carry the ids minted at parse time, which is the only way an
   * authored `id:` reaches the store. Callers that know only a count (tests, gated single
   * prompts, any path with no parsed chain) get synthetic `n1..nK`, which keeps the legacy
   * `createSession(id, chain, totalSteps)` shape working. A mismatch between the two is a
   * caller bug, so it is logged rather than silently reconciled.
   */
  private resolveCreationNodes(
    chainId: string,
    totalSteps: number,
    explicitNodes?: ChainNode[]
  ): ChainNode[] {
    if (explicitNodes !== undefined && explicitNodes.length > 0) {
      if (totalSteps > 0 && explicitNodes.length !== totalSteps) {
        this.logger.warn(
          `[ChainSessionStore] Node list length ${explicitNodes.length} disagrees with totalSteps ${totalSteps} for chain ${chainId}; using the node list`
        );
      }
      // `origin` is normalized on entry rather than left for readers to default. The field is
      // optional on `ChainNode` because four unrelated sites mint one, but the store owns the
      // run's node list, so a node inside a session always carries its provenance — otherwise
      // the same node reads `undefined` in memory and 'planned' after a cold load, and every
      // consumer has to know which side of the round-trip it is holding.
      return explicitNodes.map((node) => ({ ...node, origin: node.origin ?? 'planned' }));
    }

    const count = Math.max(0, totalSteps);
    return mintSequentialIds(count).map((id, index) => ({
      id,
      promptId: chainId,
      stepName: `Step ${index + 1}`,
      origin: 'planned' as const,
    }));
  }

  /**
   * Get session by ID
   */
  getSession(sessionId: string, scope?: StateStoreOptions): ChainSession | undefined {
    const session = this.activeSessions.get(sessionId);
    if (session) {
      // Scope filtering: if scope provided, only return if scope matches
      if (scope) {
        const resolvedScope = scope.continuityScopeId ?? resolveContinuityScopeId(scope);
        if (session.continuityScopeId && session.continuityScopeId !== resolvedScope) {
          return undefined;
        }
      }
      // Repair a run pointing at a node that is not in its own list (corrupt or partially
      // written state) by returning it to the first node — the position-keyed equivalent of
      // the old `currentStep < 1` repair. `null` is left alone: that is a completed run, not
      // a broken pointer.
      const { nodes, currentNodeId } = session.state;
      if (nodes.length > 0 && currentNodeId !== null && ordinalOf(nodes, currentNodeId) === -1) {
        session.state.currentNodeId = nodes[0]?.id ?? null;
      }
      session.lastActivity = Date.now();
      this.promoteSessionLifecycle(session, 'session-id lookup');
    }
    return session;
  }

  /**
   * Set step state for a specific step
   */
  setStepState(
    sessionId: string,
    nodeId: string,
    milestone: StepMilestone,
    isPlaceholder: boolean = false,
    declaredSections?: readonly string[]
  ): boolean {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger?.warn(
        `[StepLifecycle] Cannot set step state for non-existent session: ${sessionId}`
      );
      return false;
    }

    if (!session.state.stepStates) {
      session.state.stepStates = new Map<string, StepMetadata>();
    }

    const existing = session.state.stepStates.get(nodeId);
    const now = Date.now();

    const metadata: StepMetadata = {
      state: lifecycleForMilestone(milestone),
      isPlaceholder,
      ...(existing?.renderedAt !== undefined
        ? { renderedAt: existing.renderedAt }
        : milestone === 'rendered'
          ? { renderedAt: now }
          : {}),
      ...(milestone === 'responded'
        ? { respondedAt: now }
        : existing?.respondedAt !== undefined
          ? { respondedAt: existing.respondedAt }
          : {}),
      ...(milestone === 'completed'
        ? { completedAt: now }
        : existing?.completedAt !== undefined
          ? { completedAt: existing.completedAt }
          : {}),
      // Sticky like the timestamps above: a declaration is recorded once, at render, and every
      // later milestone for the same node carries it forward. Dropping it on 'responded' would
      // erase the record precisely when the verification stage needs to read it.
      ...(declaredSections !== undefined
        ? { declaredSections: [...declaredSections] }
        : existing?.declaredSections !== undefined
          ? { declaredSections: existing.declaredSections }
          : {}),
      // Sticky for the same reason: a detached node is spawned once, at render, and the run's
      // completion guard reads it at every later milestone (Tier 4).
      ...(existing?.spawnedAt !== undefined ? { spawnedAt: existing.spawnedAt } : {}),
    };

    session.state.stepStates.set(nodeId, metadata);

    this.logger?.debug(
      `[StepLifecycle] Step ${nodeId} milestone ${milestone} -> state ${metadata.state} (placeholder: ${isPlaceholder})`
    );
    return true;
  }

  /**
   * Record a render's declaration for `nodeId` without moving its lifecycle (P4.115).
   *
   * The gate-review render is the only render a blocking-gate step gets, and it can repeat — a
   * retry re-renders the review after the step's answer was captured. `setStepState(…,
   * 'rendered')` there would walk a captured node back to `rendered`, so an existing record keeps
   * its state and gains the declaration; only a node nothing has recorded yet is marked rendered.
   */
  recordStepDeclaration(
    sessionId: string,
    nodeId: string,
    declaredSections: readonly string[]
  ): boolean {
    const existing = this.activeSessions.get(sessionId)?.state.stepStates?.get(nodeId);
    if (existing === undefined) {
      return this.setStepState(sessionId, nodeId, 'rendered', false, declaredSections);
    }
    this.activeSessions
      .get(sessionId)
      ?.state.stepStates?.set(nodeId, { ...existing, declaredSections: [...declaredSections] });
    return true;
  }

  /**
   * Get step state for a specific step
   */
  getStepState(sessionId: string, nodeId: string): StepMetadata | undefined {
    const session = this.activeSessions.get(sessionId);
    if (!session?.state.stepStates) {
      return undefined;
    }
    return session.state.stepStates.get(nodeId);
  }

  /**
   * Transition step to a new state.
   *
   * Enforces step-lifecycle stickiness: a step in terminal `completed`
   * cannot be overwritten. Re-asserting the same terminal state is a no-op
   * (returns true to keep callers idempotent).
   */
  async transitionStepState(
    sessionId: string,
    nodeId: string,
    newMilestone: StepMilestone,
    isPlaceholder: boolean = false
  ): Promise<boolean> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger?.warn(
        `[StepLifecycle] Cannot transition step state for non-existent session: ${sessionId}`
      );
      return false;
    }

    const currentMetadata = this.getStepState(sessionId, nodeId);
    const currentState = currentMetadata?.state;

    // Stickiness: refuse to overwrite a terminal step state with a different state. Re-asserting
    // the same terminal value stays a no-op success, which is why the comparison is against the
    // lifecycle the incoming milestone implies rather than against the milestone name.
    if (
      currentState !== undefined &&
      TERMINAL_STEP_LIFECYCLES.has(currentState) &&
      lifecycleForMilestone(newMilestone) !== currentState
    ) {
      this.logger.warn(
        `[StepLifecycle] Refusing to transition step ${nodeId} from terminal ${currentState} to ${newMilestone} (session ${sessionId})`
      );
      return false;
    }

    const fromLabel = currentState ?? 'NONE';
    const snapshot = this.snapshotRun(session);
    this.setStepState(sessionId, nodeId, newMilestone, isPlaceholder);

    await this.persistMutation(snapshot);
    this.logger.debug(
      `[StepLifecycle] Transitioned step ${nodeId} from ${fromLabel} to ${newMilestone}`
    );

    return true;
  }

  /**
   * Transition the run-level lifecycle status. Refuses transitions out of terminal
   * states (completed/failed/cancelled). Re-asserting the same terminal status is
   * a no-op (returns true) to keep callers idempotent.
   */
  async transitionRunStatus(
    sessionId: string,
    target: ChainRunStatus,
    scope?: StateStoreOptions
  ): Promise<boolean> {
    const session = this.getSessionForMutation(sessionId, scope);
    if (session === undefined) {
      this.logger.warn(
        `[ChainRunStatus] Cannot transition run status for non-existent or out-of-scope session: ${sessionId}`
      );
      return false;
    }

    const currentStatus = session.runStatus;

    if (currentStatus === target) {
      return true;
    }

    if (isTerminalRunStatus(currentStatus)) {
      this.logger.warn(
        `[ChainRunStatus] Refusing to transition session ${sessionId} from terminal status '${currentStatus}' to '${target}'`
      );
      return false;
    }

    // The close guard. A run may not COMPLETE while a detached node it spawned has not reported
    // (Tier 4), or while any review of one of its nodes is open (row 4.8, P4.157): completing
    // would announce a finished run to every hook and client while a result or a verdict it still
    // needs is on its way, and that answer would then have no live run to land on. Only
    // `completed` is held. `cancelled` and `failed` stay open on purpose — they are how an
    // operator ends a run whose worker will never report, so holding them too would leave a lost
    // worker with no exit. A node the run never spawned is not owed anything and is not counted.
    if (target === 'completed') {
      const owed = nodesHoldingRunOpen(session);
      if (owed.length > 0) {
        this.logger.info(
          `[ChainRunStatus] Holding session ${sessionId} open: node(s) ${owed.join(', ')} not yet reported or under review`
        );
        return false;
      }
    }

    const snapshot = this.snapshotRun(session);
    session.runStatus = target;
    if (isTerminalRunStatus(target)) {
      session.runCompletedAt = Date.now();
    }
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);
    this.logger.debug(
      `[ChainRunStatus] Transitioned session ${sessionId} from '${currentStatus}' to '${target}'`
    );
    await this.announceRunTerminal(session, target);
    return true;
  }

  /**
   * Mark a detached (`await: run`) node SPAWNED — its brief was just rendered to the client.
   *
   * The one way a node enters the detached lifecycle, and the fact the completion guard in
   * {@link transitionRunStatus} reads: from here until the node holds a real captured output, the
   * run may pass it but may not complete. Idempotent — a re-render keeps the first spawn time,
   * which `setStepState` then carries forward across every later milestone. Awaited persistence:
   * the obligation must survive the process, because the worker's result can arrive after it.
   *
   * @returns false when the session does not exist (the caller logs; nothing was recorded).
   */
  async markNodeSpawned(sessionId: string, nodeId: string): Promise<boolean> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      this.logger.warn(`[StepLifecycle] Cannot mark ${nodeId} spawned: no session ${sessionId}`);
      return false;
    }
    const snapshot = this.snapshotRun(session);
    session.state.stepStates ??= new Map<string, StepMetadata>();
    const existing = session.state.stepStates.get(nodeId);
    if (existing?.spawnedAt !== undefined) {
      return true;
    }
    const now = Date.now();
    session.state.stepStates.set(nodeId, {
      ...(existing ?? { state: lifecycleForMilestone('rendered'), isPlaceholder: false }),
      renderedAt: existing?.renderedAt ?? now,
      spawnedAt: now,
    });
    session.lastActivity = now;
    await this.persistMutation(snapshot);
    return true;
  }

  /**
   * Complete a run standing past its last node, once nothing holds it (P4.157 / R12).
   *
   * The ONE place a run is completed normally. {@link advanceStep} only moves the run; completing
   * there latched `completed` before the phase guard (stage 19) graded the very answer that
   * walked the run off its last node, so one reply announced `chain/complete` and opened a
   * structural review. The pipeline asks here after its stage loop on every chain request, and
   * stage 16 asks on the late-report calls it answers itself; {@link transitionRunStatus}
   * still decides. A no-op (false) for a run still standing on a node, and for one still held.
   */
  async completeHeldRun(sessionId: string): Promise<boolean> {
    // Undefined (no session) and a node id (still standing somewhere) both answer "not held".
    if (this.activeSessions.get(sessionId)?.state.currentNodeId !== null) {
      return false;
    }
    return this.transitionRunStatus(sessionId, 'completed');
  }

  /**
   * Cancel a chain session. Idempotent on already-cancelled sessions. Refuses
   * sessions already in terminal completed/failed (a terminal state cannot be
   * overridden by cancel — call sites should check status first).
   *
   * Side effects:
   *  - runStatus → 'cancelled'
   *  - non-terminal step states (PENDING/RENDERED/RESPONSE_CAPTURED) → COMPLETED is reserved
   *    for the SEP-1686 StepLifecycle migration; here we leave step metadata untouched and
   *    rely on runStatus terminality + step-level stickiness to prevent further progression.
   */
  /**
   * Drop sessions another server has claimed (2A). The registry reports them from `save`;
   * the in-memory copy here is stale by definition, and keeping it would let this process
   * advance a run whose row it can no longer write. What the session held in this process (step
   * results, named outputs, run-scoped gates) is queued on `release`, which the persist drains
   * only after it commits (R116); its argument history stays (`release.argumentHistory: 'keep'`).
   */
  private evictClaimedSessions(sessionIds: readonly string[], release: RunRelease): void {
    for (const sessionId of sessionIds) {
      const session = this.activeSessions.get(sessionId);
      if (session === undefined) continue;
      this.removeSessionArtifacts(sessionId, release);
      this.removeSessionFromRun(sessionId, session.chainId);
      this.logger.info(
        `[Handoff] Session ${sessionId} (${session.chainId}) claimed by another server; evicted`
      );
    }
  }

  /**
   * Mint a single-use handoff token for a live run (2A). Minting again rotates the token —
   * the previous one can no longer claim. Returns undefined for an unknown, out-of-scope, or
   * terminal run.
   */
  async mintHandoffToken(
    sessionId: string,
    scope?: StateStoreOptions
  ): Promise<{ token: string; chainId: string; sessionId: string } | undefined> {
    const session = this.getSessionForMutation(sessionId, scope);
    if (session === undefined) return undefined;
    if (isTerminalRunStatus(session.runStatus)) {
      this.logger.warn(`[Handoff] Refusing to mint for terminal session ${sessionId}`);
      return undefined;
    }
    // 20 random bytes, base64url: unguessable, shell/URL safe, pasted exactly once.
    const token = `hnd_${randomBytes(20).toString('base64url')}`;
    const snapshot = this.snapshotRun(session);
    session.handoffToken = token;
    session.lastActivity = Date.now();
    await this.persistMutation(snapshot);
    this.logger.info(`[Handoff] Minted token for session ${sessionId} (${session.chainId})`);
    return { token, chainId: session.chainId, sessionId };
  }

  /**
   * Claim a run minted elsewhere (2A): transfer its row to this server, load it into memory
   * as a dormant session, and persist. Refuses when the row has no blueprint (OQ-1) — nothing
   * here could resume it.
   */
  async claimHandoff(token: string): Promise<ChainHandoffClaimResult> {
    await this.initPromise;
    const heldChainId = this.findHeldChainIdForToken(token);
    if (heldChainId !== undefined) {
      this.logger.warn(`[Handoff] Refusing claim: ${heldChainId} already names another run here`);
      return { status: 'chain-id-held', chainId: heldChainId };
    }
    const result = this.runRegistry.claimRunByToken(token, this.runScope);
    if (result.status !== 'claimed') return result;

    const session = result.session;
    if (!session.blueprint) {
      this.logger.warn(`[Handoff] Claimed ${session.chainId} carries no blueprint; refusing`);
      return { status: 'no-blueprint', chainId: session.chainId };
    }
    // The claim above is its own committed write: the row is this server's now, so a rejected
    // save below restores the run's own fields but keeps it held, which is what the rows say.
    const snapshot = this.snapshotRun(session);
    if (!(session.state.stepStates instanceof Map)) session.state.stepStates = new Map();
    session.lifecycle = 'dormant';
    session.lastActivity = Date.now();
    this.activeSessions.set(session.sessionId, session);
    const sessionIds = this.chainSessionMapping.get(session.chainId) ?? new Set<string>();
    sessionIds.add(session.sessionId);
    this.chainSessionMapping.set(session.chainId, sessionIds);
    this.ensureRunMappingConsistency();
    await this.persistMutation(snapshot);
    this.logger.info(`[Handoff] Claimed ${session.chainId} (session ${session.sessionId})`);
    return result;
  }

  /**
   * The chain id of the run `token` hands off, when this server already holds a DIFFERENT run
   * under it in the same continuity scope (a pair minted before R62 reserved run numbers across
   * owners). Read before the transfer, so a refused claim leaves the run with its owner.
   */
  private findHeldChainIdForToken(token: string): string | undefined {
    const row = this.resolvedDbEngine?.queryOne<{
      session_id: string;
      chain_id: string;
      scope: string | null;
    }>(
      `SELECT session_id, chain_id, json_extract(state, '$.continuityScopeId') AS scope
         FROM chain_runs WHERE handoff_token = ?`,
      [token]
    );
    if (row === null || row === undefined) return undefined;
    const held = [...(this.chainSessionMapping.get(row.chain_id) ?? [])].some((sessionId) => {
      const session = this.activeSessions.get(sessionId);
      return sessionId !== row.session_id && (session?.continuityScopeId ?? null) === row.scope;
    });
    return held ? row.chain_id : undefined;
  }

  async cancelChain(sessionId: string, scope?: StateStoreOptions): Promise<boolean> {
    const session = this.getSessionForMutation(sessionId, scope);
    if (session === undefined) {
      this.logger.warn(
        `[ChainRunStatus] Cannot cancel non-existent or out-of-scope session: ${sessionId}`
      );
      return false;
    }

    const currentStatus = session.runStatus;
    if (currentStatus === 'cancelled') {
      return true;
    }
    if (currentStatus === 'completed' || currentStatus === 'failed') {
      this.logger.warn(
        `[ChainRunStatus] Refusing to cancel session ${sessionId} in terminal status '${currentStatus}'`
      );
      return false;
    }

    const snapshot = this.snapshotRun(session);
    session.runStatus = 'cancelled';
    session.runCompletedAt = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);
    this.logger.info(`[ChainRunStatus] Cancelled session ${sessionId} (was '${currentStatus}')`);
    await this.announceRunTerminal(session, 'cancelled');
    return true;
  }

  /**
   * Announce that a run reached a terminal status, to hook consumers and to the client.
   *
   * Called from the two methods that WRITE `runStatus` — `transitionRunStatus` and
   * `cancelChain` — each after its own `saveSessions()` resolves, so a client is never told a
   * run ended before the row saying so is durable. Both writers return early when the status is
   * already what is being set and refuse a transition out of a terminal status, which is what
   * makes this exactly-once per run rather than once per caller: `advanceStep` re-advancing past
   * the same final node, or a second `cancelChain`, reaches neither call.
   *
   * A non-terminal transition announces nothing; `working -> working` is not an event.
   *
   * One catch around both channels, matching `GateVerdictProcessor.emitGateEvents`. An
   * announcement that fails must not turn a persisted terminal status into a failed call —
   * that would make the run look live to its next caller.
   */
  private async announceRunTerminal(session: ChainSession, status: ChainRunStatus): Promise<void> {
    if (!isTerminalRunStatus(status)) return;
    this.notifyRunEnded(session.sessionId);
    if (this.hookRegistry === undefined && this.notificationEmitter === undefined) return;

    // `isTerminalRunStatus` is a boolean predicate over the shared TERMINAL_RUN_STATUSES list,
    // not a type guard, so the narrowing it just proved has to be restated for the payload.
    const terminalStatus = status as ChainCompleteNotification['status'];
    const { chainId } = session;
    const totalSteps = totalOf(session.state.nodes);

    try {
      const hookContext: PipelineHookContext = {
        executionId: session.sessionId,
        executionType: 'chain',
        chainId,
        currentStep: currentOrdinal(session.state.nodes, session.state.currentNodeId),
        frameworkEnabled: false,
      };

      if (status === 'completed') {
        await this.hookRegistry?.emitChainComplete(chainId, hookContext);
      } else {
        await this.hookRegistry?.emitChainFailed(chainId, `run ${status}`, hookContext);
      }

      this.notificationEmitter?.emitChainComplete({
        chainId,
        totalSteps,
        status: terminalStatus,
      });
    } catch (error) {
      this.logger.warn(
        `[ChainRunStatus] Failed to announce terminal status '${status}' for ${chainId}: ${
          error instanceof Error ? error.message : String(error)
        }`
      );
    }
  }

  /**
   * Resolve a session for state-mutating operations with optional scope filtering.
   * Returns undefined if session does not exist or scope mismatch.
   */
  private getSessionForMutation(
    sessionId: string,
    scope?: StateStoreOptions
  ): ChainSession | undefined {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) return undefined;
    if (scope !== undefined) {
      const resolvedScope = scope.continuityScopeId ?? resolveContinuityScopeId(scope);
      const sessionScope = session.continuityScopeId;
      if (sessionScope !== undefined && sessionScope !== resolvedScope) {
        return undefined;
      }
    }
    return session;
  }

  /**
   * Check if a step is complete (not a placeholder and in COMPLETED state)
   */
  isStepComplete(sessionId: string, nodeId: string): boolean {
    const metadata = this.getStepState(sessionId, nodeId);
    return metadata?.state === 'completed' && !metadata.isPlaceholder;
  }

  /**
   * Update session state after step rendering or completion
   * IMPORTANT: This method now handles both rendering (template storage) and completion
   */
  async updateSessionState(
    sessionId: string,
    nodeId: string,
    stepResult: string,
    stepMetadata?: Record<string, any>
  ): Promise<boolean> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      if (this.logger) {
        this.logger.warn(`Attempted to update non-existent session: ${sessionId}`);
      }
      return false;
    }

    const metadataRecord = {
      ...(stepMetadata || {}),
      isPlaceholder: stepMetadata?.['isPlaceholder'] ?? false,
      storedAt: Date.now(),
    };

    const isPlaceholder = metadataRecord.isPlaceholder;
    const snapshot = this.snapshotRun(session);

    // Determine the appropriate state based on whether this is a placeholder
    const milestone: StepMilestone = isPlaceholder ? 'rendered' : 'responded';

    // Update step state tracking. `declaredSections` is deliberately NOT threaded here:
    // 18-execution-stage records it directly at render time, which is the only moment the fact
    // exists. A second write path through this metadata bag would be a second writer for one
    // column, and setStepState already carries the recorded value forward across milestones.
    this.setStepState(sessionId, nodeId, milestone, isPlaceholder);

    // NOTE: Step advancement is now handled by advanceStep() which should be called
    // ONLY after gate validation passes (or if no gates are configured).
    // This prevents the bug where retry would skip to the next step.
    this.logger?.debug(
      `[StepLifecycle] Step ${nodeId} ${isPlaceholder ? 'rendered as placeholder' : 'response captured'}, ` +
        `run remains at ${session.state.currentNodeId ?? 'complete'} (advancement deferred to advanceStep())`
    );

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);

    // The result lands in stores a snapshot cannot roll back, so only once the rows hold the
    // step's new milestone (R93).
    await this.persistStepResult(
      session,
      nodeId,
      stepResult,
      metadataRecord,
      metadataRecord.isPlaceholder
    );

    return true;
  }

  // `updateStepResult` lived here and was deleted 2026-09-21 (P4.91). It answered the same
  // question as `updateSessionState` above — write a step's result and metadata, move the step's
  // lifecycle, persist — and only a test ever called it. Its one behavioural difference was
  // merging the metadata already stored for the node, which is the opposite of what the live
  // capture path wants: the placeholder write and the real-response write are two different
  // facts about a step, and carrying `placeholderSource` forward onto real output would make the
  // captured step describe itself as a placeholder. `TextReferenceStore.getChainStepMetadata`
  // went with it — this was its only caller, and nothing else asked that question.

  /**
   * Mark a step as COMPLETED and advance the step counter
   * This should be called AFTER the step response has been captured and validated
   */
  async completeStep(
    sessionId: string,
    nodeId: string,
    options?: { preservePlaceholder?: boolean }
  ): Promise<boolean> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger?.warn(
        `[StepLifecycle] Cannot complete step for non-existent session: ${sessionId}`
      );
      return false;
    }

    const existingMetadata = this.getStepState(sessionId, nodeId);
    const preservePlaceholder = Boolean(options?.preservePlaceholder);
    const isPlaceholder = preservePlaceholder ? Boolean(existingMetadata?.isPlaceholder) : false;
    const snapshot = this.snapshotRun(session);

    // Transition to COMPLETED state while respecting placeholder metadata when requested
    this.setStepState(sessionId, nodeId, 'completed', isPlaceholder);

    // NOTE: Step advancement is now handled by advanceStep() which should be called
    // ONLY after gate validation passes. This prevents the retry-skip bug.
    this.logger?.debug(
      `[StepLifecycle] Step ${nodeId} marked COMPLETED${isPlaceholder ? ' (placeholder)' : ''}, ` +
        `run remains at ${session.state.currentNodeId ?? 'complete'} (call advanceStep() to advance)`
    );

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);
    return true;
  }

  /**
   * Advance past `nodeId` after gate validation passes.
   * This should be called ONLY when:
   * - Gate review passes (PASS verdict)
   * - No gates are configured for this step
   * - Enforcement mode is advisory/informational (non-blocking)
   *
   * @param sessionId - The session identifier
   * @param nodeId - The node that was completed (the run moves to the node after it)
   * @returns the node now current plus its derived ordinal, or false if session not found
   */
  async advanceStep(
    sessionId: string,
    nodeId: string
  ): Promise<{ nodeId: string | null; ordinal: number } | false> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger?.warn(
        `[StepLifecycle] Cannot advance step for non-existent session: ${sessionId}`
      );
      return false;
    }

    const nodes = session.state.nodes;
    const here = currentOrdinal(nodes, session.state.currentNodeId);
    const target = ordinalOf(nodes, nodeId);

    // Double-advance guard, now a position comparison between two derived ordinals rather than
    // a comparison against a stored counter. An unresolvable `nodeId` scores -1 and so lands in
    // this branch, reproducing the old no-op-on-garbage behaviour rather than advancing blind.
    if (here > target) {
      this.logger?.debug(
        `[StepLifecycle] Node ${nodeId || '(unresolved)'} already passed, run is at ordinal ${here}`
      );
      return { nodeId: session.state.currentNodeId, ordinal: here };
    }

    // `null` when `nodeId` is terminal: the run has moved past its last node.
    //
    // P4: skipped nodes are passed over here, INSIDE the single traversal owner, so the
    // run reaches its real end — a run whose trailing nodes were all skipped stands past its last
    // node after this advance (and `completeHeldRun` completes it) rather than parking on a node
    // nothing will ever render. Skipped nodes are deliberately NOT appended to `executionOrder`: that list is the
    // record of what the run actually executed, and it is read to reconstruct step results, so a
    // node with no result in it would read as an executed step with a missing response.
    const snapshot = this.snapshotRun(session);
    let next = nextAfter(nodes, nodeId);
    let skippedPast = 0;
    while (next !== null && session.state.stepStates?.get(next)?.state === 'skipped') {
      skippedPast += 1;
      next = nextAfter(nodes, next);
    }
    if (skippedPast > 0) {
      this.logger.debug(
        `[StepLifecycle] Passed ${skippedPast} skipped node(s) after ${nodeId} (session ${sessionId})`
      );
    }

    session.state.currentNodeId = next;
    if (!session.executionOrder.includes(nodeId)) {
      session.executionOrder.push(nodeId);
    }

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    const ordinal = currentOrdinal(nodes, next);

    // No completion here: advancing past the terminal node leaves the run standing on no node
    // with a non-terminal status, and `completeHeldRun` — asked after the call is graded — decides
    // whether it is finished (P4.157 / R12).
    await this.persistMutation(snapshot);
    this.logger?.debug(
      `[StepLifecycle] Advanced past node ${nodeId} to ${next ?? 'run-complete'} (ordinal ${ordinal})`
    );

    return { nodeId: next, ordinal };
  }

  /**
   * Insert a new node immediately after `afterNodeId` (P4 adaptive mutation).
   *
   * Lives beside `advanceStep` because the run's node list has exactly one owner, and an
   * insertion is a traversal-affecting write: the inserted node becomes the natural `nextAfter`
   * of the node the run is standing at, which is what makes it the next CTA with no extra
   * round-trip.
   *
   * Returns the minted node, or `null` when the insertion was refused. `null` rather than a
   * throw matches this store's posture everywhere else (`advanceStep`, `completeStep`,
   * `setStepState` all return a falsy value and warn) — but it is still an OBSERVABLE failure,
   * which a silent no-op returning a fabricated node would not be.
   *
   * Refused when:
   *  - the session does not exist
   *  - the run is in a terminal status (nothing will ever reach the new node)
   *  - `afterNodeId` is not in the run's node list
   *  - `afterNodeId` sits strictly BEHIND the node the run is standing at, which would place the
   *    new node before `currentNodeId` where traversal has already passed. Inserting after the
   *    CURRENT node is the intended case and is allowed.
   *
   * The new id is minted through `mintInsertionId`, so existing node ids are never renumbered —
   * every gate target, execution record and `executionOrder` entry addressed by id stays valid.
   */
  async insertNodeAfter(
    sessionId: string,
    afterNodeId: string,
    spec: {
      stepName: string;
      promptId: string;
      origin?: 'planned' | 'inserted';
      /** The declared unknown that motivated the insertion; stored so the per-unknown-id
       *  insertion cap can be recomputed from persisted rows after a cold load. */
      unknownId?: string;
    }
  ): Promise<ChainNode | null> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      this.logger.warn(
        `[ChainMutation] Cannot insert node into non-existent session: ${sessionId}`
      );
      return null;
    }

    if (isTerminalRunStatus(session.runStatus)) {
      this.logger.warn(
        `[ChainMutation] Refusing to insert after ${afterNodeId}: session ${sessionId} is terminal ('${session.runStatus}')`
      );
      return null;
    }

    const nodes = session.state.nodes;
    const anchor = ordinalOf(nodes, afterNodeId);
    if (anchor === -1) {
      this.logger.warn(
        `[ChainMutation] Refusing to insert: node ${afterNodeId} is not in session ${sessionId}`
      );
      return null;
    }

    const here = currentOrdinal(nodes, session.state.currentNodeId);
    if (anchor < here) {
      this.logger.warn(
        `[ChainMutation] Refusing to insert after ${afterNodeId} (ordinal ${anchor}): run is already at ordinal ${here}, so the new node would never be reached`
      );
      return null;
    }

    const nodeId = mintInsertionId(
      spec.unknownId !== undefined ? `inv-${spec.unknownId}` : spec.stepName,
      nodes.map((node) => node.id)
    );
    const inserted: ChainNode = {
      id: nodeId,
      promptId: spec.promptId,
      stepName: spec.stepName,
      origin: spec.origin ?? 'inserted',
    };
    if (spec.unknownId !== undefined) {
      inserted.originUnknownId = spec.unknownId;
    }

    // `anchor` is 1-based, so it is already the array index one past the anchor node.
    const snapshot = this.snapshotRun(session);
    nodes.splice(anchor, 0, inserted);

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);
    this.logger.debug(
      `[ChainMutation] Inserted node ${nodeId} after ${afterNodeId} at ordinal ${anchor + 1} of ${totalOf(session.state.nodes)} (session ${sessionId}, unknown ${spec.unknownId ?? 'none'})`
    );
    return inserted;
  }

  /**
   * Retire a not-yet-executed node ahead of the run (P4 adaptive mutation).
   *
   * The node ROW is preserved — this is a lifecycle assertion, not a deletion — so ordinals of
   * the nodes around it do not shift and anything already addressed by id stays valid.
   * `advanceStep` is what makes the skip observable: it passes over `skipped` nodes when choosing
   * the next current node.
   *
   * `unknownId` is the resolution that motivated the skip. It is recorded in the log and NOT
   * persisted as a column: skips are uncapped in v1 (OQ-P4-5), so no reader needs to recover it,
   * and a column nothing reads is the value-dead class this schema has already produced twice.
   *
   * Returns `false` (and warns) rather than throwing, matching the sibling operations. Refused
   * when the session does not exist, the node is not in the run, the node has already started
   * (rendered / responded / completed — a step the client has seen cannot be un-shown), or the
   * node is not STRICTLY ahead of the current node (OQ-P4-2). Re-skipping an already-skipped node
   * is idempotent and returns `true`.
   */
  async markNodeSkipped(sessionId: string, nodeId: string, unknownId: string): Promise<boolean> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      this.logger.warn(`[ChainMutation] Cannot skip node in non-existent session: ${sessionId}`);
      return false;
    }

    const nodes = session.state.nodes;
    const target = ordinalOf(nodes, nodeId);
    if (target === -1) {
      this.logger.warn(
        `[ChainMutation] Refusing to skip: node ${nodeId} is not in session ${sessionId}`
      );
      return false;
    }

    const existing = this.getStepState(sessionId, nodeId)?.state;
    if (existing === 'skipped') {
      return true;
    }
    if (hasStepStarted(existing)) {
      this.logger.warn(
        `[ChainMutation] Refusing to skip node ${nodeId}: already in state '${existing}' (session ${sessionId})`
      );
      return false;
    }

    // OQ-P4-2: strictly ahead only. The current node is already rendered client-side, so
    // skipping it would desynchronize the client's view from run state with no way to signal
    // it. `currentOrdinal` returns `nodes.length + 1` once the run has advanced past its last
    // node, so a finished run rejects every target through this same comparison.
    const here = currentOrdinal(nodes, session.state.currentNodeId);
    if (target <= here) {
      this.logger.warn(
        `[ChainMutation] Refusing to skip node ${nodeId} (ordinal ${target}): run is at ordinal ${here}, and only strictly-ahead nodes may be skipped`
      );
      return false;
    }

    const snapshot = this.snapshotRun(session);
    this.setStepState(sessionId, nodeId, 'skipped');

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot);
    this.logger.debug(
      `[ChainMutation] Skipped node ${nodeId} (ordinal ${target}) in session ${sessionId}, resolved unknown ${unknownId}`
    );
    return true;
  }

  /**
   * Apply a caller-authored remainder to the run's plan (OQ-3 / OQ-A1).
   *
   * Lives beside `insertNodeAfter` and `markNodeSkipped` for the same reason they live together:
   * the run's node list has exactly one owner, and all three are traversal-affecting writes.
   *
   * The ONE shared path for both spellings of an append (OQ-A1) and for a replacement. Whether
   * the nodes arrived as `remainder: {mode, nodes}` or as a leading-`-->` command string, they
   * reach the run here — so caps, id minting and recorded provenance cannot differ between the
   * two spellings, which is what OQ-A1 forbids.
   *
   * Contract, in the order the state-mutation rule requires: validate every refusal condition
   * FIRST (nothing is mutated on a rejected submission), then mutate in memory, then `await` the
   * strict persist, and only then report success. The persist THROWS on failure — unlike the
   * advisory sibling mutations, an accepted remainder is a plan the caller now believes in, and
   * reporting it applied while the rows say otherwise would leave the client executing a plan
   * the server cannot resume.
   *
   * Refusals are DATA, not exceptions: {@link RemainderRejectionReason} names each one so row
   * 2.2 can report it back to the submitter verbatim.
   */
  async replaceRemainder(
    sessionId: string,
    nodes: readonly RemainderNodeSpec[],
    unknownId: string,
    mode: RemainderMode
  ): Promise<RemainderOutcome> {
    const session = this.activeSessions.get(sessionId);
    const refusal = this.refuseRemainder(session, nodes, unknownId, mode);
    if (refusal !== undefined) {
      this.logger.warn(
        `[ChainRemainder] Refusing ${mode} of ${nodes.length} node(s) for unknown ${unknownId} in session ${sessionId}: ${refusal}`
      );
      return { kind: 'rejected', reason: refusal };
    }
    // `refuseRemainder` returning undefined already proved the session exists; the cast-free
    // re-narrow keeps that fact visible to the type checker without a second lookup.
    if (session === undefined) {
      return { kind: 'rejected', reason: 'session-unknown' };
    }

    const snapshot = this.snapshotRun(session);
    const existing = session.state.nodes;
    const here = currentOrdinal(existing, session.state.currentNodeId);
    const minted = mintRemainderNodes(nodes, existing, unknownId, here);

    if (mode === 'replace') {
      // `here` is 1-based, so it is already the array index of the first node AFTER the current
      // one — the same arithmetic `insertNodeAfter` relies on. Everything from there is dropped.
      const removed = existing.splice(here, existing.length - here, ...minted);
      for (const node of removed) {
        session.state.stepStates?.delete(node.id);
      }
      this.logger.debug(
        `[ChainRemainder] Replaced ${removed.length} node(s) after ordinal ${here} with ${minted.length} in session ${sessionId} (unknown ${unknownId})`
      );
    } else {
      existing.push(...minted);
      this.logger.debug(
        `[ChainRemainder] Appended ${minted.length} node(s) to session ${sessionId} (unknown ${unknownId})`
      );
    }

    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot, { strict: true });

    return { kind: 'applied', mode, nodes: minted };
  }

  /**
   * Every reason a remainder submission is refused, evaluated before anything is mutated.
   *
   * Returns `undefined` when the submission may proceed. Both caps are recomputed from the
   * run's NODES rather than from in-memory bookkeeping, so a cold-loaded run enforces exactly
   * what a hot one does — `origin`/`origin_unknown_id`/`accepted_at_step` are persisted columns
   * for this reason.
   */
  private refuseRemainder(
    session: ChainSession | undefined,
    nodes: readonly RemainderNodeSpec[],
    unknownId: string,
    mode: RemainderMode
  ): RemainderRejectionReason | undefined {
    if (nodes.length === 0) {
      return 'empty-remainder';
    }
    if (session === undefined) {
      return 'session-unknown';
    }
    if (isTerminalRunStatus(session.runStatus) || session.state.currentNodeId === null) {
      // A run standing on no node has already passed its terminal node, so "strictly after the
      // current one" names nothing and an append would add steps nothing will ever reach.
      return 'run-terminal';
    }

    const existing = session.state.nodes;
    // Per declaration (R133, the rule R127 set for insertions): a remainder accepted before the
    // unknown was resolved does not spend its re-opened incarnation's one.
    if (
      investigatedUnknownIds(session.unknownsLedger ?? [], existing, 'remainder').has(unknownId)
    ) {
      return 'cap-reached';
    }
    if (countRemainderUnknownIds(existing) >= MAX_REMAINDERS_PER_RUN) {
      return 'cap-reached';
    }

    if (mode === 'replace') {
      const here = currentOrdinal(existing, session.state.currentNodeId);
      const doomed = existing.slice(here);
      if (
        doomed.some((node) => hasStepStarted(this.getStepState(session.sessionId, node.id)?.state))
      ) {
        // OQ-P4-2, applied to a range: a step the client has already been shown cannot be
        // un-shown, so a replacement that would delete one is refused whole rather than
        // partially applied.
        return 'node-already-started';
      }
    }

    return undefined;
  }

  /**
   * Persist a step result to storage and optional tracking systems.
   */
  private async persistStepResult(
    session: ChainSession,
    nodeId: string,
    stepResult: string,
    metadata: Record<string, any>,
    isPlaceholder: boolean
  ): Promise<void> {
    const metadataPayload = {
      ...metadata,
      isPlaceholder,
    };

    // The containers key by node id; the ordinal rides along because the *rendered* contract
    // (`stepN_result`, `previous_step_results` keys) is positional and must not shift.
    const ordinal = ordinalOf(session.state.nodes, nodeId);

    this.textReferenceStore.storeChainStepResult(
      session.sessionId,
      nodeId,
      stepResult,
      metadataPayload,
      ordinal === -1 ? undefined : ordinal
    );

    if (this.argumentHistoryTracker && !isPlaceholder) {
      try {
        await this.argumentHistoryTracker.trackExecution({
          promptId: session.chainId,
          sessionId: session.sessionId,
          originalArgs: session.originalArgs || {},
          nodeId,
          ...(ordinal === -1 ? {} : { stepNumber: ordinal }),
          stepResult,
          metadata: {
            executionType: 'chain',
            chainId: session.chainId,
            ...metadataPayload,
          },
        });
      } catch (error) {
        this.logger?.error('[ChainSessionStore] Failed to track argument history entry', {
          chainId: session.chainId,
          nodeId,
          error,
        });
      }
    }
  }

  /**
   * Get chain context for session - this is the critical method for fixing contextData
   */
  getChainContext(sessionId: string, _scope?: StateStoreOptions): Record<string, any> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger.debug(`No session found for ${sessionId}, returning empty context`);
      return {};
    }

    // Get chain variables from text reference manager (single source of truth)
    const chainVariables = this.textReferenceStore.buildChainVariables(
      session.sessionId,
      session.chainId
    );

    // Get original arguments + previous results from ArgumentHistoryTracker (with graceful fallback)
    // No initializer: all three paths below (tracker success, tracker failure, no tracker)
    // assign it. `= {}` also pinned the type to `{}`, so the annotation is explicit now.
    let argumentContext: Record<string, unknown>;
    let reviewContext:
      | {
          originalArgs: Record<string, unknown>;
          previousResults: Record<number, string>;
          currentStep?: number;
          totalSteps?: number;
        }
      | undefined;
    if (this.argumentHistoryTracker) {
      try {
        reviewContext = this.argumentHistoryTracker.buildReviewContext(
          sessionId,
          currentOrdinal(session.state.nodes, session.state.currentNodeId),
          totalOf(session.state.nodes)
        );
        argumentContext = reviewContext.originalArgs;
      } catch (error) {
        // Fallback to session's originalArgs if tracker fails
        this.logger.debug(
          `Failed to get arguments from ArgumentHistoryTracker, using session originalArgs: ${
            error instanceof Error ? error.message : String(error)
          }`
        );
        argumentContext = session.originalArgs;
      }
    } else {
      // Fallback to session's originalArgs if tracker not available
      argumentContext = session.originalArgs;
    }

    // Merge with session-specific context
    const contextData: Record<string, any> = {
      // Core session info
      chain_run_id: sessionId,
      chain_id: session.chainId,
      current_step: currentOrdinal(session.state.nodes, session.state.currentNodeId),
      total_steps: totalOf(session.state.nodes),
      // Ordinals, not node ids: this lands in the rendering context, whose shape templates
      // already depend on. The node ids live on `session.executionOrder`.
      execution_order: session.executionOrder.map((id) => ordinalOf(session.state.nodes, id)),
      current_node_id: session.state.currentNodeId,

      // Chain variables (step results, etc.) from TextReferenceStore
      ...chainVariables,

      // Original arguments - spread for template access AND nested for intent rendering
      ...argumentContext,
      original_args: argumentContext,
    };

    if (reviewContext && Object.keys(reviewContext.previousResults).length > 0) {
      contextData['previous_step_results'] = { ...reviewContext.previousResults };
    }

    // Omitted entirely while empty so a template can branch on presence, matching
    // previous_step_results above. Entries are copies: template consumers must not be
    // able to mutate live session state through the rendering context.
    const unknownsLedger = session.unknownsLedger;
    if (unknownsLedger !== undefined && unknownsLedger.length > 0) {
      contextData['unknowns_ledger'] = unknownsLedger.map((entry) => ({ ...entry }));
    }

    const currentStepArgs = this.getCurrentStepArgs(session);
    if (currentStepArgs && Object.keys(currentStepArgs).length > 0) {
      contextData['currentStepArgs'] = currentStepArgs;
      // Expose step arguments as {{input}} for template access
      contextData['input'] = currentStepArgs;
    }

    const chainMetadata = this.buildChainMetadata(session);
    if (chainMetadata) {
      contextData['chain_metadata'] = chainMetadata;
    }

    this.logger.debug(
      `Retrieved context for session ${sessionId}: ${
        Object.keys(contextData).length
      } context variables (including ${Object.keys(argumentContext).length} original arguments)`
    );
    return contextData;
  }

  /**
   * Project the run's record-only complexity facts. Pure read — no mutation, no persistence,
   * and no derived score of any kind (master decision D4).
   *
   * `unknownsOpened`/`unknownsClosed` are derived from the ledger rather than from their own
   * counters because the ledger is already cumulative: entries are never deleted, only
   * transitioned active -> resolved. A parallel counter would be a second, driftable source.
   *
   * `nodesInserted`/`nodesSkipped` (P4) follow the same rule against the node list: `origin`
   * and the step lifecycle already ARE the record of what the mutation policy did, and both
   * reconstruct from persisted rows on a cold load, so a resumed run reports the same numbers
   * a continuously-live one does. A skipped node is still IN the list, so a skip never lowers
   * `stepsPlanned`.
   *
   * This is the one telemetry source BOTH terminal-record writers read
   * (`21-formatting-stage.ts` on the completed/cancelled path, `prompt-execution-pipeline.ts`
   * on the failed path). Deriving a field anywhere else would give failed runs NULLs while
   * completed runs carried values — the partial-fix shape the run-telemetry suite rejects.
   */
  getRunTelemetry(sessionId: string, _scope?: StateStoreOptions): RunTelemetry | undefined {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      return undefined;
    }

    const ledger = session.unknownsLedger ?? [];
    const stepStates = session.state.stepStates;
    return {
      stepsPlanned: totalOf(session.state.nodes),
      gatesFired: session.gatesFiredCount ?? 0,
      gateRetries: session.gateRetriesCount ?? 0,
      unknownsOpened: ledger.length,
      unknownsClosed: ledger.filter((entry) => entry.state === 'resolved').length,
      nodesInserted: session.state.nodes.filter((node) => node.origin === 'inserted').length,
      nodesSkipped: session.state.nodes.filter(
        (node) => stepStates?.get(node.id)?.state === 'skipped'
      ).length,
      // D-8. Derived from the same two lists as everything above, never from a counter — see
      // `RunTelemetry`'s docblock for what UNIT each one counts, which is the part a reader
      // cannot recover from the column name alone.
      interruptsRaised: ledger.filter((entry) => entry.blocking === true).length,
      remaindersAccepted: countRemainderUnknownIds(session.state.nodes),
    };
  }

  /**
   * Get original arguments for session
   */
  getOriginalArgs(sessionId: string): Record<string, any> {
    const session = this.activeSessions.get(sessionId);
    return session?.originalArgs || {};
  }

  getSessionBlueprint(sessionId: string, _scope?: StateStoreOptions): SessionBlueprint | undefined {
    const session = this.activeSessions.get(sessionId);
    if (!session?.blueprint) {
      return undefined;
    }
    return this.cloneBlueprint(session.blueprint);
  }

  getInlineGateIds(sessionId: string, _scope?: StateStoreOptions): string[] | undefined {
    const session = this.activeSessions.get(sessionId);
    if (!session?.blueprint?.parsedCommand) {
      return undefined;
    }

    const inlineIds = this.collectInlineGateIds(session.blueprint.parsedCommand, sessionId);
    return inlineIds.length > 0 ? inlineIds : undefined;
  }

  async remapRunGates(sessionId: string, remap: ReadonlyMap<string, string>): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      if (remap.size > 0) {
        this.logger.warn(`Attempted to remap the gates of non-existent session: ${sessionId}`);
      }
      return;
    }
    // R69: the run carries the map an earlier claimer applied, and its reviews name that
    // claimer's ids, so this process's map composes onto it rather than replacing it.
    const { applied, rewrite } = composeGateRemap(session.gateRemap ?? {}, remap);
    const mapChanged = !sameGateRemap(session.gateRemap ?? {}, applied);
    const snapshot = this.snapshotRun(session);
    if (Object.keys(applied).length > 0) session.gateRemap = applied;
    else delete session.gateRemap;
    const stale = Object.values(session.reviews ?? {}).filter((review) =>
      reviewGateIds(review).some((id) => rewrite.has(id))
    );
    for (const review of stale) {
      writeReview(session, remapReviewGateIds(review, rewrite));
    }
    if (mapChanged || stale.length > 0) await this.persistMutation(snapshot);
  }

  async setReview(sessionId: string, review: GateReview): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger.warn(`Attempted to set a gate review for non-existent session: ${sessionId}`);
      return;
    }

    const snapshot = this.snapshotRun(session);
    writeReview(session, cloneReview(review));
    await this.persistMutation(snapshot);
  }

  async clearReview(sessionId: string, nodeId: string): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (session?.reviews?.[nodeId] === undefined) return;
    const snapshot = this.snapshotRun(session);
    deleteReview(session, nodeId);
    await this.persistMutation(snapshot);
  }

  /**
   * Stamp a pre-3.1 review's kind and phase and store it on the node it names (R8): `slot`, else
   * its own `nodeId`, else the graded step its metadata records (a structural review's). The node
   * is never derived from where the run stands.
   *
   * @deprecated stamped: (as of 2026-09-23 · flips when `setPendingGateReview` has no `src`
   * caller; stages 16, 19 and 20 still write through it)
   * @throws when the review names no node.
   */
  async setPendingGateReview(
    sessionId: string,
    review: PendingGateReview,
    slot?: ReviewSlot
  ): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      this.logger.warn(`Attempted to set a gate review for non-existent session: ${sessionId}`);
      return;
    }
    const recorded = review.metadata?.['nodeId'];
    const nodeId =
      slot?.nodeId ?? review.nodeId ?? (typeof recorded === 'string' ? recorded : undefined);
    if (nodeId === undefined || nodeId.length === 0) {
      throw new Error(
        `A gate review of session ${sessionId} was written without the node it grades`
      );
    }
    await this.setReview(sessionId, stampLegacyReview({ ...review, nodeId }, session, slot));
  }

  getReview(sessionId: string, nodeId: string): GateReview | undefined {
    const review = this.activeSessions.get(sessionId)?.reviews?.[nodeId];
    return review === undefined ? undefined : cloneReview(review);
  }

  async clearPendingGateReview(sessionId: string, slot: ReviewSlot): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    const target = session?.reviews?.[slot.nodeId];
    if (session === undefined || target?.kind !== 'detached') {
      return;
    }

    const snapshot = this.snapshotRun(session);
    deleteReview(session, target.nodeId);
    await this.persistMutation(snapshot);
  }

  async setPendingShellVerification(
    sessionId: string,
    state: PendingShellVerificationSnapshot
  ): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      this.logger?.warn?.(
        `Attempted to set pending shell verification for non-existent session: ${sessionId}`
      );
      return;
    }

    const snapshot = this.snapshotRun(session);
    session.pendingShellVerification = { ...state };
    await this.persistMutation(snapshot);
  }

  getPendingShellVerification(sessionId: string): PendingShellVerificationSnapshot | undefined {
    const session = this.activeSessions.get(sessionId);
    return session?.pendingShellVerification ? { ...session.pendingShellVerification } : undefined;
  }

  async clearPendingShellVerification(sessionId: string): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (!session?.pendingShellVerification) {
      return;
    }

    const snapshot = this.snapshotRun(session);
    delete session.pendingShellVerification;
    await this.persistMutation(snapshot);
  }

  /**
   * Count one verdict in the run's cumulative gate counters. The review it answered is not
   * touched: the verdict path (`GateVerdictProcessor.answerReview`) persists the review its
   * transition returns. Record-only (D4): nothing branches on these values.
   */
  async recordGateReviewOutcome(
    sessionId: string,
    outcome: GateReviewOutcomeUpdate
  ): Promise<void> {
    const session = this.activeSessions.get(sessionId);
    if (session === undefined) {
      this.logger?.warn(
        `[GateReview] Attempted to record verdict for non-existent session: ${sessionId}`
      );
      return;
    }
    const snapshot = this.snapshotRun(session);
    session.gatesFiredCount = (session.gatesFiredCount ?? 0) + 1;
    if (outcome.verdict === 'FAIL') {
      session.gateRetriesCount = (session.gateRetriesCount ?? 0) + 1;
    }
    await this.persistMutation(snapshot);
  }

  /**
   * Check if session exists and is active
   */
  hasActiveSession(sessionId: string): boolean {
    return this.activeSessions.has(sessionId);
  }

  /**
   * Check if chain has any active sessions
   */
  hasActiveSessionForChain(chainId: string): boolean {
    const sessionIds = this.chainSessionMapping.get(chainId);
    if (!sessionIds) {
      return false;
    }

    for (const sessionId of sessionIds) {
      const session = this.activeSessions.get(sessionId);
      if (session && !this.isDormantSession(session)) {
        return true;
      }
    }
    return false;
  }

  getRunHistory(baseChainId: string): string[] {
    const normalized = stripRunNumber(baseChainId);
    const history = this.baseChainMapping.get(normalized);
    if (history && history.length > 0) {
      return [...history];
    }

    if (this.chainSessionMapping.has(normalized)) {
      return [normalized];
    }

    const fallbackRuns = Array.from(this.chainSessionMapping.keys()).filter(
      (chainId) => stripRunNumber(chainId) === normalized
    );

    return fallbackRuns.sort((a, b) => {
      const runA = parseRunNumber(a) ?? 0;
      const runB = parseRunNumber(b) ?? 0;
      return runA - runB;
    });
  }

  getLatestSessionForBaseChain(baseChainId: string): ChainSession | undefined {
    const normalized = stripRunNumber(baseChainId);
    const history = this.baseChainMapping.get(normalized);

    if (history && history.length > 0) {
      for (let idx = history.length - 1; idx >= 0; idx -= 1) {
        const runChainId = history[idx];
        if (runChainId === undefined) {
          continue;
        }
        const sessionIds = this.chainSessionMapping.get(runChainId);
        if (!sessionIds) {
          continue;
        }
        for (const sessionId of sessionIds) {
          const session = this.activeSessions.get(sessionId);
          if (session && !this.isDormantSession(session)) {
            return session;
          }
        }
      }
    }

    return this.getActiveSessionForChain(normalized);
  }

  getSessionByChainIdentifier(
    chainId: string,
    options?: ChainSessionLookupOptions
  ): ChainSession | undefined {
    const includeDormant = options?.includeDormant ?? false;
    const scopeFilter = this.resolveScopeFilter(options);

    // Scope-aware lookup: find best matching session across active/dormant states
    const found = this.findScopedSessionForChain(chainId, scopeFilter, includeDormant);
    if (found) {
      if (found.lifecycle === 'dormant') {
        this.promoteSessionLifecycle(found, 'explicit chain resume');
      }
      return found;
    }

    // Try base chain fallback
    const normalized = stripRunNumber(chainId);
    const baseFallback = this.findScopedSessionForChain(normalized, scopeFilter, includeDormant);
    if (baseFallback) {
      if (baseFallback.lifecycle === 'dormant') {
        this.promoteSessionLifecycle(baseFallback, 'explicit base chain resume');
      }
      return baseFallback;
    }

    return undefined;
  }

  /**
   * Find the best session for a chainId that matches the scope filter.
   * Prefers active over dormant, most recent by lastActivity.
   */
  private findScopedSessionForChain(
    chainId: string,
    scopeFilter: string | undefined,
    includeDormant: boolean
  ): ChainSession | undefined {
    const sessionIds = this.chainSessionMapping.get(chainId);
    if (!sessionIds || sessionIds.size === 0) return undefined;

    let bestActive: ChainSession | undefined;
    let bestDormant: ChainSession | undefined;
    let bestActiveTime = 0;
    let bestDormantTime = 0;

    for (const sessionId of sessionIds) {
      const session = this.activeSessions.get(sessionId);
      if (!session || !this.matchesScope(session, scopeFilter)) continue;

      if (this.isDormantSession(session)) {
        if (includeDormant && session.lastActivity > bestDormantTime) {
          bestDormant = session;
          bestDormantTime = session.lastActivity;
        }
      } else if (session.lastActivity > bestActiveTime) {
        bestActive = session;
        bestActiveTime = session.lastActivity;
      }
    }

    return bestActive ?? bestDormant;
  }

  listActiveSessions(limit: number = 50, scope?: StateStoreOptions): ChainSessionSummary[] {
    const scopeFilter = this.resolveScopeFilter(scope);
    const summaries: ChainSessionSummary[] = [];
    for (const session of this.activeSessions.values()) {
      if (this.isDormantSession(session)) {
        continue;
      }
      if (!this.matchesScope(session, scopeFilter)) {
        continue;
      }
      const promptName = session.blueprint?.parsedCommand?.convertedPrompt?.name;
      const promptId =
        session.blueprint?.parsedCommand?.convertedPrompt?.id ??
        session.blueprint?.parsedCommand?.promptId;
      const summary: ChainSessionSummary = {
        sessionId: session.sessionId,
        chainId: session.chainId,
        // Summaries are a display projection: ints computed here, never stored.
        currentStep: currentOrdinal(session.state.nodes, session.state.currentNodeId),
        totalSteps: totalOf(session.state.nodes),
        pendingReview: Object.keys(session.reviews ?? {}).length > 0,
        lastActivity: session.lastActivity,
        startTime: session.startTime,
        ...(promptName !== undefined && { promptName }),
        ...(promptId !== undefined && { promptId }),
      };
      summaries.push(summary);
    }

    summaries.sort((a, b) => b.lastActivity - a.lastActivity);
    return limit > 0 ? summaries.slice(0, limit) : summaries;
  }

  /**
   * Get active session for chain (returns first active session)
   */
  getActiveSessionForChain(chainId: string): ChainSession | undefined {
    const sessionIds = this.chainSessionMapping.get(chainId);
    if (!sessionIds || sessionIds.size === 0) {
      return undefined;
    }

    // Return the most recently active session
    let mostRecentSession: ChainSession | undefined;
    let mostRecentActivity = 0;

    for (const sessionId of sessionIds) {
      const session = this.activeSessions.get(sessionId);
      if (session && !this.isDormantSession(session) && session.lastActivity > mostRecentActivity) {
        mostRecentSession = session;
        mostRecentActivity = session.lastActivity;
      }
    }

    return mostRecentSession;
  }

  /**
   * Clear session
   */
  /**
   * Remove one session and its artifacts.
   *
   * `scope` is honoured the same way `cancelChain` honours it: a session belonging to another
   * workspace is invisible and the call reports `false`. Without it this method read
   * `activeSessions` directly, so `system_control session clear` could destroy a session in a
   * workspace the caller had no view of — while `cancel`, one method away, enforced the boundary.
   * Omitting `scope` preserves the previous unscoped behaviour for the internal callers
   * (`cleanupStaleSessions`, `clearSessionsForChain`) that legitimately sweep every scope.
   */
  async clearSession(sessionId: string, scope?: StateStoreOptions): Promise<boolean> {
    const session = this.getSessionForMutation(sessionId, scope);
    if (!session) {
      return false;
    }

    const snapshot = this.snapshotRunMembership();
    const release = emptyRunRelease();
    this.removeSessionArtifacts(sessionId, release);

    this.removeSessionFromRun(sessionId, session.chainId);

    await this.persistMutation(snapshot);
    // Listeners receive the removed session object, so they can still inspect its state.
    await this.notifySessionCleared(sessionId, session);
    await this.releaseRemovedRuns(release);

    if (this.logger) {
      this.logger.debug(`Cleared session ${sessionId} for chain ${session.chainId}`);
    }
    return true;
  }

  /**
   * Clear all sessions for a chain
   */
  async clearSessionsForChain(chainId: string, scope?: StateStoreOptions): Promise<void> {
    const scopeFilter = this.resolveScopeFilter(scope);
    const baseChainId = stripRunNumber(chainId);
    const runChainIds = chainId === baseChainId ? [...this.getRunHistory(baseChainId)] : [chainId];

    if (runChainIds.length === 0 && this.chainSessionMapping.has(chainId)) {
      runChainIds.push(chainId);
    }

    const snapshot = this.snapshotRunMembership();
    const release = emptyRunRelease();
    for (const runChainId of runChainIds) {
      this.removeRunChainSessionsForScope(runChainId, scopeFilter, release);
      // A run another scope still holds keeps its history, as in `clearSession` (R102); step
      // results are per session, so only the removed sessions' results are released (R107).
      if (this.chainSessionMapping.has(runChainId)) continue;
      this.removeRunFromBaseTracking(runChainId);
    }

    await this.persistMutation(snapshot);
    await this.releaseRemovedRuns(release);

    if (this.logger) {
      this.logger.debug(`Cleared all sessions for chain ${chainId}`);
    }
  }

  /**
   * Cleanup stale sessions (older than 24 hours)
   */
  async cleanupStaleSessions(): Promise<number> {
    const now = Date.now();
    const reviewThreshold = now - this.reviewSessionTimeoutMs;
    const defaultThreshold = now - this.defaultSessionTimeoutMs;
    let cleaned = 0;

    const staleSessionIds: string[] = [];
    for (const [sessionId, session] of this.activeSessions) {
      const isReviewSession = session.chainId.startsWith('prompt-review-');
      const threshold = isReviewSession ? reviewThreshold : defaultThreshold;
      if (session.lastActivity < threshold) {
        staleSessionIds.push(sessionId);
      }
    }

    for (const sessionId of staleSessionIds) {
      const session = this.activeSessions.get(sessionId);
      await this.clearSession(sessionId);
      cleaned++;
      if (session?.chainId?.startsWith('prompt-review-')) {
        this.logger?.info('[GateReview] Cleaned abandoned prompt review session', {
          sessionId,
          chainId: session.chainId,
          lastActivity: session?.lastActivity,
        });
      }
    }

    if (cleaned > 0) {
      this.logger?.info(
        `Cleaned up ${cleaned} stale chain sessions (default timeout ${this.defaultSessionTimeoutMs}ms, review timeout ${this.reviewSessionTimeoutMs}ms)`
      );
    }

    return cleaned;
  }

  private registerRunHistory(chainId: string): string {
    const baseChainId = stripRunNumber(chainId);
    const history = this.baseChainMapping.get(baseChainId) ?? [];

    const existingIndex = history.indexOf(chainId);
    if (existingIndex >= 0) {
      history.splice(existingIndex, 1);
    }

    history.push(chainId);
    this.baseChainMapping.set(baseChainId, history);
    this.runChainToBase.set(chainId, baseChainId);
    return baseChainId;
  }

  private pruneExcessRuns(baseChainId: string, release: RunRelease): void {
    const history = this.baseChainMapping.get(baseChainId);
    if (!history) {
      return;
    }

    while (history.length > MAX_RUN_HISTORY) {
      const removedChainId = history.shift();
      if (!removedChainId) {
        break;
      }

      const removedSessions = this.removeRunChainSessions(removedChainId, release);
      this.removeRunFromBaseTracking(removedChainId);

      this.logger?.info(
        `Pruned oldest run ${removedChainId} for base ${baseChainId} (keeping ${MAX_RUN_HISTORY} runs)`,
        { removedSessions }
      );
    }

    if (history.length === 0) {
      this.baseChainMapping.delete(baseChainId);
    }
  }

  private removeRunChainSessions(chainId: string, release: RunRelease): string[] {
    const sessionIds = this.chainSessionMapping.get(chainId);
    const removedSessions: string[] = [];

    if (sessionIds) {
      for (const sessionId of sessionIds) {
        this.removeSessionArtifacts(sessionId, release);
        removedSessions.push(sessionId);
      }
      this.chainSessionMapping.delete(chainId);
    }

    return removedSessions;
  }

  private async notifySessionCleared(sessionId: string, session: ChainSession): Promise<void> {
    for (const callback of this.sessionClearedCallbacks) {
      try {
        await callback(sessionId, session);
      } catch (error) {
        this.logger.warn(
          `Session-cleared callback failed for ${sessionId}: ${
            error instanceof Error ? error.message : String(error)
          }`
        );
      }
    }
  }

  /**
   * Drop a session from memory and queue what it releases on `release`. The queue runs only once
   * the persist returns ({@link releaseRemovedRuns}), because a snapshot restores membership but
   * cannot take back a callback that fired or history that was cleared (R93, P6.190).
   */
  private removeSessionArtifacts(sessionId: string, release: RunRelease): void {
    release.sessionIds.push(sessionId);
    this.activeSessions.delete(sessionId);
  }

  /**
   * The side effects of a removal that no snapshot can undo, in the order they always ran:
   * run-ended callbacks and (unless an eviction keeps it) argument history per session, then
   * step results per session (keyed by session since R107, so a removal releases exactly the
   * sessions it removed).
   * Called only after `persistMutation` returns, so a rejected save releases nothing and its
   * retry releases exactly once — or, for a session another server claimed, after the persist
   * that evicted it commits (R116).
   */
  private async releaseRemovedRuns(release: RunRelease): Promise<void> {
    for (const sessionId of release.sessionIds) {
      this.notifyRunEnded(sessionId);
      if (this.argumentHistoryTracker && release.argumentHistory === 'clear') {
        try {
          await this.argumentHistoryTracker.clearSession(sessionId);
          this.logger.debug(`Cleared argument history for session ${sessionId}`);
        } catch (error) {
          this.logger.warn(
            `Failed to clear argument history for session ${sessionId}: ${
              error instanceof Error ? error.message : String(error)
            }`
          );
        }
      }
    }
    for (const sessionId of release.sessionIds) {
      this.textReferenceStore.clearChainStepResults(sessionId);
    }
  }

  /**
   * Take one session out of its run's membership. The run leaves every run index — its emptied
   * `chainSessionMapping` set and its run-history entry — once no session holds it. The one
   * removal path `clearSession`, eviction and a reserved rename share (R120, R123).
   */
  private removeSessionFromRun(sessionId: string, chainId: string): void {
    const chainSessions = this.chainSessionMapping.get(chainId);
    if (!chainSessions) return;
    chainSessions.delete(sessionId);
    if (chainSessions.size > 0) return;
    this.chainSessionMapping.delete(chainId);
    this.removeRunFromBaseTracking(chainId);
  }

  private removeRunFromBaseTracking(chainId: string): void {
    const baseChainId = this.runChainToBase.get(chainId) ?? stripRunNumber(chainId);
    const history = this.baseChainMapping.get(baseChainId);
    if (history) {
      const filtered = history.filter((entry) => entry !== chainId);
      if (filtered.length > 0) {
        this.baseChainMapping.set(baseChainId, filtered);
      } else {
        this.baseChainMapping.delete(baseChainId);
      }
    }

    this.runChainToBase.delete(chainId);
  }

  private ensureRunMappingConsistency(): void {
    for (const chainId of this.chainSessionMapping.keys()) {
      const baseChainId = stripRunNumber(chainId);
      if (!this.baseChainMapping.has(baseChainId)) {
        this.baseChainMapping.set(baseChainId, []);
      }
      const history = this.baseChainMapping.get(baseChainId)!;
      if (!history.includes(chainId)) {
        history.push(chainId);
        history.sort((a, b) => {
          const runA = parseRunNumber(a) ?? 0;
          const runB = parseRunNumber(b) ?? 0;
          return runA - runB;
        });
      }

      if (!this.runChainToBase.has(chainId)) {
        this.runChainToBase.set(chainId, baseChainId);
      }
    }

    for (const [runChainId, baseChainId] of Array.from(this.runChainToBase.entries())) {
      if (!this.chainSessionMapping.has(runChainId)) {
        this.runChainToBase.delete(runChainId);
        const history = this.baseChainMapping.get(baseChainId);
        if (history) {
          const filtered = history.filter((entry) => entry !== runChainId);
          if (filtered.length > 0) {
            this.baseChainMapping.set(baseChainId, filtered);
          } else {
            this.baseChainMapping.delete(baseChainId);
          }
        }
      }
    }
  }

  /**
   * Get session statistics
   */
  getSessionStats(): {
    totalSessions: number;
    totalChains: number;
    averageStepsPerChain: number;
    oldestSessionAge: number;
  } {
    const totalSessions = this.activeSessions.size;
    const totalChains = this.chainSessionMapping.size;

    let totalSteps = 0;
    let oldestSessionTime = Date.now();

    for (const session of this.activeSessions.values()) {
      // Was `+= session.state.currentStep` — an identity/cardinality coercion. The only
      // consumer is `averageStepsPerChain` (observability-resources.ts:210), which asks how
      // many STEPS a chain holds, not how far along it happens to be; summing positions made
      // the average drift with progress and never reached the true count until every run
      // finished. Node count is the cardinality that question wants.
      totalSteps += totalOf(session.state.nodes);
      if (session.startTime < oldestSessionTime) {
        oldestSessionTime = session.startTime;
      }
    }

    return {
      totalSessions,
      totalChains,
      averageStepsPerChain: totalChains > 0 ? totalSteps / totalChains : 0,
      oldestSessionAge: Date.now() - oldestSessionTime,
    };
  }

  /**
   * Apply a batch of typed unknown observations to the session's ledger.
   *
   * Transition rules are NOT restated here — `computeUnknownLedger` is their single
   * owner. This method owns only lookup, in-memory mutation and persistence, in that
   * order: an invalid batch throws before `session.unknownsLedger` is touched, and a
   * persist failure throws rather than reporting a success the disk does not back.
   *
   * It calls {@link persistSessionsOrThrow}, not {@link saveSessions}: the latter still logs and
   * continues past a held lock (R74), and a declared unknown is the one thing in this subsystem
   * the CLIENT is told about: the ledger it just wrote is rendered back into this same call's
   * chain context and, from row 2.1, into a `chain_interrupt`. Reporting either against rows that were never committed hands the
   * client a plan the server cannot resume, and the divergence surfaces only on a cold load.
   *
   * A failed persist therefore fails the CALL. It propagates as a non-validation error out of
   * `StepResponseCaptureStage.applyObservations` (which converts only
   * `UnknownObservationValidationError`) to the pipeline error boundary, which is where
   * `architecture.md` puts the response decision — the same posture `replaceRemainder` takes.
   */
  async applyUnknownObservations(
    sessionId: string,
    nodeId: string,
    observations: UnknownObservation[]
  ): Promise<UnknownLedgerEntry[]> {
    const session = this.activeSessions.get(sessionId);
    if (!session) {
      throw new Error(
        `Cannot apply unknown observations: session not found: ${sessionId}. The chain run may have been cleared.`
      );
    }

    // `discoveredAtStep`/`resolvedAtStep` are ordinals-at-write — a historical stamp of where
    // the run stood, not an address into it. Resolved here so the ledger keeps its number
    // shape while the caller addresses by identity.
    const stepOrdinal = ordinalOf(session.state.nodes, nodeId);

    // Throws on an invalid transition or cap overflow — before any mutation below.
    const nextLedger = computeUnknownLedger(
      session.unknownsLedger ?? [],
      observations,
      stepOrdinal === -1
        ? currentOrdinal(session.state.nodes, session.state.currentNodeId)
        : stepOrdinal
    );

    const snapshot = this.snapshotRun(session);
    session.unknownsLedger = nextLedger;
    session.state.lastUpdated = Date.now();
    session.lastActivity = Date.now();

    await this.persistMutation(snapshot, { strict: true });

    return nextLedger.map((entry) => ({ ...entry }));
  }

  /**
   * Cleanup the chain session manager and persist state
   * Prevents async handle leaks by finalizing all file operations
   */
  async cleanup(): Promise<void> {
    this.logger.info('Shutting down ChainSessionStore...');

    try {
      if (this.cleanupIntervalHandle !== undefined) {
        clearInterval(this.cleanupIntervalHandle);
        // Use Object.assign to safely clear the optional property
        Object.assign(this, { cleanupIntervalHandle: undefined });
        this.logger.debug('Chain session cleanup scheduler cleared');
      }

      // Perform final state save to persist any pending session data
      await this.saveSessions();
      this.logger.debug('Chain sessions persisted during cleanup');
    } catch (error) {
      this.logger.warn('Error persisting sessions during cleanup:', error);
    }

    // Clear in-memory state
    this.activeSessions.clear();
    this.chainSessionMapping.clear();
    this.baseChainMapping.clear();
    this.runChainToBase.clear();
    this.logger.debug('In-memory session state cleared');

    this.logger.info('ChainSessionStore cleanup complete');
  }

  private isDormantSession(session?: ChainSession | null): boolean {
    return session?.lifecycle === 'dormant';
  }

  private promoteSessionLifecycle(session: ChainSession, reason: string): void {
    if (session.lifecycle === 'canonical') {
      return;
    }
    if (isTerminalRunStatus(session.runStatus)) {
      this.logger.warn(
        `[ChainSessionStore] Refusing to promote session ${session.sessionId} (${reason}): runStatus '${session.runStatus}' is terminal`
      );
      return;
    }
    session.lifecycle = 'canonical';
    this.logger?.debug?.(
      `[ChainSessionStore] Promoted session ${session.sessionId} to canonical (${reason})`
    );
    this.persistSessionsAsync('lifecycle-promotion');
  }

  private buildChainMetadata(session: ChainSession): Record<string, any> | undefined {
    const blueprint = session.blueprint;
    const baseMetadata: Record<string, any> = {
      chainId: session.chainId,
      chainRunId: session.sessionId,
      totalSteps: totalOf(session.state.nodes),
      currentStep: currentOrdinal(session.state.nodes, session.state.currentNodeId),
      currentNodeId: session.state.currentNodeId,
    };

    if (!blueprint) {
      return baseMetadata;
    }

    const parsed = blueprint.parsedCommand;
    const convertedPrompt = parsed?.convertedPrompt;
    const plan = blueprint.executionPlan;

    const metadata: Record<string, any> = {
      ...baseMetadata,
      promptId: convertedPrompt?.id ?? parsed?.promptId ?? session.chainId,
      name: convertedPrompt?.name ?? parsed?.promptId ?? session.chainId,
      description: convertedPrompt?.description,
      category: convertedPrompt?.category,
      gates: plan?.gates ?? [],
      strategy: plan?.strategy,
      inlineGateIds: this.collectInlineGateIds(parsed, session.sessionId),
    };

    return metadata;
  }

  /** The blueprint's inline gate ids, each resolved through the run's gate remap (R60 amended). */
  private collectInlineGateIds(
    parsedCommand: ParsedCommandSnapshot | undefined,
    sessionId: string
  ): string[] {
    if (!parsedCommand) {
      return [];
    }

    const remap = new Map(Object.entries(this.activeSessions.get(sessionId)?.gateRemap ?? {}));
    const ids = new Set<string>();

    const recordIds = (values?: string[]) => {
      if (!Array.isArray(values)) {
        return;
      }
      for (const id of values) {
        if (typeof id === 'string' && id.trim().length > 0) {
          ids.add(remap.get(id) ?? id);
        }
      }
    };

    recordIds(parsedCommand.inlineGateIds);

    if (Array.isArray(parsedCommand.steps)) {
      for (const step of parsedCommand.steps) {
        recordIds(step.inlineGateIds);
      }
    }

    return Array.from(ids);
  }

  private getCurrentStepArgs(session: ChainSession): Record<string, unknown> | undefined {
    const blueprintSteps = session.blueprint?.parsedCommand?.steps;
    if (!Array.isArray(blueprintSteps) || blueprintSteps.length === 0) {
      return undefined;
    }

    // By node (R77): a node the parse did not mint has no blueprint step. By clamped ordinal, an
    // inserted node's review quoted the next planned step's arguments in place of its own
    // `statement` and `unknown_id`, and a remainder node past the array took the last step's.
    const currentStep = currentOrdinal(session.state.nodes, session.state.currentNodeId) || 1;
    const args = parseStepForNode(blueprintSteps, session.state.currentNodeId, currentStep)?.args;
    if (!args || Object.keys(args).length === 0) {
      return undefined;
    }
    return { ...args };
  }

  private cloneBlueprint(blueprint: SessionBlueprint): SessionBlueprint {
    return JSON.parse(JSON.stringify(blueprint)) as SessionBlueprint;
  }

  // --- Scope filtering helpers ---

  /**
   * Resolve scope filter string from optional scope options.
   * Returns undefined when no scope filtering should be applied.
   * Checks explicit continuityScopeId first, then resolves from workspaceId/organizationId.
   */
  private resolveScopeFilter(scope?: StateStoreOptions): string | undefined {
    if (!scope) return undefined;
    // Direct continuityScopeId takes precedence over workspace/org resolution
    if (scope.continuityScopeId && scope.continuityScopeId !== 'default') {
      return scope.continuityScopeId;
    }
    const resolved = resolveContinuityScopeId(scope);
    return resolved === 'default' ? undefined : resolved;
  }

  /**
   * Check if a session matches the resolved scope filter.
   * If no filter is set (undefined), all sessions match.
   */
  private matchesScope(session: ChainSession, scopeFilter: string | undefined): boolean {
    if (!scopeFilter) return true;
    return session.continuityScopeId === scopeFilter;
  }

  /**
   * Remove sessions for a chain that match the scope filter.
   * If no scope filter, removes all sessions for the chain (backward compatible).
   */
  private removeRunChainSessionsForScope(
    chainId: string,
    scopeFilter: string | undefined,
    release: RunRelease
  ): string[] {
    if (!scopeFilter) {
      return this.removeRunChainSessions(chainId, release);
    }

    const sessionIds = this.chainSessionMapping.get(chainId);
    const removedSessions: string[] = [];

    if (sessionIds) {
      for (const sessionId of [...sessionIds]) {
        const session = this.activeSessions.get(sessionId);
        if (session && this.matchesScope(session, scopeFilter)) {
          this.removeSessionArtifacts(sessionId, release);
          sessionIds.delete(sessionId);
          removedSessions.push(sessionId);
        }
      }
      // Clean up mapping if all sessions removed
      if (sessionIds.size === 0) {
        this.chainSessionMapping.delete(chainId);
      }
    }

    return removedSessions;
  }
}

export type {
  ChainSession,
  ChainSessionService,
  ChainSessionSummary,
  SessionBlueprint,
} from '#shared/types/chain-session.js';

/**
 * Create and configure a chain session store
 */
export function createChainSessionStore(
  logger: Logger,
  textReferenceStore: TextReferenceStore,
  options: ChainSessionStoreOptions = {},
  argumentHistoryTracker?: ArgumentHistoryTracker
): ChainSessionStore {
  return new ChainSessionStore(logger, textReferenceStore, options, argumentHistoryTracker);
}

/**
 * Store `review` at `reviews[review.nodeId]`: one review per node, and a review of one node never
 * displaces another node's (R14).
 *
 * @throws when `review` would overwrite a review of the other side of that split at its node —
 *   a current-step review keyed onto a detached node's open review, or the reverse. Both are
 *   unreachable today; a silent overwrite would lose an open review.
 */
/** What a mutator is about to change in memory, and how to put it back (R87). */
interface MemorySnapshot {
  restore(): void;
}

/** Make `target` hold exactly `source`'s entries, keeping `target`'s identity. */
function replaceMapContents<K, V>(target: Map<K, V>, source: ReadonlyMap<K, V>): void {
  target.clear();
  for (const [key, value] of source) target.set(key, value);
}

/**
 * Whether a persist failure is a lock another connection held past the busy timeout. Classified by
 * `node:sqlite`'s `errcode` (the extended result code): its low byte is the primary code, where 5
 * is `SQLITE_BUSY` and 6 is `SQLITE_LOCKED`. The message is not used, because a constraint
 * violation's text names the columns, never the class. A `SQLITE_CONSTRAINT` (primary 19) and any
 * error with no `errcode` are not transient.
 */
function isTransientLockError(error: unknown): boolean {
  const errcode = (error as { errcode?: unknown } | null)?.errcode;
  if (typeof errcode !== 'number') return false;
  const primary = errcode & 0xff;
  return primary === 5 || primary === 6;
}

function writeReview(session: ChainSession, review: GateReview): void {
  const reviews = { ...session.reviews };
  const detached = review.kind === 'detached';
  const occupant = reviews[review.nodeId];
  if (occupant !== undefined && (occupant.kind === 'detached') !== detached) {
    throw new Error(
      `Gate review of node '${review.nodeId}' (${review.kind}) would overwrite its open ${occupant.kind} review`
    );
  }
  reviews[review.nodeId] = review;
  session.reviews = reviews;
}

/**
 * Compose the gate remap a run carries with the one this process just applied (R69). `prior` maps
 * each recorded id to the id an earlier claimer registered, and the run's open reviews name those
 * ids; `current` maps recorded ids to this process's own. A recorded id `current` leaves out
 * registered here under itself. Returns the run's new map (identity entries dropped) and the
 * rewrite that carries every id a review may name, recorded or earlier-registered, to this
 * process's id. PURE.
 */
function composeGateRemap(
  prior: Readonly<Record<string, string>>,
  current: ReadonlyMap<string, string>
): { applied: Record<string, string>; rewrite: Map<string, string> } {
  const earlierIds = new Map(Object.entries(prior));
  const applied: Record<string, string> = {};
  const rewrite = new Map<string, string>();
  for (const recorded of new Set([...earlierIds.keys(), ...current.keys()])) {
    const registered = current.get(recorded) ?? recorded;
    if (registered !== recorded) {
      applied[recorded] = registered;
      rewrite.set(recorded, registered);
    }
    const earlier = earlierIds.get(recorded);
    if (earlier !== undefined && earlier !== registered) rewrite.set(earlier, registered);
  }
  return { applied, rewrite };
}

/** True when two gate remaps hold the same entries. PURE. */
function sameGateRemap(
  left: Readonly<Record<string, string>>,
  right: Readonly<Record<string, string>>
): boolean {
  const rightEntries = new Map(Object.entries(right));
  const leftEntries = Object.entries(left);
  return (
    leftEntries.length === rightEntries.size &&
    leftEntries.every(([key, value]) => rightEntries.get(key) === value)
  );
}

/** Every gate id an open review names: its gates, its rendered prompts and its tier map. */
function reviewGateIds(review: GateReview): string[] {
  return [
    ...review.gateIds,
    ...review.prompts.flatMap((prompt) => (prompt.gateId === undefined ? [] : [prompt.gateId])),
    ...Object.keys(review.gateTiers ?? {}),
  ];
}

/**
 * A copy of `review` naming each gate through `remap` (R60 amended) wherever the render and the
 * verdict read a gate id. `history` and `checkResults` stay as recorded: they are what happened.
 */
function remapReviewGateIds(review: GateReview, remap: ReadonlyMap<string, string>): GateReview {
  const to = (id: string): string => remap.get(id) ?? id;
  const copy = cloneReview(review);
  return {
    ...copy,
    gateIds: copy.gateIds.map(to),
    prompts: copy.prompts.map((prompt) =>
      prompt.gateId === undefined ? prompt : { ...prompt, gateId: to(prompt.gateId) }
    ),
    ...(copy.gateTiers !== undefined && {
      gateTiers: Object.fromEntries(
        Object.entries(copy.gateTiers).map(([id, tier]) => [to(id), tier])
      ),
    }),
  };
}

/** Remove the review of `nodeId`; `reviews` goes when it empties. */
function deleteReview(session: ChainSession, nodeId: string): void {
  if (session.reviews === undefined) return;
  const { [nodeId]: _removed, ...rest } = session.reviews;
  if (Object.keys(rest).length > 0) session.reviews = rest;
  else delete session.reviews;
}

/** A copy that shares no array or object with `review`, so neither side can mutate the other. */
function cloneReview(review: GateReview): GateReview {
  return {
    ...review,
    gateIds: [...review.gateIds],
    prompts: review.prompts.map((prompt) => {
      const mappedPrompt: GateReviewPrompt = { ...prompt };
      if (prompt.explicitInstructions !== undefined) {
        mappedPrompt.explicitInstructions = [...prompt.explicitInstructions];
      }
      if (prompt.metadata !== undefined) {
        mappedPrompt.metadata = { ...prompt.metadata };
      }
      return mappedPrompt;
    }),
    ...(review.retryHints !== undefined && { retryHints: [...review.retryHints] }),
    ...(review.history !== undefined && {
      history: review.history.map((entry) => ({ ...entry })),
    }),
    ...(review.metadata !== undefined && { metadata: { ...review.metadata } }),
  };
}
