// @lifecycle canonical - Prompt create/update/delete operations.

import * as path from 'node:path';

import { PromptDraftService, type PromptDraftInput } from './prompt-draft-service.js';
import {
  normalizeReloadShape,
  PromptMutationReceiptService,
  type PromptMutationReceipt,
} from './prompt-mutation-receipt-service.js';
import { isPreviewRequest } from '../../../shared/preview-action.js';
import { formatRepairServingLine } from '../../../shared/quarantine-report.js';
import { ComparisonEngine } from '../analysis/comparison-engine.js';
import { ObjectDiffGenerator, type DiffResult } from '../analysis/object-diff-generator.js';
import { PromptAnalyzer } from '../analysis/prompt-analyzer.js';
import { PromptResourceContext } from '../core/context.js';
import { mergeArgumentUpdates, type PromptArgumentUpdate } from '../operations/argument-updates.js';
import {
  ALL_PROMPT_DATA_KEYS,
  FileOperations,
  NO_WRITE_INTENT,
  type PromptWriteIntent,
} from '../operations/file-operations.js';
import {
  PATCH_TARGET_FIELDS,
  applyTemplatePatches,
  findPatchParameterConflict,
  type PatchTargetField,
  type TemplatePatchOperation,
} from '../operations/template-patch.js';
import { mutationHeadline } from '../utils/mutation-headline.js';
import {
  UPDATE_FIELDS,
  type PromptWriteDefect,
  applyChainStepOperation,
  diagnosePromptWrite,
  type PromptWriteChecks,
  resolveUnsetFields,
  validateChainStepReferences,
  validateRequiredFields,
  validateToolDefinitions,
} from '../utils/validation.js';

import type { ConvertedPrompt } from '#engine/execution/types.js';
import type { PromptData } from '#modules/prompts/types.js';
import type { QuarantinedResource } from '#shared/utils/resource-quarantine.js';
import type { PromptResourceInput } from '../../core/types.js';

import { PromptReferenceValidator } from '#engine/execution/reference/index.js';
import { purgeHistoryOnDelete } from '#modules/versioning/delete-purge.js';
import {
  createRowDescription,
  updateRowDescription,
  canonicalPromptSnapshot,
  describeVersionRecord,
} from '#modules/versioning/index.js';
import { ToolResponse } from '#shared/types/index.js';
import { PromptError } from '#shared/utils/index.js';
import { preferredRepairTarget } from '#shared/utils/resource-quarantine.js';

export class PromptLifecycleProcessor {
  private readonly context: PromptResourceContext;
  private readonly promptAnalyzer: PromptAnalyzer;
  private readonly comparisonEngine: ComparisonEngine;
  private readonly textDiffService: ObjectDiffGenerator;
  private readonly fileOperations: FileOperations;
  private readonly draftService: PromptDraftService;
  private readonly receiptService: PromptMutationReceiptService;

  constructor(context: PromptResourceContext) {
    this.context = context;
    this.promptAnalyzer = context.promptAnalyzer;
    this.comparisonEngine = context.comparisonEngine;
    this.textDiffService = context.textDiffService;
    this.fileOperations = context.fileOperations;
    this.draftService = new PromptDraftService(
      () => this.getConvertedPrompts(),
      this.writeChecks()
    );
    this.receiptService = new PromptMutationReceiptService(context);
  }

  /** The checks a produced prompt answers to beyond its own text (P6.192). */
  private writeChecks(): PromptWriteChecks {
    const { isCanonicalGateId } = this.context.dependencies;
    return isCanonicalGateId !== undefined ? { isCanonicalGateId } : {};
  }

  async validatePrompt(args: PromptDraftInput): Promise<ToolResponse> {
    const result = this.draftService.prepare(args);
    if (!result.valid) {
      return {
        content: [
          {
            type: 'text' as const,
            text: `❌ **Prompt draft invalid** — nothing written, no version recorded.\n\n${result.errors
              .map((error) => `- ${error}`)
              .join('\n')}`,
          },
        ],
        structuredContent: {
          action: 'validate',
          valid: false,
          errors: result.errors,
          mutated: false,
        },
        isError: true,
      };
    }

    const currentVersion = await this.getCurrentVersion(result.draft.canonicalId);
    return {
      content: [
        {
          type: 'text' as const,
          text:
            `✅ **Prompt draft valid**: \`${result.draft.canonicalId}\`\n\n` +
            `Nothing written; no version recorded. Re-send with action:"create" to persist it.`,
        },
      ],
      structuredContent: {
        action: 'validate',
        valid: true,
        normalized_id: result.draft.canonicalId,
        draft: result.draft.promptData,
        current_version: currentVersion,
        mutated: false,
      },
      isError: false,
    };
  }

  async createPrompt(args: PromptDraftInput): Promise<ToolResponse> {
    const prepared = this.draftService.prepare(args);
    if (!prepared.valid) {
      return {
        content: [
          {
            type: 'text' as const,
            text: `❌ **Prompt creation blocked** — nothing written.\n\n${prepared.errors
              .map((error) => `- ${error}`)
              .join('\n')}`,
          },
        ],
        structuredContent: {
          action: 'create',
          valid: false,
          errors: prepared.errors,
          mutated: false,
        },
        isError: true,
      };
    }

    const promptData = prepared.draft.promptData as any;
    const { canonicalId } = prepared.draft;
    const displayName = String(promptData['name']);
    const description = String(promptData['description']);

    // The created state is recorded as version 1 — the same `saveVersion` numbering every edit
    // uses (MAX(existing)+1), which a resource with no rows yet resolves to 1 on its own. No
    // bridge: a create has no prior live state to carry across, unlike an edit of an unrecorded
    // resource. Runs as the writer transaction's `commit` step (P4.2 / SF-3 contract, matching
    // `updatePrompt` below) so a persistence failure aborts the create with nothing written.
    //
    // Recorded through `canonicalPromptSnapshot` + `normalizeReloadShape` — the SAME projection
    // and loader-default normalization `PromptMutationReceiptService` applies to the "expected"
    // side of its own post-refresh comparison. Measured: recording the raw draft `promptData`
    // carried keys the loader never produces (`isChain`, `tools`) and omitted `systemMessage`'s
    // loader default, so the first update's prior-state check never matched and always bridged.
    let versionFailure: string | undefined;
    const skipVersion = args.skip_version === true;
    const commitOptions =
      this.context.versionHistoryService.isAutoVersionEnabled() && !skipVersion
        ? {
            commit: async (): Promise<void> => {
              try {
                await this.context.versionHistoryService.saveVersion(
                  'prompt',
                  canonicalId,
                  normalizeReloadShape(canonicalPromptSnapshot(canonicalId, promptData)),
                  { description: createRowDescription('resource_manager'), diff_summary: '' }
                );
              } catch (error) {
                versionFailure = error instanceof Error ? error.message : String(error);
                throw error;
              }
            },
          }
        : {};

    // `create` owns the WHOLE state being written — there is no prior file to narrow a scope
    // against — so it passes the full key set rather than computing one (Fix B, tier-b-
    // settability-proposal §2 / §5 increment 3).
    let writeResult;
    try {
      writeResult = await this.fileOperations.updatePromptImplementation(
        promptData,
        ALL_PROMPT_DATA_KEYS,
        undefined,
        NO_WRITE_INTENT,
        commitOptions
      );
    } catch (error) {
      if (versionFailure === undefined) throw error;

      this.context.dependencies.logger.error(
        `Aborting creation of prompt ${canonicalId}: ${versionFailure}`
      );
      return {
        content: [
          {
            type: 'text' as const,
            text:
              `❌ **Prompt creation aborted**: the version snapshot could not be saved.\n\n` +
              `${versionFailure}\n\n` +
              `💡 Nothing was written for '${canonicalId}'. Retry, or pass ` +
              `\`skip_version: true\` to create without recording a version.`,
          },
        ],
        isError: true,
      };
    }
    const analysis = await this.promptAnalyzer.analyzePromptIntelligence(promptData);

    // The headline is composed at the END, once verification has run — see `mutationHeadline`.
    let response = `📝 ${description}\n`;
    response += `${analysis.feedback}`;

    if (analysis.suggestions.length > 0) {
      response += `💡 ${analysis.suggestions.join(' • ')}\n`;
    }

    if (promptData.gateConfiguration) {
      response += `\n🔒 **Gate Configuration Applied**:\n`;
      if (promptData.gateConfiguration.include) {
        response += `- Include Gates: ${promptData.gateConfiguration.include.join(', ')}\n`;
      }
      if (promptData.gateConfiguration.inline_gate_definitions) {
        response += `- Inline Gate Definitions: ${promptData.gateConfiguration.inline_gate_definitions.length} defined\n`;
      }
      // No explicit gate configuration: offer rule-based recommendations. This was previously
      // gated on an LLM-integration flag that defaulted off, which hid `GateAnalyzer` output
      // that never depended on a model.
    } else {
      try {
        const gateAnalysis = await this.context.gateAnalyzer.analyzePromptForGates({
          id: promptData.id,
          name: promptData.name,
          category: promptData.category,
          description: promptData.description,
          userMessageTemplate: promptData.userMessageTemplate,
          systemMessage: promptData.systemMessage,
          arguments: promptData.arguments || [],
        });

        if (gateAnalysis.recommendedGates.length > 0) {
          response += `\n💡 **Suggested Gates**: Consider adding these gates:\n`;
          gateAnalysis.recommendedGates.slice(0, 3).forEach((gate) => {
            response += `- ${gate}\n`;
          });
          response += `Use \`update\` action with \`gate_configuration\` parameter to add gates.\n`;
        }
      } catch (error) {
        this.context.dependencies.logger.warn('Failed to analyze gates for new prompt:', error);
      }
    }

    if (promptData.tools && promptData.tools.length > 0) {
      response += `\n🔧 **Script Tools Created**: ${promptData.tools.length} tool(s)\n`;
      for (const tool of promptData.tools) {
        response += `- \`${tool.id}\`: ${tool.name}`;
        if (tool.trigger && tool.trigger !== 'schema_match') {
          response += ` (trigger: ${tool.trigger})`;
        }
        response += '\n';
      }
    }

    const verification = await this.receiptService.complete({
      action: 'create',
      id: canonicalId,
      expectedPrompt: promptData,
      operation: writeResult,
      fullRestart: args.full_restart === true,
      refresh: () => this.context.dependencies.onRefresh(),
      reason: `Prompt created: ${canonicalId}`,
    });
    response += this.formatMutationReceipt(verification.receipt);

    return {
      content: [
        {
          type: 'text' as const,
          text: mutationHeadline('Created', displayName, canonicalId, verification) + response,
        },
      ],
      structuredContent: {
        action: 'create',
        valid: true,
        receipt: verification.receipt,
        mutated: true,
      },
      isError: !verification.verified,
    };
  }

  async updatePrompt(args: any): Promise<ToolResponse> {
    validateRequiredFields(args, ['id']);

    const currentPrompt = this.getConvertedPrompts().find((prompt) => prompt.id === args.id);
    // The repair target: a file on disk the loader refused, whose id nothing in the catalog
    // answers to. Consulted ONLY when the catalog has no entry, so a serving prompt is never
    // redirected by a quarantined namesake — the valid resource wins unconditionally, because
    // resolution never looks here.
    //
    // Without this, an update on an unloadable id produced the worst available outcome. Measured
    // 2026-09-11 against `dist/`: `update` with a full body answered `✅ **Prompt Updated**` and
    // wrote a SECOND prompt at `general/<id>` — the category `canonicalPromptSnapshot` falls back
    // to — reported `Moved prompt '<id>' from '<id>' to 'general'` (nothing moved), and left the
    // broken file exactly as it was. The record supplies the true category and root, so the write
    // lands on the file that is actually broken.
    // Read once and reused below (`resolveRepairTarget`, the P4.59 refusal): a second
    // `String(args.id)` call site would be a second unsafe access on the same `any` for no
    // reason `requestedId` does not already cover.
    const requestedId = String(args.id);
    const repairTarget =
      currentPrompt === undefined ? this.resolveRepairTarget(requestedId) : undefined;

    // P4.59 — an id that is neither loaded nor quarantined is refused HERE, before any patch or
    // diagnosis logic runs. Without this, `updatePrompt` fell through to the same path a repair
    // uses (`canonicalPromptSnapshot(id, undefined)` — an empty draft, `category: 'general'`) for
    // an id nobody asked to create, and the first thing to notice was whichever check the empty
    // draft failed first: a `patch` against `id:"plan_table"` (only addressable as
    // `implementation_plan/plan_table`) reached `applyTemplatePatches` against an empty
    // `userMessageTemplate` and refused `anchor_not_found` — a true statement about an anchor
    // that was never going to exist, pointing at the wrong cause.
    if (currentPrompt === undefined && repairTarget === undefined) {
      return this.refuseUnknownPromptId(requestedId);
    }
    const concurrencyRefusal = await this.checkExpectedVersion(args as PromptResourceInput);
    if (concurrencyRefusal !== undefined) {
      return concurrencyRefusal;
    }
    let beforeAnalysis = null;
    // Projected, not spread: a raw ConvertedPrompt carries loader-resolved runtime keys the
    // recorded snapshot shape never has, which would make recordEditResult's bridge check see
    // every post-reload edit as out-of-band (see canonicalPromptSnapshot).
    const beforeContent =
      currentPrompt !== undefined
        ? (canonicalPromptSnapshot(args.id, currentPrompt) as unknown as ConvertedPrompt)
        : null;

    if (currentPrompt) {
      beforeAnalysis = await this.promptAnalyzer.analyzePrompt(currentPrompt);
    }

    if (args.tools && args.tools.length > 0) {
      const toolErrors = validateToolDefinitions(args.tools);
      if (toolErrors.length > 0) {
        const errorDetails = toolErrors.map((e) => `• ${e}`).join('\n');
        return {
          content: [
            {
              type: 'text' as const,
              text: `❌ **Prompt update blocked** due to tool validation errors:\n\n${errorDetails}\n\n💡 Check tool definitions for required fields (id, name, script) and valid values.`,
            },
          ],
          isError: true,
        };
      }
    }

    // Build base from existing prompt, then override only explicitly provided fields. The base
    // is the same projection `beforeContent` uses, so the bridge check and every diff compare
    // like against like; `tools` rides on top because it only ever arrives via `args.tools`.
    const promptData: any = {
      ...canonicalPromptSnapshot(args.id, currentPrompt),
      tools: args.tools,
    };

    // Ahead of the `UPDATE_FIELDS` merge, so an explicitly supplied `category` still wins and
    // still moves the prompt. What this replaces is the FALLBACK: `canonicalPromptSnapshot`
    // defaults an unknown prompt's category to `general`, which for a quarantined file is a
    // category it does not live in.
    if (repairTarget !== undefined) {
      promptData.category = repairTarget.category;
    }

    // Fix B (tier-b-settability-proposal §2 write-scope narrowing): the union of every
    // `promptData` key THIS call actually touches. `FileOperations` uses it to decide which
    // files get rewritten — a key absent here means the corresponding on-disk file is left
    // untouched (byte-identical), not re-derived from a possibly-lossier in-memory projection
    // (§1.1 churn). Built incrementally alongside the same mutations that populate `promptData`
    // below, so the two cannot drift apart.
    const suppliedKeys = new Set<string>();

    for (const [argKey, dataKey] of Object.entries(UPDATE_FIELDS)) {
      if (args[argKey] !== undefined) {
        promptData[dataKey] = args[argKey];
        suppliedKeys.add(dataKey);
      }
    }
    // `gate_configuration` flows through UPDATE_FIELDS like every other field. It carried a
    // hand-written special case here until 2026-08-06 (row 1.6) whose only purpose was accepting
    // the [Framework] `gates` parameter as an alias — accepted on update, silently ignored on
    // create. That asymmetry is what settled it as unintended rather than designed.

    // `tools` never flows through `UPDATE_FIELDS` (it arrives via `args.tools` directly, above)
    // — its own entry in `suppliedKeys` accordingly needs its own check.
    if ((args as { tools?: unknown }).tools !== undefined) {
      suppliedKeys.add('tools');
    }

    // Narrowed once rather than reaching into `any` at each use, matching `deletePrompt` below.
    // `promptData` is read through an indexed `Record` for the same reason. Declared here (ahead
    // of both Fix D and the patch block) because both read `suppliedArgs`/`promptFields`.
    const { patch: patchArgument } = args as { patch?: TemplatePatchOperation[] };
    const suppliedArgs = args as Record<string, unknown>;
    const promptFields = promptData as Record<string, unknown>;

    // Fix D (tier-b-settability-proposal §2 / P6-F16): `argument_updates` overlays fields onto
    // EXISTING arguments by `name` — the patch vocabulary (`PATCH_TARGET_FIELDS`) only reaches
    // the three text bodies, and anchored string replacement cannot address WHICH argument.
    // Mutually exclusive with `arguments` in the same call (the `findPatchParameterConflict`
    // pattern below): accepting both would make the result depend on an evaluation order the
    // caller cannot see. Runs BEFORE `diagnosePromptWrite` and the version record below — same
    // placement invariant as `patch` — so `promptFields.arguments` reaches both already merged,
    // and an equivalent full-`arguments` update records the identical snapshot and diff.
    const argumentUpdates = suppliedArgs['argument_updates'] as PromptArgumentUpdate[] | undefined;
    if (argumentUpdates !== undefined && argumentUpdates.length > 0) {
      if (suppliedArgs['arguments'] !== undefined) {
        return this.blockedUpdate(
          '❌ **Prompt update blocked**: `argument_updates` cannot be combined with `arguments` ' +
            'in the same call. Send the full array, or overlay named fields onto existing ' +
            'arguments — not both.'
        );
      }

      const baseArguments = (
        Array.isArray(promptFields['arguments']) ? promptFields['arguments'] : []
      ) as Record<string, unknown>[];
      const mergeResult = mergeArgumentUpdates(baseArguments, argumentUpdates);
      if (!mergeResult.ok) {
        return this.blockedUpdate(
          `❌ **Prompt update blocked**: \`argument_updates\` names \`${mergeResult.unmatchedName}\`, ` +
            `which is not an argument of this prompt. \`argument_updates\` overlays existing ` +
            `arguments only — it cannot add one. Use \`arguments\` to add, remove, or rename ` +
            `arguments.\n\n💡 Nothing was written and no version was consumed.`
        );
      }

      promptFields['arguments'] = mergeResult.arguments;
      suppliedKeys.add('arguments');
    }

    // Anchored patches (P7 row 3.4) apply AFTER the UPDATE_FIELDS merge and BEFORE reference
    // validation, the version record and the write. That placement is what makes acceptance (c)
    // hold: `promptData` reaches `recordEditResult` already patched, so a patch and the equivalent
    // full update record the identical snapshot and diff. Any hook after the version record would
    // version the unpatched state.
    const patchOperations = patchArgument ?? [];
    const patchedFields: PatchTargetField[] = [];
    if (patchOperations.length > 0) {
      const suppliedBodyParameters = PATCH_TARGET_FIELDS.filter(
        (parameter) => suppliedArgs[parameter] !== undefined
      );
      const conflict = findPatchParameterConflict(suppliedBodyParameters, patchOperations);
      if (conflict !== undefined) {
        return this.blockedUpdate(`❌ **Prompt update blocked**: ${conflict}`);
      }

      const patchResult = applyTemplatePatches(
        {
          user_message_template: promptFields['userMessageTemplate'] as string | undefined,
          system_message: promptFields['systemMessage'] as string | undefined,
          description: promptFields['description'] as string | undefined,
        },
        patchOperations
      );

      if (!patchResult.ok) {
        return this.blockedUpdate(
          `❌ **Prompt update blocked** — patch not applied (${patchResult.rejection.reason}):\n\n${patchResult.rejection.message}\n\n💡 Nothing was written and no version was consumed. Use \`action:"inspect"\` to read the current text, or \`action:"preview"\` with \`preview_action:"update"\` to test an anchor.`
        );
      }

      for (const [field, value] of Object.entries(patchResult.values)) {
        // `UPDATE_FIELDS` already owns the parameter-name → promptData-key mapping for all three
        // patch targets; a second map here would be the drift this file has fixed twice.
        const dataKey = UPDATE_FIELDS[field] as string;
        promptFields[dataKey] = value;
        patchedFields.push(field as PatchTargetField);
        suppliedKeys.add(dataKey);
      }
    }

    // Chain step-level operations (add/remove/reorder/update). Omitting the parameter is how a
    // caller replaces the array wholesale — which is what `'replace'` used to spell as a second,
    // redundant way of saying the same thing (P2.4).
    if (args.chain_step_operation) {
      const existingSteps = (currentPrompt?.chainSteps ?? []) as unknown[];
      promptData.chainSteps = applyChainStepOperation(existingSteps, {
        operation: args.chain_step_operation,
        index: args.chain_step_index,
        stepData: args.chain_step_data,
        order: args.chain_step_order,
      });
      suppliedKeys.add('chainSteps');
    }

    // P2.3 — the tool binding's own remove verb. Three intents, and only one of them destroys
    // anything: omitting `tool_operation` REPLACES the binding (so a narrowed `tools` array
    // unbinds and leaves `tools/{id}/` on disk), `'add'` unions, and `'remove'` unbinds AND
    // deletes the directories. The deletion is why `'remove'` demands `confirm` while the other
    // two do not — it is the only `update` that destroys a file for which the caller sent no
    // replacement, and `DESTRUCTIVE_ACTIONS` cannot express it because the ACTION is `update`.
    let toolBinding: 'replace' | 'add' = 'replace';
    let removedToolIds: readonly string[] = [];
    const requestedToolIds: string[] = (suppliedArgs['tool_ids'] as string[] | undefined) ?? [];

    if (args.tool_operation === 'add') {
      if (!Array.isArray(args.tools) || args.tools.length === 0) {
        return this.blockedUpdate(
          '❌ **Prompt update blocked**: `tool_operation: "add"` needs the `tools` definitions to ' +
            'add. To unbind instead, send a narrowed `tools` array; to delete, use ' +
            '`tool_operation: "remove"`.'
        );
      }
      toolBinding = 'add';
    } else if (args.tool_operation === 'remove') {
      if (requestedToolIds.length === 0) {
        return this.blockedUpdate(
          '❌ **Prompt update blocked**: `tool_operation: "remove"` needs `tool_ids` naming what ' +
            'to remove.'
        );
      }
      if (args.confirm !== true) {
        return this.blockedUpdate(
          `⚠️ **Prompt update blocked**: removing ${requestedToolIds.map((id) => `\`${id}\``).join(', ')} ` +
            `deletes their \`tools/{id}/\` directories, which no other update does. Re-send the ` +
            `same call with \`confirm: true\`.\n\n` +
            `💡 To unbind without deleting, send a \`tools\` array without them instead.`
        );
      }
      removedToolIds = requestedToolIds;
      // The subtraction happens in the writer (only it can read the current binding), but the
      // yaml must be REWRITTEN for that to reach disk — so this call touches `tools`.
      suppliedKeys.add('tools');
    } else if (requestedToolIds.length > 0) {
      // A parameter that silently does nothing is worse than a refusal: it reads as a removal
      // that happened.
      return this.blockedUpdate(
        '❌ **Prompt update blocked**: `tool_ids` only applies to `tool_operation: "remove"`. ' +
          'Nothing was removed.'
      );
    }

    // P2.1 — the "remove" verb (owner ruling D1). Deliberately LAST of the field-writing blocks:
    // the conflict check reads `suppliedKeys`, so by running after `UPDATE_FIELDS`,
    // `argument_updates`, `patch` and the chain-step operation it sees every data key this call
    // writes, whatever parameter name delivered it. Checking parameter names instead would miss
    // `unset: ['arguments']` sent alongside `argument_updates`, which write the same key under
    // different names.
    //
    // Clearing joins `suppliedKeys` because a cleared field IS a field this call touches. Without
    // that, Fix B's write-scope narrowing would leave `prompt.yaml` unopened and the removal would
    // be a silent no-op — the same shape as the preserve-on-omit trap in the writer.
    const unsetArgument = suppliedArgs['unset'] as string[] | undefined;
    let unsetKeys: ReadonlySet<string> = NO_WRITE_INTENT.unsetKeys;
    if (unsetArgument !== undefined && unsetArgument.length > 0) {
      const resolved = resolveUnsetFields(unsetArgument, suppliedKeys);
      if (!resolved.ok) {
        return this.blockedUpdate(
          `❌ **Prompt update blocked**: ${resolved.message}\n\n` +
            `💡 Nothing was written and no version was consumed.`
        );
      }
      unsetKeys = resolved.dataKeys;
      for (const dataKey of unsetKeys) {
        delete promptFields[dataKey];
        suppliedKeys.add(dataKey);
      }
    }

    // A step naming a prompt that does not exist is a refusal, not a warning next to a saved
    // file: the run used to fail at that step one invocation later, far from the write that
    // introduced it. The chain's own `<chainId>/<step>` children are exempt — the write below
    // scaffolds exactly those.
    //
    // Scoped to steps THIS call authors, which is what `suppliedKeys` means everywhere else in
    // this method. A caller that sends `edges` or `unset` and no chain-step parameter is not
    // writing a step, and blocking it would make a chain already broken on disk uneditable —
    // including by the edit that repairs it. That is the split `diagnosePromptWrite` already
    // draws below between `blocking` (introduced by this edit) and `preExisting` (logged, not
    // blocked), applied to the same question one paragraph earlier.
    if (promptData.chainSteps && promptData.chainSteps.length > 0) {
      // Read the id through `promptFields`, the indexed `Record` this method already uses for
      // exactly this reason — `promptData` is `any` and a member access on it is unchecked.
      const chainId = String(promptFields['id']);
      const chainIntegrity = validateChainStepReferences(
        promptData.chainSteps,
        chainId,
        this.getConvertedPrompts().map((p) => p.id)
      );
      if (!chainIntegrity.valid) {
        if (suppliedKeys.has('chainSteps')) {
          return this.blockedUpdate(
            `❌ **Prompt update blocked** — a chain step names a prompt that does not exist:\n\n` +
              `${chainIntegrity.problems.map((problem) => `- ${problem}`).join('\n')}\n\n` +
              `💡 Nothing was written and no version was consumed. Create the missing prompt, or ` +
              `nest the step under '${chainId}/' so this call scaffolds it.`
          );
        }
        this.context.dependencies.logger.warn(
          `Chain '${chainId}' has pre-existing unresolvable chain step(s) (not introduced by ` +
            `this edit): ${chainIntegrity.problems.join('; ')}`
        );
      }
    }

    // Reference validation for template changes. A patch changes a template without any full-body
    // parameter arriving, so the patched fields have to arm this the same way — otherwise a patch
    // could introduce a `{{ref:missing}}` that a full update would have been refused for.
    const hasTemplateChange =
      typeof args.user_message_template === 'string' ||
      typeof args.system_message === 'string' ||
      patchedFields.some((field) => field !== 'description');
    if (hasTemplateChange) {
      const refValidator = new PromptReferenceValidator(this.getConvertedPrompts());
      const refValidation = refValidator.validate(
        args.id,
        promptData.userMessageTemplate as string,
        promptData.systemMessage as string | undefined
      );

      if (!refValidation.valid) {
        const errorDetails = refValidation.errors
          .map((e) => `• **${e.type}**: ${e.details}`)
          .join('\n');
        return {
          content: [
            {
              type: 'text' as const,
              text: `❌ **Prompt update blocked** due to reference errors:\n\n${errorDetails}\n\n💡 Ensure all referenced prompts exist before updating this prompt.`,
            },
          ],
          isError: true,
        };
      }
    }

    // Produced-state validation (P7 row 3.5). Runs BEFORE the version record, so a rejected update
    // consumes nothing — the write path's own `ResourceVerificationService` check
    // (file-operations.ts:183) only fires after a version has already been spent, and it cannot see
    // a template-syntax error at all because YAML schema validation does not compile Nunjucks.
    const diagnosis = diagnosePromptWrite(beforeContent, promptData, this.writeChecks());
    if (diagnosis.blocking.length > 0) {
      const details = diagnosis.blocking.map((defect) => `• ${defect.message}`).join('\n');
      return this.blockedUpdate(
        `❌ **Prompt update blocked** — the resulting prompt is invalid:\n\n${details}\n\n` +
          (repairTarget !== undefined
            ? `🚧 \`${repairTarget.id}\` is quarantined — the file at \`${repairTarget.path}\` ` +
              `failed to load (${repairTarget.error}), so there is no loaded state to merge onto ` +
              `and a repair has to supply the whole prompt. The content that failed validation is ` +
              `deliberately not read back here.\n\n`
            : '') +
          `💡 Nothing was written and no version was consumed.`
      );
    }
    if (diagnosis.preExisting.length > 0) {
      this.context.dependencies.logger.warn(
        `Prompt ${promptData.id} has pre-existing template defects (not introduced by this edit): ${diagnosis.preExisting
          .map((defect) => defect.message)
          .join('; ')}`
      );
    }

    // One projection of the write serves the preview, the version's diff summary and the update's
    // own diff. It is resolved from the plan the writer applies, with the arguments the writer is
    // handed below, so every diff this call reports names the files the write lands in and the
    // lines that change in them.
    const writeIntent: PromptWriteIntent = { unsetKeys, toolBinding, removedToolIds };
    const diffResult = this.textDiffService.generateFileChangeDiff(
      await this.fileOperations.projectPromptWrite(
        promptData,
        suppliedKeys,
        currentPrompt?.sourceRoot,
        writeIntent
      )
    );

    // A preview returns the produced bodies and the diff and stops here — ahead of the version
    // record and the write, so neither happens. It is the operator's pre-check that an anchor
    // matched before a version is spent.
    if (isPreviewRequest(args)) {
      return this.renderPreview(promptData, diffResult, patchedFields, diagnosis.preExisting);
    }

    // `recordEditResult` throws on persistence failure (P7-D2, OQ-P7-6), and the update ABORTS on
    // it: `version_history` is durable and nothing regenerates its rows, so content written past a
    // failed snapshot leaves an unrecoverable gap while reporting success. Go-forward numbering
    // (OQ-P7-3): the recorded snapshot is the state this edit PRODUCES, so the newest version
    // equals what `inspect` shows; any unrecorded prior state gets a bridge row first (era
    // transition, out-of-band edit).
    //
    // The record used to run HERE, ahead of the write, so "nothing was written" held by ordering
    // alone — and the mirror failure (a write that lands with no version row) was reachable the
    // moment anyone flipped that order, which is what P4.2 / SF-3 found in all three processors.
    // It now runs as the write transaction's `commit` step: it happens only if the files were
    // written and verified, and if it throws the transaction restores them. `versionFailure` is
    // what lets this method still tell an operator WHICH half failed, since both now surface as
    // one rejected write.
    let versionOutcome: { version?: number; recorded: boolean } | undefined;
    let versionFailure: string | undefined;
    const skipVersion = args.skip_version === true;
    const commitOptions =
      beforeContent !== null &&
      this.context.versionHistoryService.isAutoVersionEnabled() &&
      !skipVersion
        ? {
            // Inlined rather than extracted to a helper on purpose — see the note in
            // `framework-lifecycle-processor.ts`: `validate:mutation-atomicity` reads the record's
            // position lexically, and a gate that cannot see the property is not guarding it.
            commit: async (): Promise<void> => {
              try {
                const versionResult = await this.context.versionHistoryService.recordEditResult(
                  'prompt',
                  promptData.id,
                  beforeContent as unknown as Record<string, unknown>,
                  { ...promptData },
                  {
                    description: updateRowDescription('resource_manager'),
                    diff_summary: `+${diffResult.stats.additions}/-${diffResult.stats.deletions}`,
                  }
                );
                versionOutcome = versionResult;
                this.context.dependencies.logger.debug(
                  `${versionResult.recorded ? 'Saved' : 'Matched'} version ${versionResult.version} for prompt ${promptData.id}`
                );
              } catch (error) {
                versionFailure = error instanceof Error ? error.message : String(error);
                throw error;
              }
            },
          }
        : {};

    // `currentPrompt.sourceRoot`, not `promptData` — provenance is deliberately absent from
    // `canonicalPromptSnapshot`, which is what `promptData` is built from, so that it never
    // reaches a version snapshot or a diff. It has to arrive as its own argument (P1.2).
    let result;
    try {
      result = await this.fileOperations.updatePromptImplementation(
        promptData,
        suppliedKeys,
        currentPrompt?.sourceRoot ?? repairTarget?.root,
        writeIntent,
        commitOptions
      );
    } catch (error) {
      if (versionFailure === undefined) throw error;

      this.context.dependencies.logger.error(
        `Aborting update of prompt ${promptData.id}: ${versionFailure}`
      );
      return {
        content: [
          {
            type: 'text' as const,
            text:
              `❌ **Prompt update aborted**: the version snapshot could not be saved.\n\n` +
              `${versionFailure}\n\n` +
              `💡 No changes were written to '${promptData.id}'. Retry, or pass ` +
              `\`skip_version: true\` to update without recording a version.`,
          },
        ],
        isError: true,
      };
    }
    const afterAnalysis = await this.promptAnalyzer.analyzePromptIntelligence(promptData);

    // The headline is composed at the END, once verification has run — see `mutationHeadline`.
    let response = `${result.message}\n\n`;

    if (patchedFields.length > 0) {
      response += `🩹 **Patched**: ${patchedFields.map((field) => `\`${field}\``).join(', ')} (${patchOperations.length} operation(s))\n\n`;
    }

    if (versionOutcome !== undefined) {
      response += `${describeVersionRecord(versionOutcome)}\n\n`;
    }

    if (diffResult.hasChanges) {
      response += `${diffResult.formatted}\n\n`;
    }

    response += `${afterAnalysis.feedback}\n`;

    if (beforeAnalysis) {
      const comparison = this.comparisonEngine.compareAnalyses(
        beforeAnalysis,
        afterAnalysis.classification,
        args.id
      );
      const displaySummary = this.comparisonEngine.generateDisplaySummary(comparison);
      if (displaySummary) {
        response += `\n${displaySummary}\n`;
      }
    }

    if (afterAnalysis.suggestions.length > 0) {
      response += `\n💡 **Improvement Suggestions**:\n`;
      afterAnalysis.suggestions.forEach((suggestion, i) => {
        response += `${i + 1}. ${suggestion}\n`;
      });
    }

    const verification = await this.receiptService.complete({
      action: 'update',
      id: String(args.id),
      expectedPrompt: promptData,
      operation: result,
      fullRestart: args.full_restart === true,
      refresh: () => this.context.dependencies.onRefresh(),
      reason: `Prompt updated: ${String(args.id)}`,
    });
    response += this.formatMutationReceipt(verification.receipt);
    if (repairTarget !== undefined) {
      response += this.formatRepairOutcome(repairTarget);
    }

    return {
      content: [
        {
          type: 'text' as const,
          text:
            mutationHeadline('Updated', String(promptData.name), String(args.id), verification) +
            response,
        },
      ],
      structuredContent: {
        action: 'update',
        receipt: verification.receipt,
        mutated: true,
      },
      isError: !verification.verified,
    };
  }

  async deletePrompt(args: any): Promise<ToolResponse> {
    validateRequiredFields(args, ['id']);

    // Narrowed once, immediately after the required-field check, rather than reaching into `any`
    // at each use. The parameter type is pre-existing; this at least keeps the destructive path
    // reading typed values, and stops every new reference adding another unsafe access.
    const { id, confirm } = args as { id: string; confirm?: boolean };

    const promptToDelete = this.getPromptsData().find((prompt) => prompt.id === id);
    if (!promptToDelete) {
      throw new PromptError(`Prompt not found: ${id}`);
    }

    const dependencies = this.findPromptDependencies(id);

    // BREAKING (major): `confirm` is now enforced on delete, as its schema text has always claimed.
    //
    // It was read on `rollback` and ignored here — the gate was on the RECOVERABLE verb and absent
    // from the unrecoverable one. Delete has no undo through the tool surface: the prompt's
    // `version_history` rows are purged with it (below), and were they kept they would be
    // unreachable anyway, since `handleRollback` returns "Prompt not found" once the prompt is
    // gone.
    //
    // The dependency list is computed BEFORE the gate so the refusal can name what would break.
    // Reporting the blast radius and then proceeding anyway — the previous behaviour — told the
    // caller exactly why to stop, after stopping was no longer possible.
    // A preview reports the same blast radius the refusal names, without needing the refusal — a
    // caller who already knows they want to delete can still see what it costs first. It sits
    // ABOVE the confirm gate, where the old `dry_run` branch could not: as a modifier on
    // `action:"delete"` it had to stay below the gate or it would have been a way to skip
    // confirming a real deletion — which meant an operator had to confirm the deletion in order to
    // be shown what it would cost. As its own action there is nothing to skip, because there is no
    // path from here to the removal below.
    if (isPreviewRequest(args)) {
      const blastRadius =
        dependencies.length > 0
          ? `\n⚠️ ${dependencies.length} prompt(s) reference it and would break:\n` +
            dependencies.map((dep) => `- ${dep.name} (${dep.id})`).join('\n') +
            '\n'
          : '';
      return {
        content: [
          {
            type: 'text' as const,
            text:
              `🔍 **Preview** — deletion of prompt '${id}' (${promptToDelete.name})\n\n` +
              `Nothing was removed.\n${blastRadius}\n` +
              `📜 Would also purge its \`version_history\` rows — a preview purges nothing\n\n` +
              `⚠️ Deletion cannot be undone — rollback cannot restore a deleted prompt.\n\n` +
              `💡 Re-send as \`action:"delete"\` with \`confirm: true\` to apply it.`,
          },
        ],
        isError: false,
      };
    }

    if (confirm !== true) {
      const blastRadius =
        dependencies.length > 0
          ? `\n\n⚠️ ${dependencies.length} prompt(s) reference it and would break:\n` +
            dependencies.map((dep) => `- ${dep.name} (${dep.id})`).join('\n')
          : '';
      return {
        content: [
          {
            type: 'text' as const,
            text:
              `⚠️ Deletion requires confirmation.\n\n` +
              `To delete prompt '${id}', set confirm: true.\n` +
              `This cannot be undone — rollback cannot restore a deleted prompt.${blastRadius}`,
          },
        ],
        isError: true,
      };
    }

    let response = `🗑️ **Deleting Prompt**: ${promptToDelete.name} (${id})\n\n`;

    if (dependencies.length > 0) {
      response += `⚠️ **Warning**: This prompt is referenced by ${dependencies.length} other prompts:\n`;
      dependencies.forEach((dep) => {
        response += `- ${dep.name} (${dep.id})\n`;
      });
      response += `\nDeleting will break these chain references.\n\n`;
    }

    const result = await this.fileOperations.deletePromptImplementation(args.id);
    response += `${result.message}\n\n`;

    // AFTER the removal, and only once it has returned. The other order destroys the rollback
    // history of a prompt still on disk when the removal fails, which is unrecoverable; this
    // order's failure mode is rows left behind, which is the state before this was wired.
    // Subtree-aware in the service, so a chain takes its steps' history (`chain/step`) with it.
    const purge = await purgeHistoryOnDelete(
      this.context.versionHistoryService,
      'prompt',
      id,
      'files removed'
    );
    if (purge.failure !== undefined) throw new PromptError(purge.failure);
    response += `📜 Version history purged: ${purge.removed} row(s)\n\n`;
    response += `✅ **Prompt successfully removed from system**\n`;

    await this.handleSystemRefresh(args.full_restart, `Prompt deleted: ${args.id}`);

    return {
      content: [{ type: 'text' as const, text: response }],
      isError: false,
    };
  }

  /** One shape for every pre-write refusal on the update path: error response, nothing written. */
  /**
   * The quarantine record an unqualified `update` on this id means, if any.
   *
   * WRITABLE root first: `preferredRepairTarget` prefers the primary because that is the root a
   * `resource_manager` write lands in, so an operator repairing `foo` edits the copy they can
   * actually edit rather than the bundled one they cannot. NOT precedence — since P4.27 the primary
   * is outranked by every overlay (`shared/utils/resource-root-lookup.ts` §resourceRootPrecedence),
   * and this docstring cited that precedence back when the two happened to agree.
   */
  private resolveRepairTarget(id: string): QuarantinedResource | undefined {
    const records = this.context.dependencies.quarantine?.byId(id) ?? [];
    if (records.length === 0) return undefined;
    return preferredRepairTarget(
      records,
      this.context.dependencies.configManager.getResolvedPromptsDirectory()
    );
  }

  /**
   * Say, in the update's own response, what happened to the refused file AND which root serves now.
   *
   * This is the row's falsifier rendered at the surface an operator reads. The receipt above
   * already forced a refresh, so the quarantine and the catalog have both been rebuilt from disk
   * by the time this runs: a record still standing for the same path means the file is still
   * refused, whatever the write reported. Saying nothing when the repair worked would leave "did
   * it load?" answerable only by a second call.
   *
   * THREE OUTCOMES, NOT TWO — the gate and framework twins had this split and prompts did not.
   * A prompt write always lands under `getResolvedPromptsDirectory()` (`planPromptWrite` composes
   * `promptDir` from it; `sourceRoot` only selects a subtree to copy IN, never where to write),
   * so a refused file in another root is left exactly as broken while a working copy appears in
   * the primary. Two outcomes reported that as `Still quarantined … the prompt remains absent
   * from the catalog`, and the second clause was false: the prompt was in the catalog, served
   * from the copy this call had just written. Reachable today — a malformed prompt in the bundled
   * tree whose id nothing else claims takes exactly this path.
   *
   * WHICH ROOT SERVES is measured, not inferred: `sourceRoot` off the reloaded catalog entry, the
   * stamp `PromptLoader` wrote. `formatRepairServingLine` is the one renderer allowed to turn that
   * into a sentence, so this and the two twins cannot drift.
   */
  private formatRepairOutcome(repairTarget: QuarantinedResource): string {
    const stillRefused = (this.context.dependencies.quarantine?.byId(repairTarget.id) ?? []).some(
      (record) => record.path === repairTarget.path
    );
    const writtenRoot = this.context.dependencies.configManager.getResolvedPromptsDirectory();
    const servedFrom = this.getConvertedPrompts().find(
      (prompt) => prompt.id === repairTarget.id
    )?.sourceRoot;
    const serving = formatRepairServingLine(repairTarget.id, writtenRoot, servedFrom);

    if (!stillRefused) {
      return (
        `\n🩹 **Repaired**: \`${repairTarget.path}\` now loads and its quarantine record is ` +
        `cleared.\n` +
        serving
      );
    }

    // Root, not full path: the write reuses the record's own category (`promptData.category` is
    // set from it above), so a record whose root IS the write root names the same file.
    if (path.resolve(repairTarget.root) !== path.resolve(writtenRoot)) {
      return (
        `\n🚧 **The refused file was in another root and was not touched.** This repair wrote ` +
        `your copy under \`${writtenRoot}\`; \`${repairTarget.path}\` stays quarantined.\n` +
        serving
      );
    }

    return (
      `\n🚧 **Still quarantined**: \`${repairTarget.path}\` did not load after the write — ` +
      `the prompt remains absent from the catalog.\n`
    );
  }

  /**
   * Refuse an `update` whose id is neither loaded nor quarantined (P4.59) — named as unknown,
   * ahead of any patch or diagnosis logic that would otherwise reach for content that does not
   * exist. A bare id that matches the last `/`-segment of exactly one loaded nested chain step is
   * the id-convention trap this row exists to catch (a step is only addressable by its composite
   * id, `parent/step`): named as a suggestion. Several matches are listed rather than guessed at.
   */
  private refuseUnknownPromptId(id: string): ToolResponse {
    const nestedMatches = this.getConvertedPrompts()
      .map((prompt) => prompt.id)
      .filter((promptId) => promptId.includes('/') && promptId.split('/').pop() === id);

    const suggestion =
      nestedMatches.length === 1
        ? `\n\n💡 \`${id}\` is only addressable by its composite id — did you mean \`${nestedMatches[0]}\`?`
        : nestedMatches.length > 1
          ? `\n\n💡 \`${id}\` matches several nested steps, each only addressable by its composite ` +
            `id: ${nestedMatches.map((match) => `\`${match}\``).join(', ')}.`
          : '';

    return this.blockedUpdate(
      `❌ **Prompt update blocked**: unknown prompt \`${id}\`. Nothing was written and no ` +
        `version was consumed.${suggestion}`
    );
  }

  private blockedUpdate(text: string): ToolResponse {
    return {
      content: [{ type: 'text' as const, text }],
      isError: true,
    };
  }

  /**
   * Render what an update WOULD produce. Reached only from the preview branch, which sits ahead
   * of both the version record and the file write, so this method is the whole effect of the call.
   */
  private renderPreview(
    promptData: Record<string, unknown>,
    diff: DiffResult,
    patchedFields: readonly PatchTargetField[],
    preExisting: readonly PromptWriteDefect[]
  ): ToolResponse {
    let text = `🔍 **Preview** — nothing written, no version recorded for \`${String(promptData['id'])}\`\n\n`;
    if (patchedFields.length > 0) {
      text += `🩹 Patched field(s): ${patchedFields.map((field) => `\`${field}\``).join(', ')}\n\n`;
    }
    text += diff.hasChanges
      ? `${diff.formatted}\n\n`
      : `No changes: the result is identical to the current prompt.\n\n`;

    for (const field of PATCH_TARGET_FIELDS) {
      const dataKey = UPDATE_FIELDS[field] as string;
      const value = promptData[dataKey];
      if (typeof value !== 'string' || value.length === 0) continue;
      text += `**Resulting \`${field}\`**:\n\n\`\`\`\n${value}\n\`\`\`\n\n`;
    }

    if (preExisting.length > 0) {
      text += `⚠️ **Pre-existing issues** (present before this edit, not blocking):\n`;
      text += preExisting.map((defect) => `- ${defect.message}`).join('\n');
      text += `\n\n`;
    }

    text += `💡 Re-send as \`action:"update"\` to apply it.`;

    return {
      content: [{ type: 'text' as const, text }],
      structuredContent: {
        action: 'preview',
        preview_action: 'update',
        id: String(promptData['id']),
        valid: true,
        mutated: false,
        has_changes: diff.hasChanges,
        diff: diff.diff,
        stats: diff.stats,
        resulting_prompt: promptData,
        warnings: preExisting.map((defect) => defect.message),
      },
      isError: false,
    };
  }

  private async checkExpectedVersion(args: PromptResourceInput): Promise<ToolResponse | undefined> {
    if (args.expected_version === undefined) return undefined;

    if (args.skip_version === true) {
      return this.blockedUpdate(
        '❌ **Prompt update blocked**: `expected_version` cannot be combined with ' +
          '`skip_version:true` because the concurrency token would not advance. Nothing was written.'
      );
    }
    if (!this.context.versionHistoryService.isAutoVersionEnabled()) {
      return this.blockedUpdate(
        '❌ **Prompt update blocked**: `expected_version` requires prompt versioning to be enabled. ' +
          'Nothing was written.'
      );
    }

    const currentVersion = await this.getCurrentVersion(String(args.id));
    if (currentVersion === args.expected_version) return undefined;

    return {
      content: [
        {
          type: 'text' as const,
          text:
            `❌ **Prompt update conflict**: expected version ${args.expected_version}, ` +
            `but '${String(args.id)}' is now version ${currentVersion}.\n\n` +
            `Nothing was written and no version was consumed. Inspect the prompt again, ` +
            `reapply the intended edit, and resend with expected_version:${currentVersion}.`,
        },
      ],
      structuredContent: {
        action: 'update',
        conflict: true,
        id: String(args.id),
        expected_version: args.expected_version,
        current_version: currentVersion,
        mutated: false,
      },
      isError: true,
    };
  }

  private async getCurrentVersion(id: string): Promise<number> {
    const history = await this.context.versionHistoryService.loadHistory('prompt', id);
    return history?.current_version ?? 0;
  }

  private formatMutationReceipt(receipt: PromptMutationReceipt): string {
    const files =
      receipt.affected_files.length > 0
        ? receipt.affected_files.map((file) => `\n- ${file}`).join('')
        : '\n- (none reported)';
    return (
      `\n📍 **Write Receipt**\n` +
      `- Resource root: \`${receipt.resource_root}\`\n` +
      `- Refresh: \`${receipt.refresh_status}\`\n` +
      `- Current version: \`${receipt.current_version}\`\n` +
      `- Affected files:${files}\n`
    );
  }

  private async handleSystemRefresh(fullRestart: boolean = false, reason: string): Promise<void> {
    if (fullRestart) {
      setTimeout(() => this.context.dependencies.onRestart(reason), 1000);
    } else {
      await this.context.dependencies.onRefresh();
    }
  }

  private findPromptDependencies(promptId: string): ConvertedPrompt[] {
    return this.getConvertedPrompts().filter((prompt) => {
      if (!prompt.chainSteps || prompt.chainSteps.length === 0) return false;
      return prompt.chainSteps.some((step: any) => step.promptId === promptId);
    });
  }

  private getConvertedPrompts(): ConvertedPrompt[] {
    return this.context.getData().convertedPrompts;
  }

  private getPromptsData(): PromptData[] {
    return this.context.getData().promptsData;
  }
}
