// @lifecycle canonical - Formats responses prior to gate review.
import {
  isChainFormattingContext,
  isSinglePromptFormattingContext,
} from '../../formatting/formatting-context.js';
import { BasePipelineStage } from '../stage.js';

import type { Logger } from '#infra/logging/index.js';
import type { ExecutionRecordStore } from '#modules/chains/execution-record-store.js';
import type { FormatterExecutionContext, StepLifecycle } from '#shared/types/chain-execution.js';
import type { ChainSessionService } from '#shared/types/chain-session.js';
import type { ResponseFormatterPort } from '#shared/types/index.js';
import type { ExecutionContext } from '../../context/index.js';
import type { SinglePromptFormattingContext } from '../../formatting/formatting-context.js';
import type { ResponseAssembler } from '../../formatting/response-assembler.js';

/**
 * Pipeline Stage 21: Response Formatting
 *
 * Assembles final ToolResponse payloads with metadata, session information,
 * and progress tracking for different execution types (prompt/chain/template).
 *
 * Domain logic delegated to:
 * - ResponseAssembler: section assembly, footer building, gate validation info
 * - formatting-context.ts: type guards for discriminated union
 *
 * Dependencies: context.executionPlan, rendered content from StepExecutionStage
 * Output: context.response (final ToolResponse)
 */
export class ResponseFormattingStage extends BasePipelineStage {
  readonly name = 'ResponseFormatting';

  constructor(
    private readonly responseFormatter: ResponseFormatterPort,
    private readonly responseAssembler: ResponseAssembler,
    logger: Logger,
    private readonly executionRecordStore: ExecutionRecordStore | null = null,
    /**
     * Read-only source of the run-level telemetry stamped onto terminal records.
     * Optional, matching the store above: where it is absent the record is still
     * written, just without the telemetry fields.
     */
    private readonly chainSessionStore: ChainSessionService | null = null
  ) {
    super(logger);
  }

  private emitChainTerminalRecord(context: ExecutionContext): void {
    if (this.executionRecordStore === null) return;
    const session = context.sessionContext;
    if (session === undefined) return;

    const status = resolveTerminalStatus(context);
    if (status === undefined) return;

    const completedAt = Date.now();
    const telemetry = this.chainSessionStore?.getRunTelemetry(
      session.sessionId,
      context.getScopeOptions()
    );
    this.executionRecordStore.append({
      sessionId: session.sessionId,
      chainId: session.chainId,
      // `nodeId` deliberately omitted: this record describes the RUN reaching a terminal
      // status, not a node. `buildAppendParams` binds the column NULL for it. The prompt is the
      // run's own — the parsed command's, the one the run id names (R66).
      ...(context.parsedCommand?.promptId !== undefined
        ? { promptId: context.parsedCommand.promptId }
        : {}),
      status,
      startedAt: completedAt,
      completedAt,
      scope: context.getScopeOptions(),
      ...(telemetry ?? {}),
    });
  }

  async execute(context: ExecutionContext): Promise<void> {
    this.logEntry(context);

    if (context.response) {
      this.logExit({ skipped: 'Response already set' });
      return;
    }

    if (context.state.gates.responseBlocked === true && context.hasPendingReview()) {
      const blockedResponse = this.responseAssembler.formatBlockedResponse(context);
      context.setResponse({
        content: [{ type: 'text', text: blockedResponse }],
        isError: false,
      });
      context.diagnostics.info(this.name, 'Response blocked - gate failure', {
        blockedGateIds: context.state.gates.blockedGateIds,
      });
      this.logExit({ blocked: true, reason: 'gate_failure' });
      return;
    }

    if (!context.executionResults) {
      this.handleError(new Error('Execution results missing before formatting'));
    }

    try {
      const formatterContext = this.buildFormatterContext(context);

      let responseContent: string;
      if (isChainFormattingContext(formatterContext) && context.sessionContext) {
        responseContent = this.responseAssembler.formatChainResponse(context, formatterContext);
      } else if (isSinglePromptFormattingContext(formatterContext)) {
        responseContent = this.responseAssembler.formatSinglePromptResponse(
          context,
          formatterContext
        );
      } else {
        responseContent = this.responseAssembler.formatSinglePromptResponse(
          context,
          formatterContext as SinglePromptFormattingContext
        );
      }

      const gateValidationInfo = this.responseAssembler.buildGateValidationInfo(context);

      const response = this.responseFormatter.formatPromptEngineResponse(
        responseContent,
        formatterContext,
        { includeStructuredContent: false },
        gateValidationInfo
      );

      // Row 2.4. `includeStructuredContent: false` above is the DEFAULT-lean posture (the
      // formatter omits execution/chain bookkeeping unless a caller asks). The interrupt is not
      // bookkeeping: it is the payload the caller was told to read, and the plan's §Adapter
      // boundary makes `structuredContent.chain_interrupt` its only machine-readable form. Merged
      // rather than assigned, so a future opt-in to the bookkeeping block keeps both.
      const chainInterrupt = this.responseAssembler.buildInterruptStructuredContent(context);
      if (chainInterrupt !== undefined) {
        response.structuredContent = {
          ...(response.structuredContent ?? {}),
          chain_interrupt: chainInterrupt,
        };
      }

      context.setResponse(response);

      this.emitChainTerminalRecord(context);

      context.diagnostics.info(this.name, 'Response formatted', {
        executionType: formatterContext.executionType,
        hasGateInstructions: Boolean(context.gateInstructions),
        hasSession: Boolean(context.sessionContext),
        chainId: context.sessionContext?.chainId,
        contentLength: responseContent.length,
      });

      this.logExit({
        formatted: true,
        executionType: formatterContext.executionType,
      });
    } catch (error) {
      this.handleError(error, 'Response formatting failed');
    }
  }

  /**
   * How many of the run's nodes have actually been advanced past.
   *
   * Undefined when the store is unavailable or the session cannot be read (single prompts,
   * test harnesses wiring only a formatter) — the caller then keeps the position-derived
   * value rather than reporting a confident zero.
   */
  private countExecutedSteps(context: ExecutionContext): number | undefined {
    const sessionId = context.sessionContext?.sessionId;
    if (this.chainSessionStore === null || sessionId === undefined) {
      return undefined;
    }
    const session = this.chainSessionStore.getSession(sessionId, context.getScopeOptions());
    return session?.executionOrder.length;
  }

  /**
   * Build the FormatterExecutionContext from pipeline state.
   * This is orchestration-level context wiring, not domain logic.
   */
  private buildFormatterContext(context: ExecutionContext): FormatterExecutionContext {
    const executionType = context.executionPlan?.strategy ?? 'single';
    const sessionContext = context.sessionContext;

    const formatterContext: FormatterExecutionContext = {
      executionId: `pipeline_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      executionType,
      startTime: Date.now(),
      endTime: Date.now(),
      frameworkEnabled: Boolean(context.frameworkContext),
      success: true,
    };

    const frameworkUsed = context.frameworkContext?.selectedFramework?.name;
    if (frameworkUsed) {
      formatterContext.frameworkUsed = frameworkUsed;
    }

    // Was `sessionContext.currentStep` — the position the run is standing at, reported as a
    // count of work done. Those differ by one on a run that has not started its current step,
    // and they stop tracking each other entirely once a step can be skipped or revisited.
    // `executionOrder` records the nodes actually advanced past, so its length IS the count.
    const executedCount = this.countExecutedSteps(context);
    if (executedCount !== undefined) {
      formatterContext.stepsExecuted = executedCount;
    } else if (sessionContext?.currentStep !== undefined) {
      formatterContext.stepsExecuted = sessionContext.currentStep;
    }

    if (sessionContext?.sessionId !== undefined) {
      formatterContext.sessionId = sessionContext.sessionId;
    }

    const chainId = sessionContext?.chainId ?? context.parsedCommand?.chainId;
    if (chainId !== undefined) {
      formatterContext.chainId = chainId;
    }

    if (sessionContext?.currentStep !== undefined && sessionContext.totalSteps !== undefined) {
      formatterContext.chainProgress = {
        currentStep: sessionContext.currentStep,
        totalSteps: sessionContext.totalSteps,
        status:
          sessionContext.totalSteps > 0 && sessionContext.currentStep >= sessionContext.totalSteps
            ? 'complete'
            : 'in_progress',
      };
    }

    return formatterContext;
  }
}

/**
 * Which terminal record, if any, this run has earned.
 *
 * Abort was previously unobservable in the ledger: `state.session.aborted` is written by
 * GateVerdictProcessor and the shell-verification stage, and was read by nothing — so a
 * user-aborted chain left its last record at `working` permanently. Aborted is checked
 * first because a run can be flagged complete and aborted in the same pass, and the abort
 * is the more specific outcome.
 *
 * Returns undefined for a run still in progress, which is not a terminal state and must
 * not produce a record.
 */
function resolveTerminalStatus(context: ExecutionContext): StepLifecycle | undefined {
  if (context.state.session.aborted === true) return 'cancelled';
  if (context.state.session.chainComplete) return 'completed';
  return undefined;
}
