// @lifecycle canonical - Filesystem helpers for YAML-based prompt category operations.
/**
 * Filesystem-level category maintenance helpers shared across prompt tooling.
 *
 * Categories are implicit — determined by directory existence under the prompts root.
 * No JSON registry files are used.
 */

import { existsSync, readdirSync, type Dirent } from 'node:fs';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';

import {
  isExcludedCategoryDirectoryName,
  isIgnoredPromptEntryName,
  isReservedPromptDirectoryName,
  isSingleFilePromptName,
  singleFilePromptBaseName,
} from '#shared/utils/prompt-layout.js';

export interface CategoryResult {
  effectiveCategory: string;
  created: boolean;
}

/**
 * The category directories under a prompts root, by the same rule the loader walks them.
 *
 * Extracted from `PromptLoader.loadFromDirectories` Phase 1 at P4.7 and CALLED from there, so
 * there is one definition of "what counts as a category directory" rather than two. The tool
 * layer's `list` and `inspect` need the same answer the loader gives. The name rule itself is
 * `isExcludedCategoryDirectoryName`, which every other walk of the prompts root calls too.
 *
 * Sorted, so a listing is stable across filesystems — `readdirSync` order is not specified.
 */
export function discoverCategoryDirectories(promptsDir: string): string[] {
  if (!existsSync(promptsDir)) {
    return [];
  }

  try {
    return readdirSync(promptsDir, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && !isExcludedCategoryDirectoryName(entry.name))
      .map((entry) => entry.name)
      .sort();
  } catch {
    // An unreadable root contributes no categories, exactly as an absent one does.
    return [];
  }
}

// ============================================
// YAML Prompt Helpers
// ============================================

export interface YamlPromptInfo {
  id: string;
  path: string;
  format: 'directory' | 'file';
}

/**
 * The prompt one entry of a category directory declares, or `undefined` for an entry the loader
 * does not serve. The skip rules are `#shared/utils/prompt-layout.js`'s.
 */
function promptFromCategoryEntry(categoryDir: string, entry: Dirent): YamlPromptInfo | undefined {
  if (isIgnoredPromptEntryName(entry.name)) return undefined;

  if (entry.isDirectory()) {
    if (isReservedPromptDirectoryName(entry.name)) return undefined;
    // Directory pattern: {prompt_id}/prompt.yaml
    const promptDir = path.join(categoryDir, entry.name);
    return existsSync(path.join(promptDir, 'prompt.yaml'))
      ? { id: entry.name, path: promptDir, format: 'directory' }
      : undefined;
  }

  if (entry.isFile() && isSingleFilePromptName(entry.name)) {
    // File pattern: {prompt_id}.yaml (reserved filenames are not prompts)
    return {
      id: singleFilePromptBaseName(entry.name),
      path: path.join(categoryDir, entry.name),
      format: 'file',
    };
  }

  return undefined;
}

/**
 * Discover YAML prompts in a category directory.
 * Supports both directory format ({id}/prompt.yaml) and file format ({id}.yaml).
 *
 * One level deep, so it never reached a prompt's `tools/`. That made its own copy of the skip
 * rules harmless only by depth, and the copy still disagreed with the loader: it listed
 * `_draft.yaml`, `tool.yaml` and a `tools/` or `_drafts/` directory holding a `prompt.yaml`, none
 * of which the loader serves. The rules now come from `#shared/utils/prompt-layout.js`, as the
 * loader's do.
 *
 * @param categoryDir - Path to the category directory
 * @returns Array of discovered YAML prompts with their paths and formats
 */
export function discoverYamlPromptsInCategory(categoryDir: string): YamlPromptInfo[] {
  if (!existsSync(categoryDir)) {
    return [];
  }

  const discoveries: YamlPromptInfo[] = [];
  const seenIds = new Set<string>();

  try {
    const entries = readdirSync(categoryDir, { withFileTypes: true });

    for (const entry of entries) {
      const found = promptFromCategoryEntry(categoryDir, entry);
      if (found === undefined) continue;
      // Directory takes precedence over a file with the same id
      if (found.format === 'file' && seenIds.has(found.id)) continue;
      if (found.format === 'directory') seenIds.add(found.id);
      discoveries.push(found);
    }
  } catch (error) {
    // Ignore errors for inaccessible directories
  }

  return discoveries;
}

/**
 * Find a specific YAML prompt by ID in a category directory.
 *
 * @param categoryDir - Path to the category directory
 * @param promptId - The prompt ID to find
 * @returns The prompt info if found, null otherwise
 */
export function findYamlPromptInCategory(
  categoryDir: string,
  promptId: string
): YamlPromptInfo | null {
  // Nested prompts ({category}/{parent}/{child}/prompt.yaml) are invisible to the
  // one-level directory scan, so qualified ids resolve by direct path instead.
  if (promptId.includes('/')) {
    const segments = promptId.split('/');
    if (segments.some((s) => s === '' || s === '.' || s === '..')) {
      return null;
    }
    const nestedDir = path.join(categoryDir, ...segments);
    if (existsSync(path.join(nestedDir, 'prompt.yaml'))) {
      return { id: promptId, path: nestedDir, format: 'directory' };
    }
    const nestedFile = `${nestedDir}.yaml`;
    if (existsSync(nestedFile)) {
      return { id: promptId, path: nestedFile, format: 'file' };
    }
    return null;
  }

  const prompts = discoverYamlPromptsInCategory(categoryDir);
  return prompts.find((p) => p.id === promptId) ?? null;
}

/**
 * Check if a category directory contains any YAML-format prompts.
 *
 * @param categoryDir - Path to the category directory
 * @returns true if any YAML prompts are found
 */
export function hasYamlPromptsInCategory(categoryDir: string): boolean {
  return discoverYamlPromptsInCategory(categoryDir).length > 0;
}

/**
 * Delete a YAML prompt from a category directory.
 * Handles both directory format (deletes entire directory) and file format (deletes single file).
 *
 * @param promptInfo - The prompt info from discoverYamlPromptsInCategory
 * @returns Array of deleted paths
 */
export async function deleteYamlPrompt(promptInfo: YamlPromptInfo): Promise<string[]> {
  const deletedPaths: string[] = [];

  try {
    if (promptInfo.format === 'directory') {
      // Delete entire directory recursively
      await fs.rm(promptInfo.path, { recursive: true, force: true });
      deletedPaths.push(promptInfo.path);
    } else {
      // Delete single file
      await fs.unlink(promptInfo.path);
      deletedPaths.push(promptInfo.path);
    }
  } catch (error: any) {
    if (error.code !== 'ENOENT') {
      throw error;
    }
  }

  return deletedPaths;
}
