// @lifecycle canonical - Tracks resource changes with source attribution and audit logging
/**
 * Resource Change Tracker Module
 * Provides content hashing, change logging, and startup baseline comparison
 * for prompts and gates resources.
 *
 * Architecture:
 * ┌─────────────────┐    ┌─────────────────┐
 * │  HotReloadMgr   │    │ resource_manager│
 * │  (filesystem)   │    │   (mcp-tool)    │
 * └────────┬────────┘    └────────┬────────┘
 *          │                      │
 *          └──────────┬───────────┘
 *                     ↓
 *          ┌─────────────────────┐
 *          │ ResourceChangeTracker│
 *          │  - logChange()      │
 *          │  - getChanges()     │
 *          │  - compareBaseline()│
 *          └─────────┬───────────┘
 *                    ↓
 *     ┌──────────────┴──────────────┐
 *     │                             │
 *     ↓                             ↓
 * resource_changes (SQLite)  kv_state[key='resource_hashes']
 * (structured log)           (hash cache blob)
 */

import * as crypto from 'node:crypto';
import * as fs from 'node:fs/promises';

import { SqliteEngine } from '../../database/sqlite-engine.js';
import { SqliteStateStore } from '../../database/stores/sqlite-store.js';
import { Logger } from '../../logging/index.js';

import type { StateStoreOptions } from '#infra/database/stores/interface.js';
import type {
  ChangeSource,
  ChangeOperation,
  GetChangesParams,
  LogChangeParams,
  ResourceChangeEntry,
  ResourceChangeLogPort,
  TrackedResourceType,
} from '#shared/types/index.js';

import { enforceRetention } from '#infra/database/retention.js';
import { resolveContinuityScopeId } from '#shared/utils/request-identity-scope.js';

/**
 * The log's data contract lives in `shared/types` — `ResourceChangeLogPort` and the four shapes
 * below — because mcp/ reads this log and may not import infra/. Re-exported here so the module
 * that implements the contract is still a place to import it from.
 */
export type {
  ChangeSource,
  ChangeOperation,
  GetChangesParams,
  LogChangeParams,
  ResourceChangeEntry,
  TrackedResourceType,
} from '#shared/types/index.js';

/**
 * Configuration for the tracker
 */
export interface ResourceChangeTrackerConfig {
  /**
   * @deprecated Reads nothing. The cap for `resource_changes` is declared in
   * `table-contracts.ts` and enforced by `enforceRetention()`, which is now the single owner.
   *
   * Left in place rather than deleted because removing it also touches the user-facing
   * `resources.logs.maxEntries` config key, its validator, and its docs — a config-surface
   * change, not a retention one. Worth knowing: that key was ALREADY inert before this tier,
   * because `initializeResourceChangeTracker` hardcodes 1000 and never reads config. It is
   * settable, range-validated (50-5000), and consumed by nothing.
   */
  maxEntries: number;
  /** Writable SQLite path decided by the runtime composition root (`PathResolver`). */
  dbPath: string;
  /** Whether to track prompts */
  trackPrompts: boolean;
  /** Whether to track gates */
  trackGates: boolean;
  /**
   * Scope stamped on rows this tracker writes.
   *
   * Changes reach this tracker from a filesystem watcher, which fires with no request and
   * therefore no request scope — there is nothing to thread through. The composition root
   * supplies the process's own workspace instead, matching how `FrameworkStateStore` takes a
   * `defaultScope`. Without it every row was written with a literal `'default'` tenant and
   * NULL scope columns, which the startup migration then backfilled on the next boot — the
   * treadmill, running against a writer that never stopped producing NULLs.
   */
  defaultScope?: StateStoreOptions;
}

/** What a caller must supply: the database path, which has no default, and optionally the rest. */
type ResourceChangeTrackerOptions = Partial<ResourceChangeTrackerConfig> &
  Pick<ResourceChangeTrackerConfig, 'dbPath'>;

const DEFAULT_CONFIG: Omit<ResourceChangeTrackerConfig, 'dbPath'> = {
  maxEntries: 1000,
  trackPrompts: true,
  trackGates: true,
};

/**
 * ResourceChangeTracker class
 * Provides audit logging and hash tracking for resource changes via SQLite
 */
export class ResourceChangeTracker implements ResourceChangeLogPort {
  private logger: Logger;
  private config: ResourceChangeTrackerConfig;
  private hashCache: Map<string, string> = new Map();
  private dbManager?: SqliteEngine;
  private hashStore?: SqliteStateStore<Record<string, string>>;
  private initialized: boolean = false;

  constructor(logger: Logger, config: ResourceChangeTrackerOptions) {
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Initialize the tracker by loading existing state from SQLite
   */
  async initialize(): Promise<void> {
    if (this.initialized) {
      return;
    }

    this.logger.debug('ResourceChangeTracker: Initializing...');

    // Initialize SqliteEngine and hash store (idempotent — no-op if already initialized)
    this.dbManager = await SqliteEngine.getInstance(this.logger, { dbPath: this.config.dbPath });
    await this.dbManager.initialize();

    this.hashStore = new SqliteStateStore<Record<string, string>>(
      this.dbManager,
      {
        tableName: 'kv_state',
        key: 'resource_hashes',
        stateColumn: 'state',
        defaultState: () => ({}),
      },
      this.logger
    );

    // Load hash cache from SQLite
    await this.loadHashCache();

    this.initialized = true;
    this.logger.info('✅ ResourceChangeTracker initialized');
  }

  /**
   * Load hash cache from SQLite
   */
  private async loadHashCache(): Promise<void> {
    try {
      const cached = await this.hashStore!.load();
      this.hashCache = new Map(Object.entries(cached));
      this.logger.debug(`ResourceChangeTracker: Loaded ${this.hashCache.size} cached hashes`);
    } catch (error) {
      this.logger.warn('ResourceChangeTracker: Failed to load hash cache', error);
      this.hashCache = new Map();
    }
  }

  /**
   * Save hash cache to SQLite
   */
  private async saveHashCache(): Promise<void> {
    const data = Object.fromEntries(this.hashCache);
    await this.hashStore!.save(data);
  }

  /**
   * Compute SHA-256 hash of content
   */
  private computeHash(content: string): string {
    return `sha256:${crypto.createHash('sha256').update(content, 'utf-8').digest('hex')}`;
  }

  /**
   * Get cache key for a resource
   */
  private getCacheKey(resourceType: TrackedResourceType, resourceId: string): string {
    return `${resourceType}/${resourceId}`;
  }

  /**
   * Log a resource change
   */
  async logChange(params: LogChangeParams): Promise<void> {
    if (!this.initialized) {
      await this.initialize();
    }

    // Check if we should track this resource type
    if (params.resourceType === 'prompt' && !this.config.trackPrompts) {
      return;
    }
    if (params.resourceType === 'gate' && !this.config.trackGates) {
      return;
    }

    const cacheKey = this.getCacheKey(params.resourceType, params.resourceId);
    const previousHash = this.hashCache.get(cacheKey);

    // Compute hash from content or file
    let contentHash: string;
    if (params.content !== undefined && params.content !== '') {
      contentHash = this.computeHash(params.content);
    } else if (params.operation !== 'removed') {
      try {
        const fileContent = await fs.readFile(params.filePath, 'utf-8');
        contentHash = this.computeHash(fileContent);
      } catch {
        this.logger.warn(`ResourceChangeTracker: Cannot read file for hashing: ${params.filePath}`);
        contentHash = 'sha256:unknown';
      }
    } else {
      contentHash = 'sha256:removed';
    }

    // Skip if hash unchanged (no actual change)
    if (params.operation === 'modified' && previousHash === contentHash) {
      this.logger.debug(`ResourceChangeTracker: Skipping unchanged resource ${params.resourceId}`);
      return;
    }

    // Update in-memory cache
    if (params.operation === 'removed') {
      this.hashCache.delete(cacheKey);
    } else {
      this.hashCache.set(cacheKey, contentHash);
    }

    // INSERT change into resource_changes table
    const timestamp = new Date().toISOString();
    const scope = this.config.defaultScope;
    this.dbManager!.run(
      `INSERT INTO resource_changes (tenant_id, organization_id, workspace_id, timestamp, source, operation, resource_type, resource_id, file_path, content_hash, previous_hash)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        resolveContinuityScopeId(scope),
        scope?.organizationId ?? null,
        scope?.workspaceId ?? null,
        timestamp,
        params.source,
        params.operation,
        params.resourceType,
        params.resourceId,
        params.filePath,
        contentHash,
        previousHash !== undefined && previousHash !== contentHash ? previousHash : null,
      ]
    );

    // Persist hash cache
    await this.saveHashCache();

    // Rotate log if needed
    this.rotateLogIfNeeded();

    this.logger.info(
      `📝 ResourceChangeTracker: ${params.operation} ${params.resourceType}/${params.resourceId} (source: ${params.source})`
    );
  }

  /**
   * Trim the change log to the cap declared for `resource_changes` in table-contracts.ts.
   *
   * Delegates rather than inlining its own DELETE, which is what this used to do with a
   * `maxEntries` config value that could disagree with the declared contract. One definition now
   * serves two call sites: the engine's startup pass and this per-write trim.
   *
   * The per-write call is kept deliberately. A startup-only pass would let the table grow without
   * bound for the length of a session, and this table is the one measured at its cap and actively
   * evicting — so the write site is where the bound actually holds.
   */
  private rotateLogIfNeeded(): void {
    enforceRetention(this.dbManager!, this.logger, 'resource_changes');
  }

  /**
   * Get changes from the log with optional filtering
   */
  async getChanges(params: GetChangesParams = {}): Promise<ResourceChangeEntry[]> {
    if (!this.initialized) {
      await this.initialize();
    }

    const { limit = 50, source, resourceType, since, resourceId } = params;

    // Build query dynamically based on filters
    const conditions: string[] = [];
    const values: (string | number)[] = [];

    if (source !== undefined) {
      conditions.push('source = ?');
      values.push(source);
    }
    if (resourceType !== undefined) {
      conditions.push('resource_type = ?');
      values.push(resourceType);
    }
    if (resourceId !== undefined && resourceId !== '') {
      conditions.push('resource_id = ?');
      values.push(resourceId);
    }
    if (since !== undefined && since !== '') {
      conditions.push('timestamp >= ?');
      values.push(since);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    values.push(limit);

    const rows = this.dbManager!.query<{
      timestamp: string;
      source: string;
      operation: string;
      resource_type: string;
      resource_id: string;
      file_path: string;
      content_hash: string;
      previous_hash: string | null;
    }>(
      `SELECT timestamp, source, operation, resource_type, resource_id, file_path, content_hash, previous_hash
       FROM resource_changes ${whereClause}
       ORDER BY id DESC LIMIT ?`,
      values
    );

    return rows.map((row) => ({
      timestamp: row.timestamp,
      source: row.source as ChangeSource,
      operation: row.operation as ChangeOperation,
      resourceType: row.resource_type as TrackedResourceType,
      resourceId: row.resource_id,
      filePath: row.file_path,
      contentHash: row.content_hash,
      ...(row.previous_hash ? { previousHash: row.previous_hash } : {}),
    }));
  }

  /**
   * Compare current resources against cached baseline and log external changes
   * Called at startup to detect changes made while server was down
   */
  async compareBaseline(
    resources: Array<{
      resourceType: TrackedResourceType;
      resourceId: string;
      filePath: string;
      /**
       * The owning loader refused this file, so it is on disk and NOT in the catalog.
       *
       * A plain boolean rather than a quarantine handle: all this loop needs to know is whether
       * the file entered the catalog, and the caller already holds the collection that answers
       * that. Threading the collection down here would give the tracker a second way to ask a
       * question the loader has already answered.
       */
      refused?: boolean;
    }>
  ): Promise<{ added: number; modified: number; removed: number; refused: number }> {
    if (!this.initialized) {
      await this.initialize();
    }

    const result = { added: 0, modified: 0, removed: 0, refused: 0 };
    const currentKeys = new Set<string>();

    for (const resource of resources) {
      const cacheKey = this.getCacheKey(resource.resourceType, resource.resourceId);
      currentKeys.add(cacheKey);

      // A refusal is a THIRD disposition, not a variant of either other one.
      //
      // Not `added`: `resource_changes` is supposed to mean a resource entered the catalog, and
      // this one did not — logging it told an operator a prompt was available that `prompt_engine`
      // rejects. Not `removed` either: the key stays in `currentKeys` above, so the sweep below
      // does not fire, because the file is still sitting on disk where they left it.
      //
      // The hash is deliberately NOT written. That is what makes the repair fire the event at the
      // moment the resource actually enters the catalog: a file broken on its first sighting stays
      // uncached and logs `added` once repaired, and a file that was valid, broke, and was repaired
      // keeps its old hash and logs `modified`.
      if (resource.refused === true) {
        result.refused++;
        continue;
      }

      try {
        const content = await fs.readFile(resource.filePath, 'utf-8');
        const currentHash = this.computeHash(content);
        const cachedHash = this.hashCache.get(cacheKey);

        if (cachedHash === undefined) {
          // New resource added externally
          await this.logChange({
            source: 'external',
            operation: 'added',
            resourceType: resource.resourceType,
            resourceId: resource.resourceId,
            filePath: resource.filePath,
            content,
          });
          result.added++;
        } else if (cachedHash !== currentHash) {
          // Resource modified externally
          await this.logChange({
            source: 'external',
            operation: 'modified',
            resourceType: resource.resourceType,
            resourceId: resource.resourceId,
            filePath: resource.filePath,
            content,
          });
          result.modified++;
        }
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
          this.logger.warn(
            `ResourceChangeTracker: Error reading resource ${resource.resourceId}`,
            error
          );
        }
      }
    }

    result.removed = await this.logRemovals(currentKeys);

    if (result.added > 0 || result.modified > 0 || result.removed > 0 || result.refused > 0) {
      this.logger.info(
        `📊 ResourceChangeTracker: Baseline comparison - ` +
          `${result.added} added, ${result.modified} modified, ${result.removed} removed, ` +
          `${result.refused} refused by their loader and not logged as a change (external)`
      );
    }

    return result;
  }

  /**
   * Log a removal for every cached resource absent from `present`, comparing no content.
   *
   * The reconciliation half of {@link compareBaseline}, for a folder that appeared while the
   * server ran: its present files arrive as watcher events, but an entry written and removed
   * before the folder was watched arrives as nothing, while its `added` row stands.
   *
   * @returns the number of removals logged
   */
  async sweepRemovals(
    present: ReadonlyArray<{ resourceType: TrackedResourceType; resourceId: string }>
  ): Promise<number> {
    if (!this.initialized) {
      await this.initialize();
    }
    return this.logRemovals(
      new Set(
        present.map((resource) => this.getCacheKey(resource.resourceType, resource.resourceId))
      )
    );
  }

  /**
   * Log a removal for every cached resource the current walk did not see, and return the count.
   *
   * Extracted from `compareBaseline` so that method stays under the cognitive-complexity limit
   * once refusals became a third disposition there. It is also the half that reads the cache as a
   * KEY SET rather than a hash store, which is a different question from the comparison above.
   */
  private async logRemovals(currentKeys: ReadonlySet<string>): Promise<number> {
    let removed = 0;
    for (const cacheKey of this.hashCache.keys()) {
      if (currentKeys.has(cacheKey)) continue;
      // Split on the FIRST separator only. The cache key is `${resourceType}/${resourceId}` and
      // a resourceId may itself contain '/' (a categorised prompt, a tool under its parent), so
      // a plain split() truncates the id at its first segment and reports a removal for a
      // resource that was never tracked under that name.
      const separatorIndex = cacheKey.indexOf('/');
      await this.logChange({
        source: 'external',
        operation: 'removed',
        resourceType: cacheKey.slice(0, separatorIndex) as TrackedResourceType,
        resourceId: cacheKey.slice(separatorIndex + 1),
        filePath: `(removed: ${cacheKey})`,
      });
      removed++;
    }
    return removed;
  }
}

/**
 * Factory function to create a ResourceChangeTracker instance
 */
export function createResourceChangeTracker(
  logger: Logger,
  config: ResourceChangeTrackerOptions
): ResourceChangeTracker {
  return new ResourceChangeTracker(logger, config);
}
