/**
 * Max check-tier gates given a `per_gate` slot in the verdict template.
 *
 * Bounds the collected CHECK entries only — reminder-tier gates never count against this cap,
 * since they render once in the `reminders` field rather than one `per_gate` entry each. The full
 * `gateIds` list is still walked in original order so a run of leading reminders cannot push a
 * later check off the template before it is even considered.
 */
const MAX_GATE_VERDICT_ENTRIES = 10;

/**
 * The verbs that answer a SOFT (unpaused) interrupt, verbatim from the plan's §Interrupt payload
 * block.
 *
 * `gate_action` spellings match the contract enum (`tooling/contracts/prompt-engine.json`)
 * exactly, because a client reads this list and puts the string back on the wire.
 */
const SOFT_INTERRUPT_VERBS = [
  'answer the step',
  'remainder',
  'gate_action:abort',
  'cancel',
] as const;

/**
 * The verbs a HARD-paused run offers — the RESOLUTION verbs only, and this list is not a
 * superset of the soft one (row 2.6).
 *
 * `answer the step` is deliberately absent: stage 18 issues no step while a review is pending, so
 * a paused run has no step to answer, and the paused footer never offered one either. Shipping it
 * here advertised an exit the run does not accept — the machine half of the payload and the run's
 * own behaviour disagreed. `remainder` is absent for the same reason in a different direction: on
 * a paused run a bare `remainder` does not clear the synthetic review, so the caller must spell it
 * `gate_action:accept_alternative` and carry the remainder with it. That pairing is stated inline
 * rather than left to the reader; `GateVerdictProcessor` refuses `accept_alternative` by name when
 * the remainder is missing, so this string and that refusal are the two halves of one contract.
 */
const PAUSED_INTERRUPT_VERBS = [
  'gate_action:resume',
  'gate_action:accept_alternative (with remainder)',
  'gate_action:abort',
  'cancel',
] as const;

/**
 * One verb list per state, built once, rendered twice — the text section and `structuredContent`
 * must not be able to advertise different exits from the same hold.
 *
 * STATE-DEPENDENT, not additive: see {@link PAUSED_INTERRUPT_VERBS}. A run latched complete has
 * nothing left to resume, so it offers none (R97).
 */
function resolveInterruptVerbs(paused: boolean, complete: boolean): string[] {
  if (complete) return [];
  return paused ? [...PAUSED_INTERRUPT_VERBS] : [...SOFT_INTERRUPT_VERBS];
}

/** One call inserts at most one investigation step (R114); an interrupt names the rest. */
const UNINVESTIGATED_LABEL =
  'Open with no investigation step (one call inserts one, for the first blocking unknown it declares)';

/** A `label: a, b` line under the interrupt header, or nothing when the list is empty. */
const listLine = (label: string, items: readonly string[]): string =>
  items.length > 0 ? `\n\n${label}: ${items.join(', ')}` : '';

/**
 * Assembles response content sections for different execution types.
 *
 * Handles chain responses (with footers, gate instructions, advisory warnings),
 * single prompt responses, blocked responses, script confirmations, validation
 * errors, gate validation info, and legacy footer building.
 *
 * Extracted from ResponseFormattingStage.
 */
export class ResponseAssembler {
  /**
   * @param runStepViewProvider The live run's node order and retired-node list (P6 Tier 2).
   *   Optional, and absent means "answer from the parse array alone" — the pre-P6 behavior,
   *   byte-identical. The same narrow-view + provider seam the gate layer uses
   *   (`GateEnhancementService`, `TemporaryGateRegistrar`): the assembler needs two facts about
   *   the run, not a session store, so the dependency stays a function type.
   * @param declaredSectionsProvider Phase-guard section headers a framework declares, from
   *   `declared-sections.ts` — the same source `19-phase-guard-verification-stage` grades the
   *   response against (Tier 2.5, OQ-1). A function type, matching the seam above: this
   *   assembler needs one derived fact, not framework-manager access. Absent means "declare
   *   nothing", the pre-Tier-2 behavior for single-prompt execution.
   */
  constructor(
    private readonly runStepViewProvider?: RunStepViewProvider,
    private readonly declaredSectionsProvider?: (frameworkId: string) => DeclaredSection[]
  ) {}

  /**
   * Formats response for chain execution with session tracking.
   */
  formatChainResponse(
    context: ExecutionContext,
    _formatterContext: ChainFormattingContext
  ): string {
    const sections: string[] = [];
    const gateActive = !this.isGateContentSuppressed(context);

    sections.push(this.extractBaseContent(context));

    const confirmationRequired = context.state.scripts?.confirmationRequired;
    if (confirmationRequired) {
      sections.push(this.formatConfirmationRequest(confirmationRequired));
    }

    const validationErrors = context.state.scripts?.validationErrors;
    if (validationErrors && validationErrors.length > 0) {
      sections.push(this.formatValidationErrors(validationErrors));
    }

    if (gateActive && this.isGateGuidanceInjectionEnabled(context) && context.gateInstructions) {
      sections.push(context.gateInstructions);
    }

    sections.push(...this.buildAdvisoryWarnings(context));

    // Gate review CTA (only when gate content active) or final completion
    const gateReviewCTA = gateActive ? this.buildGateReviewCTA(context) : null;
    if (gateReviewCTA != null) {
      sections.push(gateReviewCTA);
    } else {
      const finalMessage = this.buildFinalStepMessage(context);
      if (finalMessage != null) sections.push(finalMessage);
    }

    // Row 2.4. After the gate CTA and before the footer: the interrupt is what the caller must
    // act on, and the footer is bookkeeping. On a PAUSED run this is the only call to action in
    // the payload — `buildGateReviewCTA` returns null for the synthetic review precisely so the
    // client is not shown a `gate_verdict` template for a hold that no verdict resolves.
    const interruptSection = this.buildInterruptSection(context);
    if (interruptSection != null) sections.push(interruptSection);

    // Operator layer: inject handoff CTA when next step is delegated.
    // Detects from StepExecutionStage metadata OR parsed steps (when pendingReview blocked StepExecutionStage).
    if (this.isNextStepDelegated(context)) {
      const handoffCTA = this.buildHandoffSection(context);
      if (handoffCTA != null) sections.push(handoffCTA);
    }

    const footer = this.buildChainFooter(context);
    if (footer) {
      sections.push(footer);
    }

    return sections.join('\n\n');
  }

  /**
   * Formats response for single prompt execution.
   */
  formatSinglePromptResponse(
    context: ExecutionContext,
    _formatterContext: SinglePromptFormattingContext
  ): string {
    const sections: string[] = [];
    const gateActive = !this.isGateContentSuppressed(context);

    sections.push(this.extractBaseContent(context));

    const confirmationRequired = context.state.scripts?.confirmationRequired;
    if (confirmationRequired) {
      sections.push(this.formatConfirmationRequest(confirmationRequired));
    }

    const validationErrors = context.state.scripts?.validationErrors;
    if (validationErrors && validationErrors.length > 0) {
      sections.push(this.formatValidationErrors(validationErrors));
    }

    // An exhausted review takes no verdict (R9), so the guidance that closes on attesting in one
    // is withheld, as the chain step's review render withholds it (P6.45, P6.46).
    const reviewExhausted = context.sessionContext?.pendingReview?.phase === 'exhausted';
    if (
      gateActive &&
      !reviewExhausted &&
      this.isGateGuidanceInjectionEnabled(context) &&
      context.gateInstructions
    ) {
      sections.push(context.gateInstructions);
    }

    sections.push(...this.buildAdvisoryWarnings(context));

    // Declared section headers (Tier 2.5, OQ-1) — same block the chain path renders via
    // buildResponseFormatSection. A gated single prompt (explicit `gates`, a `gate` operator, or
    // `chainSteps`) gets a session and reaches stage 19 phase-guard verification
    // (`execution-planner.ts:427-450`), so it must be told the same header vocabulary the guard
    // grades it against — otherwise it is blocked on a contract it was never shown.
    const declaredSectionsBlock = this.buildDeclaredSectionsBlock(context);
    if (declaredSectionsBlock) {
      sections.push(declaredSectionsBlock);
    }

    // Row 2.4, on THIS path too. Found by the live drive, not by the suite: `>>strategic_implement`
    // is a gated single prompt that gets a session, so it can declare observations, raise an
    // interrupt and reach here — and rendered nothing, while `structuredContent.chain_interrupt`
    // (attached in stage 21, outside the chain/single branch) was correctly present. A payload
    // whose machine half reports a blocking unknown and whose human half does not is worse than
    // either alone.
    const interruptSection = this.buildInterruptSection(context);
    if (interruptSection != null) sections.push(interruptSection);

    const nextAction = this.buildNextActionCTA(context, gateActive);
    if (nextAction) {
      sections.push(nextAction);
    }

    return sections.join('\n\n');
  }

  /**
   * Formats a blocked response when gate failure suppresses content.
   */
  formatBlockedResponse(context: ExecutionContext): string {
    const blockedGateIds = context.state.gates.blockedGateIds ?? [];
    const gateInstructions = this.resolveBlockedReviewInstructions(context);

    const sections: string[] = [
      '## ⛔ Response Blocked',
      '',
      'Response content has been suppressed due to gate failure.',
      '',
      `**Blocking gates**: ${blockedGateIds.length > 0 ? blockedGateIds.join(', ') : 'unknown'}`,
      '',
    ];

    // Why each one failed, from the reviewer's own per-gate entry. Without this the block names
    // the gates and says nothing about them, which on a five-gate review is the same as naming
    // none (P4.75). Absent per-gate detail, nothing is added and the block is unchanged.
    const failedVerdicts = this.resolveFailedGateVerdicts(context);
    if (failedVerdicts.size > 0) {
      for (const [gateId, rationale] of failedVerdicts) {
        sections.push(`- \`${gateId}\` — ${rationale}`);
      }
      sections.push('');
    }

    sections.push('---');
    sections.push('');
    if (gateInstructions !== '') {
      sections.push(gateInstructions);
    } else {
      // Never silently. A block with no criteria is a retry loop with nothing to act on, and the
      // omission used to be invisible: the `if` above simply skipped the section. Say which piece
      // is missing so the absence is a report rather than a shorter response.
      sections.push(
        '**Gate review instructions are unavailable for this call** — the gate criteria could not be rendered. Inspect the gate definitions named above.'
      );
    }

    // A retry of a judge-routed gate needs the judge prompt as much as the first attempt did.
    const judgeSection = this.buildJudgeReviewSection(context);
    if (judgeSection !== '') {
      sections.push('');
      sections.push(judgeSection);
    }

    sections.push('');
    sections.push('---');
    sections.push('');
    // An exhausted review refuses every verdict (R9): the reply names the moves it accepts.
    const exhausted = context.sessionContext?.pendingReview?.phase === 'exhausted';
    sections.push(
      exhausted
        ? `**To proceed**: ${EXHAUSTED_REVIEW_CHOICE}`
        : '**To proceed**: Address the gate criteria and resubmit with `gate_verdict`.'
    );

    // The retry budget, from the counter the ordinary review footer reads (P4.101). A blocked
    // reply is the one place a caller cannot see it any other way: the block returns before
    // `buildGateReviewCTA`, so a loop bounded at five attempts showed no remaining count at all
    // and a client had nothing to stop on but the exhaustion notification.
    const attempt = this.resolveAttemptCounter(context);
    if (attempt !== undefined) {
      const remaining = Math.max(attempt.max - attempt.current, 0);
      sections.push('');
      sections.push(
        `**Attempt ${attempt.current} of ${attempt.max}** — ${remaining} ${
          remaining === 1 ? 'attempt remains' : 'attempts remain'
        } after this one.`
      );
    }

    const chainId = context.sessionContext?.chainId;
    if (chainId !== undefined && chainId !== '') {
      sections.push('');
      sections.push(
        exhausted ? exhaustedReviewMoves(chainId) : this.buildBlockedResubmitBlock(context, chainId)
      );
    }

    return sections.join('\n');
  }

  /**
   * Where this call stands in the gate's retry budget, or `undefined` when no review is pending.
   *
   * ONE reader of `pendingReview.attemptCount`/`maxAttempts` for both the review footer and the
   * blocked reply, so the two cannot disagree about which attempt a caller is on. The `+1` and
   * the clamp are the footer's own arithmetic: `attemptCount` is how many attempts have been
   * CONSUMED, so the attempt now in the caller's hands is the next one, and it never reads past
   * the ceiling on the call that exhausts it.
   *
   * `maxAttempts <= 1` answers `undefined`: "attempt 1 of 1" is not a budget, and the footer
   * omits the counter in that state for the same reason.
   */
  private resolveAttemptCounter(
    context: ExecutionContext
  ): { current: number; max: number } | undefined {
    const pendingReview = context.sessionContext?.pendingReview;
    if (pendingReview === undefined || pendingReview.maxAttempts <= 1) {
      return undefined;
    }
    return {
      current: Math.min(pendingReview.attemptCount + 1, pendingReview.maxAttempts),
      max: pendingReview.maxAttempts,
    };
  }

  /**
   * The resubmit instruction a blocked reply ends on — structured form first, legacy string after.
   *
   * Until P4.101 this was one line offering the legacy string and nothing else, while the
   * ordinary review footer had been offering the schema-validated object form since the object
   * form existed. A caller blocked on a gate was therefore steered into the one submission shape
   * that can fail to parse, on the reply where getting it wrong costs an attempt.
   *
   * Falls back to the bare resume line when no review is pending — there is no gate list to key
   * a template to, and inventing an empty one would advertise a shape the caller cannot fill.
   */
  private buildBlockedResubmitBlock(context: ExecutionContext, chainId: string): string {
    const pendingReview = context.sessionContext?.pendingReview;
    if (pendingReview === undefined) {
      return `Resume: \`chain_id="${chainId}", gate_verdict="GATE_REVIEW: PASS|FAIL - <reason>"\``;
    }

    const structuredTemplate = buildStructuredVerdictTemplate(
      pendingReview.gateIds,
      pendingReview.prompts,
      this.resolveGateTiers(context),
      this.resolveCheckResults(context)
    );

    return (
      `Resume:\n\n\`\`\`\nchain_id="${chainId}"\ngate_verdict=${structuredTemplate}\n\`\`\`\n\n` +
      'Set `"overall": "FAIL"` and say what needs improvement if the gates are still not met. ' +
      'Rationales are single-line.\n\n' +
      'A legacy string form is still accepted: `gate_verdict="GATE_REVIEW: PASS - [assessment]"`.'
    );
  }

  /**
   * Builds GateValidationInfo for structured response contract.
   */
  buildGateValidationInfo(context: ExecutionContext):
    | {
        enabled: boolean;
        passed: boolean;
        totalGates: number;
        failedGates: Array<{ id: string; reason: string }>;
        executionTime: number;
        pendingGateIds: string[];
        requiresGateVerdict: boolean;
        responseBlocked: boolean;
        gateRetryInfo: { maxAttempts: number; currentAttempt: number; retryAllowed: boolean };
      }
    | undefined {
    const gateIds = context.gates.getAll();
    if (gateIds.length === 0) {
      return undefined;
    }

    if (this.isGateContentSuppressed(context)) {
      return undefined;
    }

    const hasPendingReview = context.hasPendingReview();
    const responseBlocked = context.state.gates.responseBlocked === true;
    const blockedGateIds = context.state.gates.blockedGateIds ?? [];
    const retryLimitExceeded = context.state.gates.retryLimitExceeded === true;

    // The reviewer's own words for a gate it marked FAIL, when this call carried a per-gate
    // block. The literal below survives only where no such entry exists — it says why the
    // response is blocked, which is a different statement from why the gate failed, and it was
    // the whole of `reason` until the per-gate detail had a reader (P4.75).
    const failedVerdicts = this.resolveFailedGateVerdicts(context);
    const failedGates: Array<{ id: string; reason: string }> = blockedGateIds.map((id) => ({
      id,
      reason: failedVerdicts.get(id) ?? 'Gate failed (blockResponseOnFail enabled)',
    }));

    const sessionRetryInfo = context.sessionContext?.pendingReview;
    const gateRetryInfo = {
      maxAttempts: sessionRetryInfo?.maxAttempts ?? 2,
      currentAttempt: sessionRetryInfo?.attemptCount ?? 0,
      retryAllowed: !retryLimitExceeded,
    };

    return {
      enabled: true,
      passed: failedGates.length === 0 && !hasPendingReview,
      totalGates: gateIds.length,
      failedGates,
      executionTime: 0,
      pendingGateIds: hasPendingReview ? [...blockedGateIds] : [],
      requiresGateVerdict: hasPendingReview,
      responseBlocked,
      gateRetryInfo,
    };
  }

  /**
   * The run-completion latch, as the pipeline recorded it.
   *
   * Single reader of `state.session.chainComplete` for footer purposes so the progress line and
   * the CTA line cannot disagree — they were two independent `currentStep >= totalSteps`
   * computations before.
   */
  private isRunLatchedComplete(context: ExecutionContext): boolean {
    return context.state.session.chainComplete === true;
  }

  /**
   * Builds chain footer with session and progress tracking.
   */
  buildChainFooter(context: ExecutionContext): string {
    const lines: string[] = [];
    const sessionContext = context.sessionContext!;
    const chainIdentifier = sessionContext.chainId ?? sessionContext.sessionId;
    lines.push(`Chain: ${chainIdentifier}`);

    const hasPendingReview = context.hasPendingReview();
    // An exhausted review accepts only a `gate_action` (R9 refuses every verdict), so it owes no
    // verdict and its `Next:` names the moves it accepts (P6.23).
    const reviewExhausted = sessionContext.pendingReview?.phase === 'exhausted';

    // Completion is the LATCHED run fact (StepExecutionStage sets it from the store's
    // runStatus), not `currentStep >= totalSteps`. Those two differ on exactly one state —
    // the run standing on its final step with work still owed — and reading the ordinal there
    // printed "✓ Chain complete (N/N) · No user_response needed" while the run was still
    // `working`, so a client that obeyed the banner never sent the call that finished it.
    const isComplete = this.isRunLatchedComplete(context);
    let awaitingFinalVerdict = false;

    if (sessionContext.currentStep && sessionContext.totalSteps) {
      const normalizedStep = Math.min(sessionContext.currentStep, sessionContext.totalSteps);
      const progress = `${normalizedStep}/${sessionContext.totalSteps}`;
      const onFinalStep = normalizedStep === sessionContext.totalSteps;
      awaitingFinalVerdict = !isComplete && onFinalStep && hasPendingReview && !reviewExhausted;
      if (isComplete) {
        lines.push(`✓ Chain complete (${progress})`);
      } else if (awaitingFinalVerdict) {
        // The one state whose text changes: still the final step, still owing a verdict.
        // "step N/N" keeps the downstream step-indicator regexes matching (hooks/lib
        // /session_state.py and the opencode mirror both key on step|progress + N/N).
        lines.push(`→ Final step ${progress} — awaiting gate verdict`);
      } else {
        lines.push(`→ Progress ${progress}`);
      }
    }

    // Handoff footer requires the CURRENT step's brief to be IN this response (S7) — a
    // `nextStepDelegated`-only response carries the one-line advisory, not a handoff, so it
    // falls through to the normal resume/gate-review lines below.
    const currentStepDelegated = this.isCurrentStepDelegated(context);

    if (currentStepDelegated) {
      // Handoff takes priority — gate enforcement passes to sub-agent
      lines.push(this.buildHandoffFooterLine(context, chainIdentifier));
    } else if (isUnknownInterruptPending(sessionContext.pendingReview)) {
      // A hard-paused blocking unknown holds the run WITHOUT issuing a step, so the gate-review
      // line below would be wrong twice in one sentence: there is no step output to report, and
      // no `gate_verdict` clears this hold. The footer and the interrupt section must not
      // advertise different exits from the same hold — the contradiction-inside-one-payload this
      // footer's completion latch already had to fix once.
      lines.push(
        `Next: chain_id="${chainIdentifier}", gate_action="resume" | gate_action="accept_alternative" (with remainder) | gate_action="abort"`
      );
    } else if (reviewExhausted) {
      lines.push(exhaustedReviewMoves(chainIdentifier));
    } else if (isComplete || awaitingFinalVerdict) {
      // One payload states one state (R96). A finished run has no next step, and a run holding
      // its FINAL step for a verdict has none either: the review above says how to answer it,
      // and a `Next:` asking for more step output would invite a step the run does not have.
    } else if (hasPendingReview || this.renderAsksVerdict(context)) {
      // Gate review, or a gated step's render: every render of a gated step asks for its verdict
      // the same way (R171) — only when not delegating
      lines.push(
        `Next: chain_id="${chainIdentifier}", user_response="<your step output>", gate_verdict="GATE_REVIEW: PASS|FAIL - <why>"`
      );
    } else if (sessionContext.currentStep && sessionContext.totalSteps) {
      lines.push(`Next: chain_id="${chainIdentifier}", user_response="<your step output>"`);
    }

    return lines.join('\n');
  }

  /**
   * Builds the NEXT-step delegation advisory via DelegationRenderer (S7). Used to render a full
   * envelope-bearing handoff here; that handoff was phase-shifted — it described the NEXT step
   * while pointing "content above" at the CURRENT step's response. The authoritative handoff
   * (brief + envelope) now renders in ChainOperatorExecutor, in the same response as the
   * delegated step's own content (`buildCurrentStepHandoff`). This method only builds the
   * payload identifying that next step and emits the one-line advisory pointing at it.
   *
   * Resolves the advisory's step identity from the parse-time step the run actually hands off
   * to (`findNextDelegatedStep`), falling back to StepExecutionStage metadata only when no
   * parse-time view exists. Metadata is the LAST resort, not the first (S10): on a gate-review
   * response the metadata names the SYNTHETIC review step (`promptId: '__gate_review__'`,
   * `stepNumber: totalSteps + 1`), so reading it first emitted "Step 4 ("Quality Gate
   * Validation") is delegated" for a 2-step chain — the synthetic step's coordinates must never
   * reach the advisory.
   */
  private buildHandoffSection(context: ExecutionContext): string | null {
    const metadata = context.executionResults?.metadata ?? {};

    const nextStep = this.findNextDelegatedStep(context);
    const parsedNext =
      nextStep !== undefined ? context.parsedCommand?.steps?.[nextStep.index] : undefined;

    // Real delegated-step identity when the parse-time view has it; metadata-derived offset
    // (`current + 1`) only when it does not (e.g. a normal render whose parsed steps are not
    // on the context — pinned by the metadata-path test).
    const fallbackStepNumber =
      ((metadata['stepNumber'] as number | undefined) ?? context.sessionContext?.currentStep ?? 0) +
      1;
    // The run places the step, not the parse array (P6.159): after an insertion, parse step 2 is
    // the run's step 3 of 3 — the count `Progress` uses, retired nodes included.
    const runNodeIds = this.resolveRunStepView(context)?.nodeIds ?? [];
    const runOrdinal = ordinalOf(runNodeIds, parsedNext?.nodeId ?? '');
    const stepNumber = runOrdinal > 0 ? runOrdinal : (parsedNext?.stepNumber ?? fallbackStepNumber);
    const totalSteps =
      runOrdinal > 0
        ? runNodeIds.length
        : parsedNext !== undefined
          ? (context.parsedCommand?.steps?.length ?? 0)
          : ((metadata['totalSteps'] as number | undefined) ??
            context.sessionContext?.totalSteps ??
            0);
    const parsedNextName = parsedNext?.convertedPrompt?.name;
    const promptName =
      parsedNext !== undefined
        ? parsedNextName != null && parsedNextName.trim().length > 0
          ? parsedNextName
          : parsedNext.promptId
        : String(metadata['promptName'] ?? this.resolveNextStepPromptName(context) ?? 'next-step');
    const agentType = nextStep?.agentType;
    const subagentModel = nextStep?.subagentModel;

    const gateCount = context.gates.getAll().length;
    const clientProfile = this.resolveClientProfile(context);
    const renderer = new DelegationRenderer();
    const payload: DelegationPayload = {
      stepNumber,
      totalSteps,
      promptName,
      ...(agentType != null ? { agentType } : {}),
      ...(clientProfile != null ? { clientProfile } : {}),
      ...(subagentModel != null ? { subagentModel } : {}),
      gateCount,
      hasGates: gateCount > 0,
      // Same fallback both payload construction sites use: nodeId when the parsed step carries
      // one, else `n<stepNumber>` for a legacy chain — handoffNodeToken is the one derivation.
      nodeToken: handoffNodeToken({ nodeId: parsedNext?.nodeId, stepNumber }),
      mode: 'blocking',
    };
    return renderer.renderNextStepAdvisory(payload);
  }

  private resolveClientProfile(context: ExecutionContext): RequestClientProfile | undefined {
    const identityContext = context.state.identity.context;
    return identityContext?.clientProfile ?? identityContext?.identity.clientProfile;
  }

  private buildHandoffFooterLine(context: ExecutionContext, chainIdentifier: string): string {
    const delegationProfile = this.resolveClientProfile(context)?.delegationProfile;
    const prefix = getHandoffFooterInstruction(delegationProfile);
    return `Next: ${prefix} (see instructions above), then: chain_id="${chainIdentifier}", user_response="<sub-agent result>"`;
  }

  /**
   * Formats script tool confirmation request for user approval.
   */
  formatConfirmationRequest(
    confirmation: NonNullable<
      typeof ExecutionContext.prototype.state.scripts
    >['confirmationRequired']
  ): string {
    if (!confirmation) return '';

    const sections: string[] = [];

    for (const tool of confirmation.tools) {
      const lines: string[] = [`⚠️ **Tool Confirmation**: \`${tool.toolId}\``];

      if (tool.message) {
        lines.push(`> ${tool.message}`);
      }

      if (tool.matchedParams && tool.matchedParams.length > 0) {
        lines.push(`**Detected parameters:** ${tool.matchedParams.join(', ')}`);
      }

      if (tool.extractedInputs && Object.keys(tool.extractedInputs).length > 0) {
        const summary = this.formatExtractedInputsSummary(tool.extractedInputs);
        lines.push(`**Values:** ${summary}`);
      }

      lines.push(`→ To proceed: \`${tool.resumeCommand}\``);
      sections.push(lines.join('\n'));
    }

    return sections.join('\n\n');
  }

  /**
   * Formats validation errors from script tool validation.
   */
  formatValidationErrors(errors: string[]): string {
    const lines: string[] = [
      '\n---',
      '## ❌ Validation Failed',
      '',
      'The following validation errors prevented auto-execution:',
      '',
    ];

    for (const error of errors) {
      lines.push(`- ${error}`);
    }

    lines.push('');
    lines.push('**Fix the issues above** and try again with updated parameters.');

    return lines.join('\n');
  }

  /**
   * Detects whether the next step is delegated.
   * Checks StepExecutionStage metadata first, falls back to parsed step `delegated` flag
   * (always available from CommandParsingStage, even when pendingReview blocked StepExecutionStage).
   */
  private isNextStepDelegated(context: ExecutionContext): boolean {
    const metadata = context.executionResults?.metadata ?? {};
    if (metadata['nextStepDelegated'] === true) {
      return true;
    }
    return this.findNextDelegatedStep(context) !== undefined;
  }

  /**
   * Detects whether the CURRENT step (the one whose content is in this response) is delegated
   * — i.e. whether ChainOperatorExecutor rendered it as a self-contained EXECUTION BRIEF (R-1).
   * No parsed-steps fallback: unlike `nextStepDelegated`, this flag only exists once
   * `renderStep` has actually run and stamped `currentStepDelegated` on the render result — there
   * is no earlier parse-time signal to fall back to.
   */
  /** The rendered step carries gates and its render asked for the verdict (R171). */
  private renderAsksVerdict(context: ExecutionContext): boolean {
    return context.executionResults?.metadata?.['asksVerdict'] === true;
  }

  private isCurrentStepDelegated(context: ExecutionContext): boolean {
    const metadata = context.executionResults?.metadata ?? {};
    return metadata['currentStepDelegated'] === true;
  }

  /**
   * Finds the parse-time step the run hands off to next, when that step is `delegated: true`.
   * Returns undefined if no delegation is found.
   */
  private findNextDelegatedStep(
    context: ExecutionContext
  ): { promptId: string; agentType?: string; subagentModel?: string; index: number } | undefined {
    const steps = context.parsedCommand?.steps;
    if (!steps || steps.length === 0) {
      return undefined;
    }
    const nextIndex = this.resolveNextStepIndex(context, steps);
    const nextStep = nextIndex === undefined ? undefined : steps[nextIndex];
    if (nextIndex !== undefined && nextStep?.delegated === true) {
      return {
        promptId: nextStep.promptId,
        agentType: nextStep.agentType,
        subagentModel: nextStep.subagentModel,
        // Carried so the P5 visibility decision for the handed-off step can be resolved from
        // the same lookup that found it — recomputing the index elsewhere would give the
        // node-id/ordinal fallback two implementations that could disagree.
        index: nextIndex,
      };
    }
    return undefined;
  }

  /**
   * Which parse-time step the run hands off to next (P6-F1).
   *
   * **Node address first, and asked of the RUN.** The previous implementation resolved the
   * current step by node id and then took `currentIndex + 1` — a node-addressed anchor followed
   * by a positional step. That offset is only correct while the parse array and the run's node
   * list are the same list, which stops being true the moment the P4 mutation policy inserts or
   * retires a node: after a skip the run's next node is two parse positions ahead, so the handoff
   * (and the visibility declarations resolved from it) resolved against a step that will never
   * execute; after an insertion the run's next node is the inserted one, and the handoff rendered
   * a planned step's CTA a step early. The run is the only thing that knows which node comes
   * next, so it is asked, and its answer is matched back into the parse array by identity.
   *
   * A node id with no parse step — the shape every inserted node has — yields `undefined`, i.e.
   * no delegation. That is correct rather than conservative: only planned steps carry `delegated`.
   *
   * The ordinal branch survives for the two cases that have no node address to use: a legacy
   * chain whose steps carry no `nodeId` (P3 D10 keeps it optional), and a call with no run view
   * to ask (no provider injected, or the request names no chain). Those keep the pre-P6 answer
   * exactly, which is what leaves an unmutated run byte-identical.
   */
  private resolveNextStepIndex(
    context: ExecutionContext,
    steps: readonly { nodeId?: string; stepNumber: number }[]
  ): number | undefined {
    const nodeAddressed = steps.some((step) => step.nodeId != null);

    if (nodeAddressed) {
      const nextNodeId = this.resolveNextRunNodeId(context);
      if (nextNodeId === null) {
        // The run is standing at its last live node: there is no next step to hand off to.
        return undefined;
      }
      if (nextNodeId !== undefined) {
        const index = steps.findIndex((step) => step.nodeId === nextNodeId);
        return index >= 0 ? index : undefined;
      }
      // `undefined` = no run view to ask. Fall through to the pre-P6 offset.
    }

    const current = parseStepForNode(
      steps,
      context.sessionContext?.currentNodeId,
      context.sessionContext?.currentStep ?? 1
    );
    return current === undefined ? undefined : steps.indexOf(current) + 1;
  }

  /**
   * The node the run stands at NEXT, read off the live run.
   *
   * Three distinct answers, deliberately not collapsed (the `filterGatesForTarget` split):
   * a **string** is the next live node; **null** is "resolved, and there is none" — the run is on
   * its last node or has walked off the end; **undefined** is "no run to ask", which is the only
   * one that licenses the ordinal fallback. Collapsing `null` into `undefined` would make a
   * finished run silently fall back to the positional offset and render a handoff for a step the
   * run already passed.
   *
   * Only live nodes (`liveNodeIds`) are walked for the successor, for the same reason
   * `filterGatesForTarget` refuses to fire a gate whose target is not live: a step that will not
   * execute cannot be the step being handed off to.
   */
  private resolveNextRunNodeId(context: ExecutionContext): string | null | undefined {
    const view = this.resolveRunStepView(context);
    if (view === undefined) {
      return undefined;
    }

    const liveNodes = liveNodeIds(view);
    const currentNodeId = view.currentNodeId ?? context.sessionContext?.currentNodeId;
    if (currentNodeId === null) {
      return null;
    }
    if (currentNodeId === undefined) {
      return undefined;
    }

    const currentIndex = liveNodes.indexOf(currentNodeId);
    if (currentIndex < 0) {
      // The run is standing somewhere this view cannot place — do not invent a successor.
      return undefined;
    }
    return liveNodes[currentIndex + 1] ?? null;
  }

  /**
   * The live run behind this request, or undefined when there is none to ask.
   *
   * Resolved per call rather than memoized: the assembler holds no per-request state, the answer
   * cannot change while one response is being assembled, and the provider reads already-loaded
   * session maps.
   */
  private resolveRunStepView(context: ExecutionContext): RunStepView | undefined {
    if (this.runStepViewProvider === undefined) {
      return undefined;
    }
    const chainId = context.getRequestedChainId();
    return chainId === undefined
      ? undefined
      : this.runStepViewProvider(chainId, context.getScopeOptions());
  }

  /**
   * Resolves the prompt name for the next delegated step from parsed steps.
   */
  private resolveNextStepPromptName(context: ExecutionContext): string | undefined {
    return this.findNextDelegatedStep(context)?.promptId;
  }

  /**
   * Builds gate review CTA with verdict template, attempt counter, and submit instructions.
   * Retry hints are NOT included here — they are SSOT in chain-operator-executor supplementalSections
   * (already present in base content).
   */
  private buildGateReviewCTA(context: ExecutionContext): string | null {
    const pendingReview = context.sessionContext?.pendingReview;
    if (!pendingReview) {
      return null;
    }

    // The synthetic unknown-interrupt hold is not a gate review and no `gate_verdict` resolves
    // it. `buildInterruptSection` renders its call to action, with the verbs that DO resolve it.
    // Checked before the phase-guard branches below because a run cannot hold on both: stage 16
    // raises this one only when nothing is already pending.
    if (isUnknownInterruptPending(pendingReview)) {
      return null;
    }
    // An exhausted review takes no verdict (R9): the "Retry Limit Reached" section the step's
    // render carries names the `gate_action` moves, and the footer's `Next:` repeats them.
    if (pendingReview.phase === 'exhausted') {
      return null;
    }

    const chainId = context.sessionContext?.chainId ?? '';
    // Same counter the blocked reply reads (`resolveAttemptCounter`), rendered in this footer's
    // own long-standing `N/M` shorthand. One source of the numbers, two renderings — a second
    // computation here is how the two surfaces would come to disagree about which attempt a
    // caller is on.
    const attempt = this.resolveAttemptCounter(context);
    const attemptInfo = attempt !== undefined ? ` (attempt ${attempt.current}/${attempt.max})` : '';

    const isPhaseGuardReview = pendingReview.gateIds?.includes(PHASE_GUARD_GATE_ID) === true;
    const hasOtherGates = pendingReview.gateIds?.some((id) => id !== PHASE_GUARD_GATE_ID) ?? false;

    let header: string;
    let gatesLine: string;

    if (isPhaseGuardReview && !hasOtherGates) {
      header = 'Structural Review Required';
      gatesLine = 'phase guards';
    } else if (isPhaseGuardReview && hasOtherGates) {
      header = 'Structural + Gate Review Required';
      gatesLine = '';
    } else {
      header = 'Gate Review Required';
      gatesLine = '';
    }

    const structuredTemplate = buildStructuredVerdictTemplate(
      pendingReview.gateIds ?? [],
      pendingReview.prompts,
      this.resolveGateTiers(context),
      this.resolveCheckResults(context)
    );

    const judgeSection = this.buildJudgeReviewSection(context);
    const judgeBlock = judgeSection !== '' ? `\n\n${judgeSection}` : '';

    return `\n---\n\n**${header}**${attemptInfo}\n\n${gatesLine}${this.buildFailedGateSummary(context)}${judgeBlock}\n\nReview your output above against the gates, then submit:\n\n\`\`\`\nchain_id="${chainId}"\ngate_verdict=${structuredTemplate}\n\`\`\`\n\nSet \`"overall": "FAIL"\` and say what needs improvement if the gates are not met. Rationales are single-line.\n\nA legacy string form is still accepted: \`gate_verdict="GATE_REVIEW: PASS - [assessment]"\`.`;
  }

  /**
   * The judge prompt `GateReviewStage` built for this review's `mode: judge` gates (P4.133).
   *
   * The ONE renderer of `metadata.judge`: the review footer and the blocked reply both call it,
   * and each reply is built by exactly one of them, so a reply carries the prompt at most once.
   * Fenced with four backticks because the prompt fences the output slot with three.
   *
   * Empty string when no gate in the review is judge-routed, so a self-reviewed reply renders
   * byte-identical to what it did before this section existed.
   */
  private buildJudgeReviewSection(context: ExecutionContext): string {
    const judge = this.resolveJudgeReview(context);
    if (judge === undefined) {
      return '';
    }

    const gates = judge.judgeGateIds.map((id) => `\`${id}\``).join(', ');
    const model = judge.modelHint !== undefined ? ` (suggested model: ${judge.modelHint})` : '';
    return [
      `**Independent judge required** for ${gates} — do not grade ${judge.judgeGateIds.length === 1 ? 'this gate' : 'these gates'} yourself.`,
      `Give a separate sub-agent${model} ONLY the prompt below, with your step output in place of \`${JUDGE_OUTPUT_PLACEHOLDER}\`, and use the verdict it returns for ${judge.judgeGateIds.length === 1 ? 'that gate' : 'those gates'}.`,
      '',
      '````markdown',
      judge.judgePrompt,
      '````',
    ].join('\n');
  }

  /**
   * `metadata.judge`, when the review render carried one — only the review stage stamps it.
   * Present but malformed throws: skipping it would send a judge-routed gate back to self-review
   * with nothing in the reply to say so.
   */
  private resolveJudgeReview(context: ExecutionContext): JudgeReviewMetadata | undefined {
    const judge = context.executionResults?.metadata?.['judge'] as
      Partial<JudgeReviewMetadata> | undefined;
    if (judge === undefined) {
      return undefined;
    }
    if (typeof judge.judgePrompt !== 'string' || !Array.isArray(judge.judgeGateIds)) {
      throw new Error('metadata.judge is missing judgePrompt or judgeGateIds');
    }
    return {
      judgePrompt: judge.judgePrompt,
      judgeGateIds: judge.judgeGateIds,
      ...(typeof judge.modelHint === 'string' ? { modelHint: judge.modelHint } : {}),
    };
  }

  /**
   * The gates the reviewer just marked FAIL, in its own words (P4.75).
   *
   * Added above the verdict template because without it a retry reply is the SAME full N-gate
   * template the first attempt showed: the submitter has to re-derive which two of five it
   * failed by re-reading its own echoed prior response. Naming them costs one block and makes
   * the retry addressable.
   *
   * Empty string when this call carried no per-gate detail — an overall-only verdict, a PASS,
   * or no verdict at all — so every existing reply renders byte-identical.
   */
  private buildFailedGateSummary(context: ExecutionContext): string {
    const failed = this.resolveFailedGateVerdicts(context);
    if (failed.size === 0) {
      return '';
    }

    const lines = [...failed].map(([gateId, rationale]) => `- \`${gateId}\` — ${rationale}`);
    return `\n\n**Gates you marked FAIL:**\n\n${lines.join('\n')}`;
  }

  /**
   * Rationale per gate the reviewer marked FAIL on this call, keyed by gate id.
   *
   * Reads `context.state.gates.perGateVerdicts`, which `GateVerdictProcessor` wrote from the
   * submission being processed in this same request — never an instance field, so STDIO (one
   * server per connection) and Streamable HTTP (a fresh server per request) render the same
   * reply from the same source.
   *
   * A FAIL entry whose rationale is empty still appears: the gate id is the fact worth
   * carrying, and dropping the entry would make a terse reviewer look like a silent one.
   */
  private resolveFailedGateVerdicts(context: ExecutionContext): ReadonlyMap<string, string> {
    const failed = new Map<string, string>();
    for (const entry of context.state.gates.perGateVerdicts ?? []) {
      if (entry.verdict !== 'FAIL') {
        continue;
      }
      const rationale = entry.rationale ?? '';
      failed.set(entry.gateId, rationale.length > 0 ? rationale : 'no rationale given');
    }
    return failed;
  }

  /**
   * The gate review instructions a blocked response carries — the one thing a blocked caller can
   * act on, from whichever of the two places this call actually put it.
   *
   * `context.gateInstructions` is written by gate enhancement on the SINGLE-PROMPT path only
   * (`GateEnhancementService`, the enhanced-template tail). On a chain step the per-step gate text
   * goes to `step.metadata['gateInstructions']` instead, and the rendered review — criteria,
   * attempt counter, resubmit schema — is what `GateReviewStage` put in `context.executionResults`.
   * Reading only the first field meant every blocked CHAIN step returned a stub naming the gates
   * and nothing else, while `blockResponseOnFail`'s contract is that the review instructions ARE
   * returned. Measured 2026-09-20: 291 characters, no criteria, no attempt counter.
   *
   * The execution result is admitted by its own predicate — `metadata.gateReview` present — not by
   * merely existing. That metadata is stamped only by the review render, so the content is
   * instruction text; on any other path `executionResults` holds the model output this block
   * exists to suppress, and returning it would defeat the block. Verified on the render: it
   * carries no `user_response` text.
   */
  private resolveBlockedReviewInstructions(context: ExecutionContext): string {
    const enhanced = context.gateInstructions ?? '';
    if (enhanced.trim() !== '') return enhanced;

    const results = context.executionResults;
    const isGateReviewRender = results?.metadata?.['gateReview'] !== undefined;

    return isGateReviewRender && typeof results?.content === 'string' ? results.content : '';
  }

  /**
   * The human-readable half of the mid-chain interrupt (row 2.4, plan §Interrupt payload).
   *
   * Mirrors the gate-pending prose deliberately — same `---` rule, same bold header, same
   * fenced resume block — because a client that already knows how to read a gate hold should not
   * need a second parser to read this one. What differs is the vocabulary in the fence:
   * `gate_verdict` resolves a gate review, and none of these verbs is a verdict.
   *
   * Returns null when this call raised no interrupt, which is every call on a run with no open
   * blocking unknown.
   */
  private buildInterruptSection(context: ExecutionContext): string | null {
    const interrupt = context.state.session.chainInterrupt;
    if (interrupt === undefined) return null;

    // A completed run names every unknown it never resolved, and offers nothing to act on (R97, R105).
    if (this.isRunLatchedComplete(context)) {
      const named = interrupt.openBlockingUnknowns.map((u) => `\`${u.id}\` — ${u.statement}`);
      return `\n---\n\n**Unresolved unknown**: ${named.join('\n\n**Unresolved unknown**: ')}`;
    }
    const header = interrupt.paused ? 'Chain Paused — Blocking Unknown' : 'Blocking Unknown';
    const affected = listLine('Affected steps (declared)', interrupt.affectedStepIds);
    const uninvestigated = listLine(UNINVESTIGATED_LABEL, interrupt.uninvestigatedUnknownIds);
    const remaining =
      interrupt.remainingNodes.length > 0
        ? `\n\nRemaining plan:\n${interrupt.remainingNodes
            .map((node) => `- \`${node.id}\` — ${node.stepName} (${node.promptId})`)
            .join('\n')}`
        : '\n\nRemaining plan: none — this is the last step.';
    const verbs = resolveInterruptVerbs(interrupt.paused, false)
      .map((verb) => `- ${verb}`)
      .join('\n');

    return `\n---\n\n**${header}**\n\n${interrupt.statement}${uninvestigated}${affected}${remaining}\n\nResolve with \`chain_id="${context.sessionContext?.chainId ?? ''}"\` plus one of:\n\n${verbs}`;
  }

  /**
   * The machine-readable half: `structuredContent.chain_interrupt`, verbatim per the plan's
   * §Interrupt payload block.
   *
   * snake_case at the wire boundary while {@link ChainInterrupt} stays camelCase inside the
   * engine — this method IS that translation, and it is the only one, which is why the wire
   * shape cannot drift by a stage renaming an internal field.
   *
   * Returned rather than assigned: `ToolResponse` is assembled by `ResponseFormattingStage`, so
   * the assembler builds payloads and the stage owns the response object, the same split the
   * string sections already follow. Undefined means "no interrupt", not "empty interrupt".
   */
  buildInterruptStructuredContent(context: ExecutionContext): Record<string, unknown> | undefined {
    const interrupt = context.state.session.chainInterrupt;
    if (interrupt === undefined) return undefined;
    const latched = this.isRunLatchedComplete(context);

    return {
      kind: 'chain_interrupt',
      reason: interrupt.reason,
      // `unknown` is what this interrupt is about (the one the inserted step investigates, R119);
      // the first list is every open one, the second the ids the text's open-with-no-step line names
      // — empty on a completed run, whose text lists them as unresolved and no step will
      // investigate one (R114 third amendment).
      unknown: { id: interrupt.unknownId, statement: interrupt.statement },
      open_blocking_unknowns: [...interrupt.openBlockingUnknowns], // already `{id, statement}`
      uninvestigated_unknown_ids: latched ? [] : [...interrupt.uninvestigatedUnknownIds],
      affected_step_ids: [...interrupt.affectedStepIds],
      // camelCase `promptId`/`stepName` inside these entries is the plan's declared shape, not
      // an oversight: they name IR node fields a caller would author back verbatim in a
      // `remainder`, so converting them would hand the client a vocabulary it cannot resubmit.
      remaining_nodes: [...interrupt.remainingNodes], // already `{id, promptId, stepName}`
      paused: interrupt.paused,
      resume: {
        chain_id: context.sessionContext?.chainId ?? '',
        verbs: resolveInterruptVerbs(interrupt.paused, latched),
      },
    };
  }

  /**
   * Builds the completion message for a run that has actually finished.
   *
   * Gated on the latch rather than on `isFinalChainStep`, which is true from the moment the
   * final step is *rendered*. Under the old guard this printed "✅ Chain execution complete.
   * You may now respond to the user." on the call that handed the client its last step to do —
   * the same one-call-early claim the footer made, on a second surface. With the footer now
   * honest the two would have contradicted each other inside one payload.
   */
  private buildFinalStepMessage(context: ExecutionContext): string | null {
    if (!this.isFinalChainStep(context) || !this.isRunLatchedComplete(context)) {
      return null;
    }
    const completion = '\n\n✅ Chain execution complete. You may now respond to the user.';
    const cta = this.buildUsageCTA(context);
    return cta ? `${completion}\n\n${cta}` : completion;
  }

  /**
   * Checks whether the current step is the final step of a chain execution.
   */
  private isFinalChainStep(context: ExecutionContext): boolean {
    const session = context.sessionContext;
    if (!session?.isChainExecution) {
      return false;
    }
    // A single-prompt execution with a session (e.g., for gate tracking)
    // is NOT a chain completion — it should behave like a normal single prompt
    if (context.executionPlan?.strategy === 'single') {
      return false;
    }
    const { currentStep, totalSteps } = session;
    if (typeof currentStep !== 'number' || typeof totalSteps !== 'number' || totalSteps <= 0) {
      return false;
    }
    return currentStep >= totalSteps;
  }

  /**
   * Tier per gate for the verdict template, from the pending review `GateReviewStage` recorded.
   *
   * Read off the review rather than loaded here: this assembler takes no gate provider and is
   * synchronous, and giving it one to answer a question the gate-review stage has already
   * answered would put a second reader on the gate registry for no new fact.
   *
   * An id with no recorded tier answers `check` so it stays visible in the verdict template.
   * Classification alone establishes no criterion result; those come from `checkResults`.
   */
  private resolveGateTiers(context: ExecutionContext): ReadonlyMap<string, GateTier> {
    const tiers = context.sessionContext?.pendingReview?.gateTiers;
    return new Map(Object.entries(tiers ?? {}));
  }

  /** Recorded check results for the pending review, keyed by gate id (empty when none ran). */
  private resolveCheckResults(context: ExecutionContext): ReadonlyMap<string, GateCheckResult> {
    const results = context.sessionContext?.pendingReview?.checkResults ?? [];
    return new Map(results.map((result) => [result.gateId, result]));
  }

  /**
   * Renders the declared-header vocabulary for the framework active on this single-prompt
   * execution, or `null` when there is nothing to declare — no provider wired, no session (an
   * ungated single prompt never reaches stage 19), no framework resolves, or the framework
   * declares no guarded phases. Mirrors `buildResponseFormatSection`'s "Required Sections" block
   * in `chain-operator-executor.ts` verbatim rather than reimplementing the format, so the two
   * declaration surfaces cannot drift from each other.
   */
  private buildDeclaredSectionsBlock(context: ExecutionContext): string | null {
    const declaredSections = this.resolveDeclaredSections(context);
    if (declaredSections.length === 0) {
      return null;
    }

    const lines: string[] = [
      '**Required Sections** — emit these headers verbatim; they are graded structurally:',
    ];
    for (const section of declaredSections) {
      const qualifier = section.required ? 'required' : 'optional';
      const criteria = section.criteria.length > 0 ? `; ${section.criteria.join('; ')}` : '';
      lines.push(`- \`${section.header}\` (${qualifier}${criteria})`);
    }
    return lines.join('\n');
  }

  /**
   * Declared phase-guard headers for the framework active on this single-prompt execution, or
   * `[]` when this execution will not be graded by stage 19 at all.
   *
   * Five independent skip conditions (Tier 2.6; the fourth added for issue #228, the fifth by
   * R22), each a separate reason to declare nothing:
   *
   * 1. No provider wired — pre-Tier-2 behavior, byte-identical.
   * 2. No session (`context.sessionContext?.sessionId` absent) — an UNGATED single prompt never
   *    gets a session (`execution-planner.ts:427-450` only sets `requiresSession` for explicit
   *    `gates`, a `gate` operator, or `chainSteps`), and stage 19 skips whenever the session is
   *    absent (`19-phase-guard-verification-stage.ts:73-78`). Declaring headers for a prompt that
   *    will never be graded against them would spend tokens for nothing.
   * 3. No framework resolves, or the resolved framework declares no guarded phases — `provider()`
   *    itself returns `[]` for both, so no separate check is needed.
   * 4. The prompt DECLINED the framework — the author wrote
   *    `injection.system-prompt.enabled: false`, or a modifier suppressed it. Telling a prompt
   *    that opted out of a framework to emit that framework's headers "verbatim; they are graded
   *    structurally" states two things that are not true of it: it was not given the framework,
   *    and on this path nothing grades it.
   *
   *    Judged by `isFrameworkInjected`, the SAME predicate the step's framework gates are
   *    resolved with (`gate-enhancement-service.ts`), not by `state.injection.systemPrompt.inject`
   *    as it was until now. Those answer different questions: the state field says whether the
   *    system prompt was EMITTED THIS TURN, which frequency rules ("once per session") make false
   *    for a prompt that never declined anything — and then the block is withheld from a prompt
   *    stage 19 still grades, which is the "blocked on a contract it was never shown" shape this
   *    condition exists to prevent, pointed the other way. One decision, both halves: the chain
   *    surface reads the same predicate for its own opt-out.
   *
   * Condition 4 is deliberately NOT mirrored onto the chain surface
   * (`chain-operator-executor.resolveDeclaredSections`), which documents the opposite ruling for
   * its own path and is correct there: stage 19's declared-header set is RUN-WIDE, so a sibling
   * step that declared a header keeps that header blocking for the whole run, and withholding
   * the vocabulary from one opted-out step would grade it against headers it was never shown.
   * No such set exists here — the single-prompt path records no `declaredSections` into the
   * session at all (`18-execution-stage.ts:206` writes them only for a chain node), so nothing
   * downstream can be made unsatisfiable by this skip.
   *
   * Reads through the provider on every call — no cache — so framework hot-reload keeps working,
   * matching the chain path's `resolveDeclaredSections`.
   */
  private resolveDeclaredSections(context: ExecutionContext): DeclaredSection[] {
    const provider = this.declaredSectionsProvider;
    if (!provider) {
      return [];
    }

    if (context.sessionContext?.sessionId === undefined) {
      return [];
    }

    if (
      !isFrameworkInjected({
        modifiers: context.getExecutionModifiers(),
        promptInjection: context.parsedCommand?.convertedPrompt?.injection,
      }) ||
      // 5. The prompt turned framework gates off (R22): the sections are graded, so a gate.
      !declaresFrameworkSections(context.parsedCommand?.convertedPrompt)
    ) {
      return [];
    }

    // `.id`, never `.type` — `FrameworkManager.getFrameworkGuide` lowercases its argument, so
    // `.type` only resolves for CAGEERF by coincidence ('CAGEERF' → 'cageerf') and would silently
    // miss a framework whose discriminator is not simply its lowercased id (`5w1h`).
    // `19-phase-guard-verification-stage` resolves on `.id`; the declaration and the guard must
    // read the same field or the prompt names different headers than the guard grades (F2's own
    // shape, one layer over). Never branch on `context.sessionContext?.isChainExecution` here —
    // F2 records it returns true for gated single prompts too, so it cannot discriminate this
    // case; `context.executionPlan?.strategy` is the reliable signal this method already avoids
    // needing, because `formatSinglePromptResponse` is only invoked for non-chain formatting
    // contexts (`21-formatting-stage.ts:103-114`).
    const frameworkId = context.frameworkContext?.selectedFramework.id ?? '';
    if (frameworkId === '') {
      return [];
    }

    return provider(frameworkId);
  }

  /**
   * What this call's non-blocking FAILs warned about (an advisory verdict, a phase guard in warn
   * mode). It reports the call itself, so it renders even when gate content is suppressed: the
   * FAIL that completes a chain still happened (P6.37).
   */
  private buildAdvisoryWarnings(context: ExecutionContext): string[] {
    const warnings = context.state.gates.advisoryWarnings;
    return warnings.length === 0
      ? []
      : ['\n---\n**Advisory Gate Warnings:**', ...warnings.map((warning) => `- ${warning}`)];
  }

  /**
   * Central gate content suppression check.
   * Returns true when gate-related content (CTAs, validation info,
   * instructions, advisory warnings) should NOT appear in the response.
   *
   * Called once per format method as `gateActive = !isGateContentSuppressed()`,
   * then threaded to all gate-emitting sections. Sub-methods do NOT call this
   * directly — the orchestrator decides, sub-methods obey.
   *
   * Entry points: formatChainResponse, formatSinglePromptResponse (top-level),
   *               buildGateValidationInfo (external entry from ResponseFormattingStage)
   */
  private isGateContentSuppressed(context: ExecutionContext): boolean {
    return context.state.session.chainComplete === true;
  }

  /** Checks injection control setting for gate guidance (not suppression — caller handles that). */
  private isGateGuidanceInjectionEnabled(context: ExecutionContext): boolean {
    return context.state.injection?.gateGuidance?.inject !== false;
  }

  private extractBaseContent(context: ExecutionContext): string {
    return typeof context.executionResults!.content === 'string'
      ? context.executionResults!.content
      : JSON.stringify(context.executionResults!.content, null, 2);
  }

  /**
   * A completed run's re-run (R89): the command that re-parses to the same run. A chain prompt is
   * written with its operators (P6.186); an arrow-chain run is the command text the parser consumed
   * whole and the blueprint keeps (P6.194), the JSON form's decoded (P6.222). A workflow: no line.
   */
  private buildUsageCTA(context: ExecutionContext): string | null {
    const parsed = context.parsedCommand;
    const command =
      parsed?.convertedPrompt !== undefined
        ? this.buildInvocationString(context, parsed.convertedPrompt)
        : rerunCommandText(parsed?.metadata);
    return command === undefined ? null : `---\nRe-run: \`${command}\``;
  }

  /**
   * Builds context-aware CTA from all active operators.
   * Composition: primary action (exclusive) + hints (additive) + re-run (always).
   * Gate action is only appended when gateActive is true (decided by caller).
   */
  private buildNextActionCTA(context: ExecutionContext, gateActive = true): string | null {
    const lines: string[] = ['---'];
    if (!this.isRunLatchedComplete(context)) {
      const hasPrimaryAction = gateActive && this.appendGateAction(lines, context);

      this.appendVerifyHint(lines, context);
      this.appendVerifyBudget(lines, context);
      this.appendLoopHint(lines, context);

      if (!hasPrimaryAction) {
        this.appendSessionAction(lines, context);
      }
    }

    this.appendRerunLine(lines, context);

    return lines.length > 1 ? lines.join('\n') : null;
  }

  /** Appends the action accepted by the actual pending review, including deferred singles. */
  private appendGateAction(lines: string[], context: ExecutionContext): boolean {
    const chainId = context.sessionContext?.chainId;
    const pendingReview = context.sessionContext?.pendingReview;
    if (pendingReview === undefined) return false;

    // Accumulated gates describe guidance, not a durable hold. The review owns the gates this
    // action answers, even when the run-wide or current-step gate lists differ.
    const gateIds = pendingReview.gateIds;
    if (gateIds.length === 0 || chainId == null || chainId.length === 0) return false;

    // An exhausted review refuses every verdict (R9): offer the moves it accepts, no template.
    if (pendingReview.phase === 'exhausted') {
      lines.push('**Review Retry Limit Reached**', '', `**Gates**: ${gateIds.join(', ')}`, '');
      lines.push(EXHAUSTED_REVIEW_CHOICE, '', exhaustedReviewMoves(chainId));
      return true;
    }
    const checkResults = this.resolveCheckResults(context);
    const structuredTemplate = buildStructuredVerdictTemplate(
      gateIds,
      pendingReview.prompts,
      this.resolveGateTiers(context),
      checkResults
    );

    lines.push('**Review Required**');
    lines.push('');
    lines.push(`**Gates**: ${gateIds.join(', ')}`);
    lines.push('');
    // Names what the two halves of the template are for. "Review your output against the gate
    // criteria" asked for a self-grade on every gate, which is what produced five "not
    // applicable" rationales per run and no caught defect (ruling B4).
    lines.push(
      checkResults.size > 0
        ? 'Recorded check results appear in the template; attest reminders in one field, then submit:'
        : 'No criterion results are recorded for this review; attest reminders in one field, then submit:'
    );
    lines.push('');
    lines.push('```');
    lines.push(`chain_id="${chainId}"`);
    lines.push(`gate_verdict=${structuredTemplate}`);
    lines.push('```');
    return true;
  }

  /** Appends shell verification command hint when :: verify:"cmd" operators are present. */
  private appendVerifyHint(lines: string[], context: ExecutionContext): void {
    const namedGates = context.parsedCommand?.namedInlineGates;
    if (namedGates == null) return;

    const verifyCommands = namedGates
      .map((g) => g.shellVerify?.command)
      .filter((cmd): cmd is string => cmd != null && cmd.length > 0);
    if (verifyCommands.length === 0) return;

    const formatted = verifyCommands.map((cmd) => `\`${cmd}\``).join(', ');
    lines.push(`Verification: ${formatted} runs automatically on each attempt`);
  }

  /**
   * Publishes the RESOLVED attempt budget for a shell-verify gate.
   *
   * The preset table in the README claims `:fast` = 1 try/30s, `:full` = 5/5min, `:extended` =
   * 10/10min, and until this line existed none of it was observable: the presets expand inside
   * `InlineGateProcessor.setupShellVerification`, which logs the resolved values and stores them on
   * `state.gates.pendingShellVerification`, but nothing rendered them. `:fast` and `:extended`
   * therefore produced BYTE-IDENTICAL responses, so a conformance scenario for either could assert
   * nothing beyond "the syntax parsed" — three published numbers with no way to check them (plan
   * row 0.5.22).
   *
   * Read from the pending state rather than the parsed operator on purpose: the operator carries
   * what the USER typed, which for a bare `:fast` is `maxIterations: undefined`. That is exactly
   * how `appendLoopHint` came to print the global default for every preset.
   */
  private appendVerifyBudget(lines: string[], context: ExecutionContext): void {
    const budget = context.state?.gates?.shellVerifyBudget;
    if (budget == null) return;

    const { maxAttempts: attempts, timeoutMs, preset } = budget;

    const parts = [`${attempts} attempt${attempts === 1 ? '' : 's'}`];
    if (timeoutMs != null) parts.push(`${Math.round(timeoutMs / 1000)}s timeout`);
    const suffix = preset != null ? ` (preset: ${preset})` : '';
    lines.push(`Verify budget: ${parts.join(' / ')}${suffix}`);
  }

  /** Appends Ralph loop hint when :: verify:"cmd" loop:true is active. */
  private appendLoopHint(lines: string[], context: ExecutionContext): void {
    const operators = context.parsedCommand?.operators?.operators;
    if (operators == null) return;

    const loopGate = operators.find(
      (op): op is GateOperator => op.type === 'gate' && op.shellVerify?.loop === true
    );
    if (loopGate?.shellVerify == null) return;

    // Prefer the resolved budget over the typed one: a bare `:fast` leaves `maxIterations`
    // undefined on the operator, so reading it here printed the global default no matter which
    // preset was named. The pending state holds what the gate will actually enforce.
    const max =
      context.state?.gates?.shellVerifyBudget?.maxAttempts ??
      loopGate.shellVerify.maxIterations ??
      SHELL_VERIFY_DEFAULT_MAX_ITERATIONS;
    lines.push(`Loop mode: autonomous retry (max ${max} iterations)`);
  }

  /** Appends session resume CTA when an active session has no pending review action. */
  private appendSessionAction(lines: string[], context: ExecutionContext): void {
    const chainId = context.sessionContext?.chainId;
    if (chainId == null || chainId.length === 0) return;

    lines.push(`Continue: \`chain_id="${chainId}", user_response="<your output>"\``);
  }

  /** Appends the re-run line; with no prompt to name there is none — never `>>prompt` (R89). */
  private appendRerunLine(lines: string[], context: ExecutionContext): void {
    const prompt = context.parsedCommand?.convertedPrompt;
    if (prompt !== undefined)
      lines.push(`Re-run: \`${this.buildInvocationString(context, prompt)}\``);
  }

  /** The command that re-parses to this run (R89): its operators, the prompt and args, its gates. */
  private buildInvocationString(context: ExecutionContext, prompt: ConvertedPrompt): string {
    const parts: string[] = [];
    this.appendOperatorPrefixes(parts, context);
    parts.push(`>>${prompt.id}${this.buildArgString(prompt, context.parsedCommand?.promptArgs)}`);
    this.appendGateSuffixes(parts, context);
    return parts.join(' ');
  }

  /** Appends modifier, framework, and style operator prefixes to parts. */
  private appendOperatorPrefixes(parts: string[], context: ExecutionContext): void {
    const modifierToken = this.resolveModifierToken(context.parsedCommand?.modifiers);
    if (modifierToken != null) {
      parts.push(modifierToken);
    }

    const frameworkToken = this.resolveFrameworkToken(context);
    if (frameworkToken != null) {
      parts.push(frameworkToken);
    }

    const style = context.parsedCommand?.styleSelection;
    if (style != null && style.length > 0) {
      parts.push(`#${style}`);
    }
  }

  /** Resolves the framework operator token for CTA display. */
  private resolveFrameworkToken(context: ExecutionContext): string | null {
    const fwDecision = context.frameworkAuthority.getCachedDecision();
    if (fwDecision?.source === 'operator' && fwDecision.frameworkId != null) {
      return `^${fwDecision.frameworkId}`;
    }
    // Fallback: show @FRAMEWORK from parser when user typed it,
    // even if decision authority disabled it (e.g., implicit %clean on script-tool prompts)
    const operatorOverride = context.parsedCommand?.executionPlan?.frameworkOverride;
    return operatorOverride ? `^${operatorOverride.toLowerCase()}` : null;
  }

  /** Resolves the modifier token from execution modifiers. */
  private resolveModifierToken(modifiers?: ExecutionModifiers): string | null {
    if (modifiers?.clean === true) return '%clean';
    if (modifiers?.lean === true) return '%lean';
    if (modifiers?.judge === true) return '%judge';
    return null;
  }

  /** Appends inline gate criteria and named gates as suffixes. */
  private appendGateSuffixes(parts: string[], context: ExecutionContext): void {
    // A chain prompt's command criteria were folded onto its steps and left the command (R37);
    // the anonymous gate operator the command was parsed into still carries them (P6.186).
    const anonymousGate = context.parsedCommand?.operators?.operators.find(
      (op): op is GateOperator => op.type === 'gate' && op.gateId === undefined
    );
    const commandCriteria =
      context.parsedCommand?.inlineGateCriteria ?? anonymousGate?.parsedCriteria ?? [];
    for (const criteria of commandCriteria) {
      parts.push(`:: '${criteria}'`);
    }
    for (const { gateId, criteria, shellVerify } of context.parsedCommand?.namedInlineGates ?? []) {
      parts.push(
        shellVerify !== undefined
          ? formatShellVerifyToken(shellVerify)
          : `:: ${gateId}:"${criteria[0] ?? ''}"`
      );
    }
  }

  /**
   * Builds the argument portion of an invocation string from prompt schema + user values.
   */
  private buildArgString(prompt?: ConvertedPrompt, userArgs?: Record<string, unknown>): string {
    if (prompt?.arguments == null || prompt.arguments.length === 0) return '';

    const MAX_DISPLAY = 4;
    const args = prompt.arguments;
    const displayArgs =
      args.length > MAX_DISPLAY
        ? args.filter((a) => a.required || (userArgs != null && a.name in userArgs))
        : args;

    if (displayArgs.length === 0) return '';

    const parts = displayArgs
      .map((arg) => this.formatArgForCTA(arg, userArgs))
      .filter((part): part is string => part != null);

    return parts.length > 0 ? ' ' + parts.join(' ') : '';
  }

  /** Formats a single argument for CTA display. */
  private formatArgForCTA(
    arg: { name: string; required: boolean; defaultValue?: unknown },
    userArgs?: Record<string, unknown>
  ): string | null {
    // JSON quoting is the escape set the argument parser decodes (`parseQuotedValue`), so a value
    // carrying a quote or a backslash re-parses to itself (P6.178, R89).
    if (userArgs != null && arg.name in userArgs) {
      return `${arg.name}:${JSON.stringify(String(userArgs[arg.name]))}`;
    }
    if (arg.defaultValue !== undefined) {
      return `${arg.name}:${JSON.stringify(String(arg.defaultValue))}`;
    }
    if (arg.required) {
      return `${arg.name}:"<${arg.name}>"`;
    }
    return null;
  }

  private formatExtractedInputsSummary(inputs: Record<string, unknown>): string {
    const parts: string[] = [];

    for (const [key, value] of Object.entries(inputs)) {
      if (value === undefined || value === null) continue;

      let display: string;
      if (Array.isArray(value)) {
        display = `[${value.length} items]`;
      } else if (typeof value === 'object') {
        const keys = Object.keys(value);
        display = `{${keys.length} fields}`;
      } else if (typeof value === 'string' && value.length > 30) {
        display = `"${value.substring(0, 27)}..."`;
      } else {
        display = JSON.stringify(value);
      }

      parts.push(`${key}=${display}`);
    }

    return parts.join(', ') || '(none)';
  }
}

/**
 * Builds the structured `gate_verdict` template keyed to actual gate names.
 *
 * Offered ahead of the string template because a structured submission is
 * validated by the tool schema and cannot be malformed, whereas the string
 * form is a format the model has to reproduce and the server then reads back
 * with five fallback regexes. Advertising the fragile form first would keep
 * steering clients into the path that can fail.
 *
 * Rendered as JSON rather than prose so it can be copied into the call
 * directly. Rationale placeholders are single-line, which is what the
 * schema requires.
 *
 * A module function, not a method: a detached node's review (row 4.8) renders the same template
 * from `StepResponseCaptureStage`, which holds no assembler.
 */
export function buildStructuredVerdictTemplate(
  gateIds: readonly string[],
  prompts: readonly GateReviewPrompt[],
  tiers: ReadonlyMap<string, GateTier>,
  checkResults: ReadonlyMap<string, GateCheckResult>
): string {
  const promptMap = buildPromptLookup(prompts);

  const entries: string[] = [];
  const reminderIds: string[] = [];

  // Walk the FULL advertised list, not a pre-sliced prefix: slicing before the walk let a run
  // of leading reminders push a later check off the template before it was ever considered.
  // The cap binds only the collected check entries (below); reminders are never counted against
  // it because they render once in the `reminders` field rather than one `per_gate` slot each.
  gateIds.forEach((gateId, position) => {
    // The index is the gate's place in the ORIGINAL list, not its place among the entries:
    // `parseGateVerdicts` matches `[n]` back to the advertised gate list, so renumbering the
    // survivors after reminders are dropped (or a check is capped out) would point every
    // verdict at the wrong gate.
    const index = position + 1;
    if ((tiers.get(gateId) ?? 'check') === 'reminder') {
      reminderIds.push(gateId);
      return;
    }
    if (entries.length >= MAX_GATE_VERDICT_ENTRIES) {
      return;
    }

    const prompt = promptMap.get(gateId);
    const label = prompt?.gateName ?? gateId;
    // Criteria carry the reviewer's actual checklist; dropping them would
    // make the structured form less informative than the string form it
    // replaces. Quotes are escaped because this lands inside a JSON string.
    const criteria = prompt?.criteriaSummary;
    const suffix = criteria != null && criteria.length > 0 ? ` — ${criteria}` : '';
    // A recorded result is the engine's, so the template states it rather than asking for it
    // — a slot the model fills is a slot it can fill wrongly, and the processor refuses a PASS
    // over a recorded failure anyway. `<why>` survives only where nothing ran yet.
    const recorded = checkResults.get(gateId);
    const slot = recorded !== undefined ? `<recorded: ${recorded.summary}>` : '<why>';
    const rationale = `${label}${suffix}: ${slot}`.replace(/"/g, '\\"');
    const passed = recorded?.passed ?? true;
    entries.push(`    {"index": ${index}, "passed": ${passed}, "rationale": "${rationale}"}`);
  });

  const perGate = entries.length > 0 ? `,\n  "per_gate": [\n${entries.join(',\n')}\n  ]` : '';
  // One field for every reminder, never one entry each (ruling B4). Pre-listed under
  // `satisfied` because that is the common answer; an id that did not apply moves to
  // `not_applicable` WITH a reason, which the schema requires.
  const reminders =
    reminderIds.length > 0
      ? `,\n  "reminders": {"satisfied": [${reminderIds
          .map((id) => `"${id.replace(/"/g, '\\"')}"`)
          .join(', ')}], "not_applicable": []}`
      : '';
  return `{\n  "overall": "PASS",\n  "rationale": "<overall assessment>"${perGate}${reminders}\n}`;
}

/**
 * Builds a lookup map from gate ID to its review prompt.
 */
function buildPromptLookup(prompts: readonly GateReviewPrompt[]): Map<string, GateReviewPrompt> {
  const map = new Map<string, GateReviewPrompt>();
  for (const prompt of prompts) {
    if (prompt.gateId != null && prompt.gateId.length > 0) {
      map.set(prompt.gateId, prompt);
    }
  }
  return map;
}

/** What an exhausted review accepts, in the words every reply holding one uses. */
const EXHAUSTED_REVIEW_CHOICE =
  'The retry budget is spent. Choose a `gate_action`: `retry`, or `skip` to accept the answer already given, or send `cancel: true`.';

/** The `Next:` line of a reply holding an exhausted review: the only moves it accepts (P6.23). */
function exhaustedReviewMoves(chainId: string): string {
  return `Next: chain_id="${chainId}", gate_action="retry" | gate_action="skip" | cancel: true`;
}
