// @lifecycle canonical - Controls all injection decisions using the modular injection system.
import {
  INJECTION_TYPES,
  InjectionDecisionService,
  type InjectionDecisionInput,
  type InjectionConfig,
  type InjectionType,
  type InjectionRuntimeOverride,
  type PromptInjectionConfig,
  getSessionOverrideResolver,
  isSessionOverrideResolverInitialized,
} from '../decisions/injection/index.js';
import { BasePipelineStage } from '../stage.js';

import type { Logger } from '#infra/logging/index.js';
import type { ExecutionContext } from '../../context/index.js';
import type { ChainStepPrompt } from '../../operators/types.js';

import { parseStepForNode } from '#shared/utils/node-order.js';

type InjectionConfigProvider = () => InjectionConfig;

/** The types a resume decides again for the step it renders (R151); gate guidance is not one. */
const RENDERED_STEP_TYPES: readonly InjectionType[] = ['system-prompt', 'style-guidance'];

/** The run position a decision is computed for: the step the call renders. */
export interface InjectionPosition {
  readonly currentStep: number;
  readonly currentNodeId?: string | null | undefined;
}

/**
 * Pipeline Stage 14: Injection Control
 *
 * Controls when system prompts, gate guidance, and style guidance are injected
 * during prompt and chain execution. Uses a modular design with
 * InjectionDecisionService for hierarchical configuration resolution.
 *
 * Key improvements over the old system:
 * - Clear boolean semantics: inject=true means INJECT, inject=false means SKIP
 * - Hierarchical configuration: Global → Category → Chain → Prompt → Step
 * - Multiple injection types controlled separately
 * - Conditional injection based on gate status, step type, etc.
 * - Runtime overrides via system_control
 *
 * For chains:
 * - Step 1: Default behavior based on config (usually inject)
 * - Step N>1: Inject based on configured frequency
 *
 * For single prompts:
 * - Always inject unless modifiers (%clean, %lean) disable it
 *
 * Dependencies: context.sessionContext.currentStep (from SessionManagementStage)
 * Output: context.state.injection (InjectionState)
 * Can Early Exit: No
 */
export class InjectionControlStage extends BasePipelineStage {
  readonly name = 'InjectionControl';
  readonly provides = ['state.injection'] as const;
  readonly requires = ['sessionContext.currentStep'] as const;

  private injectionService: InjectionDecisionService | null = null;

  constructor(
    private readonly getInjectionConfig: InjectionConfigProvider,
    logger: Logger
  ) {
    super(logger);
  }

  async execute(context: ExecutionContext): Promise<void> {
    this.logEntry(context);

    // NO blueprint-restored skip. The sibling stages that skip on restore cache a one-time
    // resolution the blueprint carries (parsedCommand, executionPlan, gateInstructions); this
    // one decides per step from `sessionContext.currentStep`, and `SessionBlueprint` has no
    // injection field, so skipping left `context.state.injection` undefined on every chain
    // continuation. Its consumers read `?.inject === false` / `?? true`, so undefined means
    // INJECT — the configured frequency (`frameworks.systemPromptFrequency`) and target were
    // silently bypassed for steps 2..N and every gate-review retry.

    const injectionState = this.decideFor(context, {
      currentStep: context.sessionContext?.currentStep ?? 1,
      currentNodeId: context.sessionContext?.currentNodeId,
    });

    this.logExit({
      systemPrompt: injectionState.systemPrompt?.inject,
      gateGuidance: injectionState.gateGuidance?.inject,
      styleGuidance: injectionState.styleGuidance?.inject,
      currentStep: injectionState.currentStep,
      source: {
        systemPrompt: injectionState.systemPrompt?.source,
        gateGuidance: injectionState.gateGuidance?.source,
        styleGuidance: injectionState.styleGuidance?.source,
      },
    });
  }

  /**
   * Decide the system prompt and style again for the step the run stands on after stage 16 moved
   * it (R151); gate guidance keeps the decision taken for the step the call ANSWERED.
   *
   * This stage runs before the capture stage decides whether the call advances, so on an
   * advancing resume it decided for the answered step while the reply renders the next one: a
   * PASS on step 1 rendered step 2 with step 1's frequency verdict. The system prompt and style
   * dress the rendered step, so they follow it. Gate guidance does not: under the shipped
   * first-step-only frequency the answered step's decision is what carries a step's own gate
   * criteria onto the step 2 render, and deciding it for the rendered step would drop them. A
   * call that did not move stands where it was, and deciding again gives the same answer.
   */
  redecideAt(context: ExecutionContext, position: InjectionPosition): void {
    const answeredGateGuidance = context.state.injection.gateGuidance;
    // Gate guidance is not decided again: a decision for the rendered step had no reader (R172).
    const injectionState = this.decideFor(context, position, RENDERED_STEP_TYPES);
    if (answeredGateGuidance !== undefined) {
      injectionState.gateGuidance = answeredGateGuidance;
    }
    this.logger.debug('[InjectionControl] Re-decided for the rendered step', {
      currentStep: injectionState.currentStep,
      systemPrompt: injectionState.systemPrompt?.inject,
      styleGuidance: injectionState.styleGuidance?.inject,
      gateGuidance: injectionState.gateGuidance?.inject,
    });
  }

  /**
   * Decide every injection type for one run position and store it on the context, the
   * authoritative source every downstream stage reads.
   */
  private decideFor(
    context: ExecutionContext,
    position: InjectionPosition,
    types: readonly InjectionType[] = INJECTION_TYPES
  ): ReturnType<InjectionDecisionService['decideAll']> {
    // Create authority if not already created
    if (!this.injectionService) {
      const config = this.getInjectionConfig();
      this.injectionService = new InjectionDecisionService(config, this.logger);
    }

    // Pull active session overrides (if initialized via system_control) and
    // sync them into the decision service so runtime overrides take effect.
    const sessionOverrides = this.getSessionOverrides();
    this.injectionService.syncRuntimeOverrides(sessionOverrides ?? new Map());

    const overrideRecord = this.toSessionOverrideRecord(sessionOverrides);
    const input = this.buildDecisionInput(context, position, types, overrideRecord);
    const injectionState = this.injectionService.decideAll(input, types);

    // Persist active session overrides for downstream diagnostics/status
    if (overrideRecord) {
      injectionState.sessionOverrides = overrideRecord;
    }

    context.state.injection = injectionState;
    return injectionState;
  }

  /**
   * Build the decision input from execution context, for the given run position.
   */
  private buildDecisionInput(
    context: ExecutionContext,
    position: InjectionPosition,
    types: readonly InjectionType[],
    sessionOverrides?: Partial<Record<InjectionType, boolean>>
  ): Omit<InjectionDecisionInput, 'injectionType'> {
    const input: Omit<InjectionDecisionInput, 'injectionType'> = {
      currentStep: position.currentStep,
      executionContext: context.sessionContext?.pendingReview ? 'gate_review' : 'step',
    };

    const totalSteps = context.sessionContext?.totalSteps;
    if (totalSteps !== undefined) {
      input.totalSteps = totalSteps;
    }

    // Read by the gate-guidance decision alone.
    const gatedRenderOrdinal = types.includes('gate-guidance')
      ? this.gatedRenderOrdinal(context, position)
      : undefined;
    if (gatedRenderOrdinal !== undefined) {
      input.gatedRenderOrdinal = gatedRenderOrdinal;
    }

    const gateStatuses = this.buildGateStatusMap(context);
    if (gateStatuses) {
      input.gateStatuses = gateStatuses;
    }

    const categoryId = this.getCategoryId(context);
    if (categoryId) {
      input.categoryId = categoryId;
    }

    const chainId = context.getRequestedChainId();
    if (chainId) {
      input.chainId = chainId;
    }

    const promptId = context.parsedCommand?.promptId;
    if (promptId) {
      input.promptId = promptId;
    }

    const promptInjection = this.getPromptInjection(context, position);
    if (promptInjection !== undefined) {
      input.promptInjection = promptInjection;
    }

    const modifiers = context.executionPlan?.modifiers;
    if (modifiers) {
      input.modifiers = modifiers;
    }

    const stepType = this.getStepType(context, position);
    if (stepType) {
      input.stepType = stepType;
    }

    const previousStepResult = context.sessionContext?.previousStepResult;
    if (previousStepResult) {
      input.previousStepResult = previousStepResult;
    }

    if (sessionOverrides) {
      input.sessionOverrides = sessionOverrides;
    }

    return input;
  }

  /**
   * The gate-guidance frequency's counter for this position (R155): one more than the gated steps
   * before it in the chain walk. The decision taken while answering a step dresses the step the
   * reply renders next (R151), so an ungated step answered before the first gated one decides as
   * the first gated render, and the gated step's own guidance renders whatever came before it.
   * Undefined when no walk ran or the position has no parse-time step (an inserted node).
   */
  private gatedRenderOrdinal(
    context: ExecutionContext,
    position: InjectionPosition
  ): number | undefined {
    const gated = context.state.gates.gatedStepNumbers;
    const step = this.resolveCurrentChainStep(context, position);
    if (gated === undefined || step === undefined) {
      return undefined;
    }
    return gated.filter((stepNumber) => stepNumber < step.stepNumber).length + 1;
  }

  /**
   * Build a map of gate IDs to their current status.
   */
  private buildGateStatusMap(
    context: ExecutionContext
  ): Map<string, 'pass' | 'fail' | 'pending'> | undefined {
    const gateStatuses = new Map<string, 'pass' | 'fail' | 'pending'>();

    // Check accumulated gates for their status
    const accumulatedGateIds = context.state.gates.accumulatedGateIds ?? [];

    if (accumulatedGateIds.length === 0) {
      return undefined;
    }

    // If there's a pending review, those gates are 'pending'
    const pendingReview = context.sessionContext?.pendingReview;
    if (pendingReview) {
      // Gates in pending review are pending
      gateStatuses.set('pending-review', 'pending');
    }

    // For now, mark all accumulated gates as 'pending' until we have results
    // This could be enhanced to track actual pass/fail status per gate
    for (const gateId of accumulatedGateIds) {
      if (!gateStatuses.has(gateId)) {
        gateStatuses.set(gateId, 'pending');
      }
    }

    return gateStatuses.size > 0 ? gateStatuses : undefined;
  }

  /**
   * Get the category ID from the context.
   */
  private getCategoryId(context: ExecutionContext): string | undefined {
    // Try to get from converted prompt
    if (context.parsedCommand?.convertedPrompt?.category) {
      return context.parsedCommand.convertedPrompt.category;
    }

    // Try to get from chain steps
    if (context.hasChainCommand()) {
      const firstStep = context.parsedCommand.steps[0];
      if (firstStep?.convertedPrompt?.category) {
        return firstStep.convertedPrompt.category;
      }
    }

    return undefined;
  }

  /**
   * Get the prompt's own injection block from the context.
   *
   * For a chain, the block is read from the step currently executing rather than the chain's
   * entry prompt: each step is a different prompt, and a step's own declaration is what the
   * prompt tier is meant to express. Mirrors how `getStepType` indexes the step list.
   */
  private getPromptInjection(
    context: ExecutionContext,
    position: InjectionPosition
  ): PromptInjectionConfig | undefined {
    if (context.hasChainCommand()) {
      return this.resolveCurrentChainStep(context, position)?.convertedPrompt?.injection;
    }

    return context.parsedCommand?.convertedPrompt?.injection;
  }

  /**
   * The parse-time step for the node the run is standing at.
   *
   * Resolved by node id first (P4 row 3.4): the ordinal-indexed read this replaced named the
   * wrong step for every node after an adaptive insertion, because the run's ordinal space and
   * the parse-time array stop being the same list once a node is inserted. Positional lookup
   * remains for chains parsed before node ids were minted (P3 D10 keeps `nodeId` optional).
   *
   * Returns undefined for a node with no parse-time counterpart — an INSERTED node. That node
   * declares no prompt-tier injection of its own, and reading a neighbour's block would be a
   * silent misattribution rather than a missing declaration.
   */
  private resolveCurrentChainStep(
    context: ExecutionContext,
    position: InjectionPosition
  ): ChainStepPrompt | undefined {
    return parseStepForNode(
      context.parsedCommand?.steps ?? [],
      position.currentNodeId,
      position.currentStep
    );
  }

  /**
   * Get the step type from the context.
   * Step type can be defined in step metadata.
   */
  private getStepType(context: ExecutionContext, position: InjectionPosition): string | undefined {
    if (!context.hasChainCommand()) {
      return undefined;
    }

    const step = this.resolveCurrentChainStep(context, position);

    // Try to get step type from metadata
    if (step?.metadata?.['stepType']) {
      return String(step.metadata['stepType']);
    }

    return undefined;
  }

  /**
   * Retrieve active session overrides from the SessionOverrideResolver if available.
   */
  private getSessionOverrides(): Map<InjectionType, InjectionRuntimeOverride> | undefined {
    if (!isSessionOverrideResolverInitialized()) {
      return undefined;
    }

    const manager = getSessionOverrideResolver();
    return manager.getAllOverrides();
  }

  /**
   * Convert runtime overrides map to the lightweight record stored on pipeline state.
   */
  private toSessionOverrideRecord(
    overrides?: Map<InjectionType, InjectionRuntimeOverride>
  ): Partial<Record<InjectionType, boolean>> | undefined {
    if (!overrides || overrides.size === 0) {
      return undefined;
    }

    const record: Partial<Record<InjectionType, boolean>> = {};
    for (const [type, override] of overrides) {
      if (override.enabled !== undefined) {
        record[type] = override.enabled;
      }
    }

    return Object.keys(record).length > 0 ? record : undefined;
  }
}
