/**
 * Type guard for gate review input
 */
function isGateReviewInput(input: ChainStepExecutionInput): input is GateReviewInput {
  return input.executionType === 'gate_review';
}

export class ChainOperatorExecutor {
  constructor(
    private readonly logger: Logger,
    private readonly convertedPrompts: ConvertedPrompt[],
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private readonly gateGuidanceRenderer?: any,
    private readonly getFrameworkContext?: (
      promptId: string,
      scope: StateStoreOptions | undefined,
      frameworkId?: string
    ) => Promise<StepFrameworkContext | null>,
    private readonly collaborators?: ChainOperatorCollaborators
  ) {}

  async renderStep(input: ChainStepExecutionInput): Promise<ChainStepRenderResult> {
    const { stepPrompts, chainContext = {}, additionalGateIds = [], inlineGuidanceText } = input;

    if (stepPrompts.length === 0) {
      return {
        stepNumber: 0,
        totalSteps: 0,
        promptId: '',
        promptName: '',
        content: 'No executable steps detected in symbolic chain.',
        callToAction: '',
      };
    }

    // Use discriminated union type guards for variant-specific logic
    if (isGateReviewInput(input)) {
      return this.renderGateReviewStep(
        input,
        stepPrompts,
        chainContext,
        additionalGateIds,
        inlineGuidanceText
      );
    }

    // Normal step execution
    return this.renderNormalStep(input, stepPrompts, chainContext);
  }

  /**
   * Renders a gate review step (synthetic validation step)
   */
  private async renderGateReviewStep(
    input: GateReviewInput,
    stepPrompts: readonly ChainStepPrompt[],
    chainContext: Record<string, unknown>,
    additionalGateIds: readonly string[],
    inlineGuidanceText?: string
  ): Promise<ChainStepRenderResult> {
    const review = describeReviewForRender(input.review);
    const { isRetry } = review;
    const gateGuidanceEnabled = this.isGateGuidanceEnabled(chainContext);
    const frameworkInjectionEnabled = this.isFrameworkInjectionEnabledForGates(chainContext);

    this.logger.debug(`[SymbolicChain] Rendering synthetic gate review step`, {
      gateGuidanceEnabled,
      frameworkInjectionEnabled,
    });
    const totalSteps = stepPrompts.length + 1;
    const stepNumber = totalSteps;
    const reviewStep = this.resolveReviewStep(stepPrompts, chainContext, review);
    const { gateIds: gateIdsToRender, explicitGateIds } = this.collectReviewGateIds(
      review,
      additionalGateIds,
      reviewStep
    );
    const hasInlineGateFocus =
      explicitGateIds.length > 0 ||
      gateIdsToRender.some((gateId) => this.isInlineGateId(gateId)) ||
      Boolean(inlineGuidanceText);
    const callToAction =
      'Use the resume shortcut below and include both your step output and a gate_verdict (e.g., `GATE_REVIEW: PASS - reason`) to resume the workflow.';

    // Get the last actual step that was executed
    const fallbackIndex = stepPrompts.length - 1;
    // By identity: `reviewStep` is an element of `stepPrompts`, never matched back by ordinal.
    const lastStepIndex = reviewStep ? stepPrompts.indexOf(reviewStep) : fallbackIndex;
    const targetStep =
      reviewStep ??
      (lastStepIndex >= 0 ? stepPrompts[lastStepIndex] : (stepPrompts[fallbackIndex] ?? undefined));

    // P5 visibility for the REVIEWED step (Tier 3.1/3.3). A review re-renders that step's own
    // template as "Original Task Instructions", so it must show exactly what the step itself
    // was allowed to see — otherwise the review path becomes a second, unwithheld copy of the
    // context the step was denied. Index tracks `targetStep`: `lastStepIndex` when the review
    // step was resolved, else the fallback (last) index.
    const targetIndex = lastStepIndex >= 0 ? lastStepIndex : fallbackIndex;
    const reviewVisibility = this.resolveStepVisibility(stepPrompts, targetIndex);
    const reviewWithheld = new Set<VisibilityItem>(reviewVisibility.withheld);

    const convertedPrompt =
      targetStep?.convertedPrompt ??
      this.convertedPrompts.find((p) => p.id === targetStep?.promptId);
    const systemMessage = this.reviewSystemMessage(targetStep, chainContext, isRetry);
    const systemMessageLines = (systemMessage ?? '') === '' ? [] : [`> ${systemMessage}`];

    const originalContent = await this.renderReviewedTask({
      targetStep,
      convertedPrompt,
      chainContext,
      stepPrompts,
      targetIndex,
      reviewWithheld,
      isRetry,
      reviewExhausted: input.review.phase === 'exhausted',
    });
    const gateGuidance = await this.renderReviewGateGuidance({
      input,
      targetStep,
      gateGuidanceEnabled,
      gateIdsToRender,
      explicitGateIds,
      inlineGuidanceText,
    });

    // Retry hints, the last review and the retry-limit prompt, read off the review record.
    // Attempt display is handled by ResponseAssembler.buildGateReviewCTA()
    const supplementalSections = renderReviewSupplements(review, hasInlineGateFocus);

    // Framework guidance for the review, whenever the call's decision injects it — retries
    // included (R152): a FAIL re-render is the step's render for this call, and a step carries the
    // same framework block whether it renders normally or as a review. The frequency, not the
    // attempt count, is what spares a later step the block.
    let frameworkGuidance = '';
    if (frameworkInjectionEnabled && targetStep && !hasFrameworkGuidance(systemMessage)) {
      const guidance = await this.buildFrameworkGuidance(targetStep, input);
      if (guidance) {
        frameworkGuidance = guidance;
        this.logger.debug('[SymbolicChain] Added framework guidance to gate review step');
      }
    } else if (!frameworkInjectionEnabled) {
      this.logger.debug(
        '[SymbolicChain] Framework injection suppressed for gate review (target config)'
      );
    }

    // Required Response Format — reuses the same declared-sections contract as
    // renderNormalStep (F5, phase-guard-declaration-contract-2026-08-15). A gated chain step
    // is graded on this render, not on renderNormalStep: 13-session-stage opens the pending
    // gate review upfront and 18-execution-stage skips the normal render entirely for a
    // blocking-gate step, so this was the only chain path that never declared its headers.
    //
    // Declared on retries too, as the framework guidance above is (R152). A retry exists
    // because the model's prior attempt failed a structural check (a declared header was
    // missing or malformed), so retry is exactly the turn where the model most
    // needs the vocabulary restated — omitting it here would tell the step to fix its
    // structure without telling it the structure. `isFinalStep`/`gateGuidanceEnabled` reuse
    // the target step's own coordinates (`targetIndex`) and the chain-wide gate-guidance
    // decision already resolved above, matching renderNormalStep's semantics exactly rather
    // than introducing a second definition of "final".
    const isTargetFinalStep = targetIndex === stepPrompts.length - 1;
    const declaredSections = await this.resolveDeclaredSections(targetStep, input);
    const responseFormatSection = this.buildResponseFormatSection(
      { coverage: gateGuidanceEnabled, verdictLine: isTargetFinalStep },
      declaredSections
    );

    // Assemble in proper order: Framework → Warning → Content → Gates → Metadata → Format
    // Use original task template as the review body. Gate guidance comes from
    // GateGuidanceRenderer (gateGuidance variable) as the single source of truth.
    const reviewPrompt = originalContent;

    // A delegated step under review still has to be HANDED to a worker. The worker-facing half
    // (framework guidance + the step's own task) moves inside the brief; everything below stays
    // outside for the parent, who ratifies the verdict (R-2) — including the review CTA the
    // assembler appends from the pending review itself.
    //
    // Two conditions, both about what the parent can act on rather than about safety. The step
    // under review must be DELEGATED — a normal step's review is the parent's own work and needs
    // no worker. And it must be the FIRST attempt: a retry already abbreviates the task body to
    // "review the original task above", so a brief there would hand a worker a task the retry is
    // not asking anyone to redo. The retry path is left exactly as it was.
    const reviewBriefLines =
      targetStep?.delegated === true && !isRetry
        ? buildDelegatedStepLines({
            step: targetStep,
            totalSteps: stepPrompts.length,
            promptName: this.getPromptDisplayName(targetStep),
            clientProfile: this.extractClientProfile(chainContext),
            historyEntries: this.collectBriefHistory(
              stepPrompts,
              targetIndex,
              chainContext,
              reviewWithheld
            ),
            manifest: reviewVisibility.manifest,
            workerLines: [frameworkGuidance, ...systemMessageLines, reviewPrompt].filter(
              (part) => part.trim().length > 0
            ),
            gateGuidanceEnabled,
          }).lines
        : null;

    const contentParts = [
      ...(reviewBriefLines ?? [frameworkGuidance, ...systemMessageLines, reviewPrompt]),
      gateGuidance,
      supplementalSections.join('\n\n'),
      responseFormatSection,
    ].filter((part) => part && part.trim().length > 0);

    const reviewContent = contentParts.join('\n\n');

    return {
      stepNumber,
      totalSteps,
      promptId: '__gate_review__',
      promptName: 'Quality Gate Validation',
      content: reviewContent,
      callToAction,
      // What this review told the model, for the node it reviewed (P4.115). A gated step's review
      // IS that step's render — stage 18 skips it — so without these the reviewed node recorded no
      // declaration and stage 19 graded it against the run's union instead of its own headers.
      ...(targetStep?.nodeId !== undefined
        ? {
            declaredNodeId: targetStep.nodeId,
            declaredSections: declaredSections.map((section) => section.header),
          }
        : {}),
    };
  }

  /**
   * The step's system message a first-attempt review carries, as the step's normal render does
   * (R180): the review grades work that message shaped. A retry abbreviates the task to "review
   * the original task above" and carries none. A delegated review hands the step's own copy to the
   * worker inside the brief, as its normal delegated render does. Any other review is the parent's,
   * and quotes the AUTHOR's text from the catalog: on a run's first call the step's copy also
   * carries the injected framework guidance, which the review shows in its own framework block.
   */
  private reviewSystemMessage(
    step: ChainStepPrompt | undefined,
    chainContext: Record<string, unknown>,
    isRetry: boolean
  ): string | undefined {
    if (step === undefined || isRetry) return undefined;
    const authored = this.convertedPrompts.find((p) => p.id === step.promptId);
    return step.delegated === true
      ? this.withRenderedStepStyle((step.convertedPrompt ?? authored)?.systemMessage, chainContext)
      : (authored ?? step.convertedPrompt)?.systemMessage;
  }

  /** Re-render the reviewed task under its original visibility; retries quote prior context. */
  private async renderReviewedTask({
    targetStep,
    convertedPrompt,
    chainContext,
    stepPrompts,
    targetIndex,
    reviewWithheld,
    isRetry,
    reviewExhausted,
  }: {
    targetStep: ChainStepPrompt | undefined;
    convertedPrompt: ConvertedPrompt | undefined;
    chainContext: Record<string, unknown>;
    stepPrompts: readonly ChainStepPrompt[];
    targetIndex: number;
    reviewWithheld: ReadonlySet<VisibilityItem>;
    isRetry: boolean;
    reviewExhausted: boolean;
  }): Promise<string> {
    // An exhausted review offers only gate actions; its omitted criteria cannot be reviewed.
    if (isRetry && reviewExhausted) return '';
    if (isRetry) {
      return '## Review Context\n\nReview the original task and your output above against the gate criteria.\n\n---\n';
    }
    // The catalog may have moved after execution; a review still renders without a task quote.
    if (targetStep === undefined || convertedPrompt === undefined) return '';
    const ownArgs =
      (chainContext['currentStepArgs'] as Record<string, unknown> | undefined) ?? targetStep.args;
    const stepArgs = this.normalizeStepArgs(ownArgs ?? {}, convertedPrompt);
    const templateContext: Record<string, unknown> = { ...chainContext, ...stepArgs };
    this.applyWithheldToTemplateContext(templateContext, reviewWithheld, stepPrompts, targetIndex);
    const renderedTemplate = await this.renderTemplateString(
      convertedPrompt.userMessageTemplate,
      templateContext,
      targetStep.promptId,
      convertedPrompt.promptDir
    );
    const intent = this.buildOriginalIntentSection(chainContext, ownArgs);
    const unknowns = reviewWithheld.has('unknowns_ledger')
      ? null
      : this.buildUnknownsSection(chainContext);
    return [
      '## Original Task Instructions',
      '',
      ...(intent === null ? [] : [intent, '']),
      ...(unknowns === null ? [] : [unknowns, '']),
      renderedTemplate,
      '',
      '---',
      '',
    ].join('\n');
  }

  /** Render only guidance the review can act on, using the existing gate renderer/fallback. */
  private async renderReviewGateGuidance({
    input,
    targetStep,
    gateGuidanceEnabled,
    gateIdsToRender,
    explicitGateIds,
    inlineGuidanceText,
  }: {
    input: GateReviewInput;
    targetStep: ChainStepPrompt | undefined;
    gateGuidanceEnabled: boolean;
    gateIdsToRender: readonly string[];
    explicitGateIds: readonly string[];
    inlineGuidanceText: string | undefined;
  }): Promise<string> {
    if (input.review.phase === 'exhausted') {
      this.logger.debug('[SymbolicChain] Gate guidance withheld: the review is exhausted');
      return '';
    }
    if (!gateGuidanceEnabled) {
      this.logger.debug('[SymbolicChain] Gate guidance injection suppressed by decision');
      return '';
    }
    if (gateIdsToRender.length === 0) {
      return (inlineGuidanceText ?? '').length === 0
        ? ''
        : this.renderSimpleGateGuidance([], inlineGuidanceText);
    }
    const reviewStepContext = await this.resolveFrameworkContext(targetStep, input);
    if (this.gateGuidanceRenderer == null) {
      return this.renderSimpleGateGuidance(gateIdsToRender, inlineGuidanceText);
    }
    try {
      const guidance: string = await this.gateGuidanceRenderer.renderGuidance(gateIdsToRender, {
        criteriaExecution: 'pipeline',
        framework: reviewStepContext?.selectedFramework?.type || DEFAULT_FRAMEWORK_ID,
        category: reviewStepContext?.category || 'general',
        promptId: targetStep?.promptId,
        explicitGateIds,
      });
      return guidance;
    } catch (error) {
      this.logger.warn('[SymbolicChain] Gate guidance rendering failed, using fallback:', error);
      return this.renderSimpleGateGuidance(gateIdsToRender, inlineGuidanceText);
    }
  }

  /**
   * Renders a normal step (non-review execution)
   */
  private async renderNormalStep(
    input: NormalStepInput,
    stepPrompts: readonly ChainStepPrompt[],
    chainContext: Record<string, unknown>
  ): Promise<ChainStepRenderResult> {
    const { currentStepIndex } = input;

    if (currentStepIndex < 0 || currentStepIndex >= stepPrompts.length) {
      throw new Error(
        `Invalid step index ${currentStepIndex} for chain of length ${stepPrompts.length}`
      );
    }

    const step = stepPrompts[currentStepIndex];
    if (!step) {
      throw new Error(
        `Step at index ${currentStepIndex} is undefined in chain of length ${stepPrompts.length}`
      );
    }
    this.logger.debug(`[SymbolicChain] Rendering step ${step.stepNumber}: ${step.promptId}`);

    // Look up convertedPrompt if not already set on the step
    const convertedPrompt =
      step.convertedPrompt || this.convertedPrompts.find((p) => p.id === step.promptId);

    if (!convertedPrompt) {
      // The fifth site of the assert the other four already make (execution-planner.ts,
      // symbolic-command-builder.ts x2, 04-parsing-stage.ts). It used to warn and render
      // `Execute the prompt "<id>"` with `Complete this step manually`: a step that cannot run,
      // reported as a step, in a run whose footer still counts it as progress. Reachable — a
      // synthesized node (`node-step-projection.synthesizeStep`) carries no `convertedPrompt`,
      // so a run resumed after a reload that removed the prompt lands exactly here.
      throw new PromptError(`Converted prompt data not found for chain step: ${step.promptId}`);
    }

    const promptName = convertedPrompt.name || step.promptId;

    // Prioritize currentStepArgs from chainContext (pipeline integration)
    // Fall back to step-level args captured during parsing
    const ownArgs =
      (chainContext['currentStepArgs'] as Record<string, unknown> | undefined) ?? step?.args;
    const stepArgs = this.normalizeStepArgs(ownArgs ?? {}, convertedPrompt);

    const templateContext: Record<string, unknown> = {
      ...chainContext,
      ...stepArgs,
    };

    // P5 visibility (Tier 3.1/3.3). Resolved once and applied to every context surface this
    // render produces: the template context below, the unknowns section, and the delegation
    // envelope for the next step. Empty when no step in the chain declares `visibility`.
    const visibility = this.resolveStepVisibility(stepPrompts, currentStepIndex);
    const withheld = new Set<VisibilityItem>(visibility.withheld);

    // Stripped BEFORE inputMapping: a mapping like `{ research: 'step1_result' }` — or
    // `{ research: 'outputs' }` — would otherwise re-publish a withheld history entry under a
    // name the filter never sees. inputMapping stays FLAT and is not namespaced: it renames
    // into this step's own context, which is the step's own business, whereas `outputMapping`
    // publishes chain-wide and is what the namespace exists to fence.
    if (withheld.has('chain_history')) {
      this.stripChainHistory(templateContext);
    }

    // Apply inputMapping to create semantic variable names
    // e.g., { "research": "step1_result" } allows template to use {{research}} instead of {{step1_result}}
    if (step.inputMapping) {
      for (const [semanticName, sourceVar] of Object.entries(step.inputMapping)) {
        if (templateContext[sourceVar] !== undefined) {
          templateContext[semanticName] = templateContext[sourceVar];
          this.logger.debug(
            `[SymbolicChain] Applied inputMapping: ${semanticName} <- ${sourceVar}`
          );
        }
      }
    }

    const totalSteps = stepPrompts.length;
    const previousStepIndex = currentStepIndex - 1;

    if (currentStepIndex === 0) {
      templateContext['previous_step_output'] =
        '**[CONTEXT INSTRUCTION]**: This is the first step. Begin the workflow here.';
      templateContext['previous_step_result'] = templateContext['previous_step_output'];
    } else if (withheld.has('previous_step_output')) {
      // A prior step withheld its output from this one. The stored result is never read, so it
      // never enters the template context — this is the withhold, not a formatting choice.
      const instruction = this.buildWithheldOutputInstruction(stepPrompts, currentStepIndex);
      templateContext['previous_step_output'] = instruction;
      templateContext['previous_step_result'] = instruction;
    } else {
      const previousStep = stepPrompts[previousStepIndex];
      const storedOutput = previousStep
        ? this.getStoredStepResult(chainContext, previousStep.stepNumber)
        : undefined;

      if (storedOutput) {
        templateContext['previous_step_output'] = storedOutput;
        templateContext['previous_step_result'] = storedOutput;
      } else {
        const previousName = previousStep
          ? this.getPromptDisplayName(previousStep)
          : `Step ${currentStepIndex}`;
        const instruction = `**[CONTEXT INSTRUCTION]**: Use the response you produced for Step ${currentStepIndex} (${previousName}) wherever {{previous_step_output}} is referenced.`;
        templateContext['previous_step_output'] = instruction;
        templateContext['previous_step_result'] = instruction;
      }
    }

    const renderedTemplate = await this.renderTemplateString(
      convertedPrompt.userMessageTemplate,
      templateContext,
      step.promptId,
      convertedPrompt.promptDir
    );

    const lines: string[] = [];
    const stepNumber = currentStepIndex + 1;
    const isFinalStep = currentStepIndex === totalSteps - 1;

    // Original Request Intent — provides delivery context for every chain step
    const intentSection = this.buildOriginalIntentSection(chainContext, ownArgs);
    if (intentSection) {
      lines.push(intentSection);
    }

    // Unknowns Ledger — surfaces run-scoped unknowns declared by prior steps.
    // Suppressed entirely when a prior step withheld `unknowns_ledger` (Tier 3.3): the section
    // is not summarised or redacted, it is absent, which is what "withheld" means here.
    const unknownsSection = withheld.has('unknowns_ledger')
      ? null
      : this.buildUnknownsSection(chainContext);
    if (unknownsSection) {
      lines.push(unknownsSection);
    }

    // Use target-aware helper to determine if framework should be suppressed on steps
    const suppressFrameworkInjection = this.shouldSuppressFrameworkForSteps(chainContext);
    const gateGuidanceEnabled = this.isGateGuidanceEnabled(chainContext);

    if (!suppressFrameworkInjection && !hasFrameworkGuidance(convertedPrompt?.systemMessage)) {
      const frameworkGuidance = await this.buildFrameworkGuidance(step, input);
      if (frameworkGuidance) {
        lines.push(frameworkGuidance);
      }
    }

    const systemMessage = this.withRenderedStepStyle(convertedPrompt?.systemMessage, chainContext);
    if (systemMessage !== undefined && systemMessage !== '') {
      lines.push(`> ${systemMessage}`);
    }

    lines.push(renderedTemplate.trim());

    // A gated step's render names the gates it grades and asks for its verdict, every time
    // (R171): gate enhancement wrote those gates' instructions on the step, and the gate-guidance
    // frequency never thins them, because this render asks for the verdict they grade. Skipped
    // for a delegated CURRENT step: the brief owns the gate text there, under the
    // `### Quality Gates` heading the hook contract requires (S2/S4) — pushing it here too
    // would duplicate it inside the brief body.
    const stepGateInstructions =
      typeof step.metadata?.['gateInstructions'] === 'string'
        ? step.metadata['gateInstructions']
        : '';
    const asksVerdict = stepGateInstructions.trim() !== '';
    if (asksVerdict && step.delegated !== true) {
      lines.push(stepGateInstructions);
    }

    // R-1: a CURRENT delegated step renders as a self-contained EXECUTION BRIEF — everything a
    // spawned executor needs, in THIS response — followed by handoff instructions pointing at
    // it. Worker-facing lines built so far move INSIDE the brief; parent-facing sections
    // (Required Response Format, footer) stay outside, because the parent ratifies and submits
    // the gate verdict (R-2) — the worker only proposes.
    const isCurrentDelegated = step.delegated === true;
    let briefHasGates = false;
    if (isCurrentDelegated) {
      const brief = buildDelegatedStepLines({
        step,
        totalSteps,
        promptName: this.getPromptDisplayName(step),
        clientProfile: this.extractClientProfile(chainContext),
        historyEntries: this.collectBriefHistory(
          stepPrompts,
          currentStepIndex,
          chainContext,
          withheld
        ),
        manifest: visibility.manifest,
        workerLines: lines.splice(0, lines.length),
        gateGuidanceEnabled,
      });
      briefHasGates = brief.hasGates;
      lines.push(...brief.lines);
    }

    // Required Response Format — guides structured output for delivery verification.
    // The declared section headers follow this step's OWN framework declaration (R85): a step
    // that declined the framework declares nothing, and stage 19 grades it against nothing,
    // because the record it reads is what this render wrote. Declaring them anyway — which is
    // what this did until P4.111 — handed an opted-out step a contract from a framework it never
    // saw, and the run-wide header set then blocked it on its siblings' vocabulary. Suppression
    // by FREQUENCY is a different question and deliberately does not withhold them: the step was
    // given the framework, just not a second copy of its system prompt.
    const declaredSections = await this.resolveDeclaredSections(step, input);
    lines.push(
      this.buildResponseFormatSection(
        { coverage: asksVerdict, verdictLine: asksVerdict },
        declaredSections
      )
    );

    // NEXT-step delegation gets a one-line ADVISORY, never a full handoff (S7): the old full CTA
    // here described step N+1 while "Pass ALL content above" pointed at step N's content — an
    // obedient parent handed the sub-agent the wrong step's prompt. The authoritative handoff
    // renders WITH step N+1's own brief, one resume later.
    const nextStep = !isFinalStep ? stepPrompts[currentStepIndex + 1] : undefined;
    const callToAction = isCurrentDelegated
      ? buildDelegatedStepCallToAction(step, briefHasGates)
      : nextStep?.delegated === true
        ? this.buildDelegationCTA(
            stepPrompts,
            currentStepIndex + 1,
            gateGuidanceEnabled,
            chainContext
          )
        : !isFinalStep
          ? `Use the resume shortcut below and include your step output in user_response${
              asksVerdict ? ' and your gate_verdict' : ''
            } so Step ${stepNumber + 1} can begin.`
          : 'Deliver the final response to the user (no user_response needed once the chain completes).';

    const content = lines.filter(Boolean).join('\n\n').trimEnd();

    return {
      stepNumber,
      totalSteps,
      promptId: step.promptId,
      promptName,
      content,
      callToAction,
      nextStepDelegated: nextStep?.delegated === true || undefined,
      ...(isCurrentDelegated ? { currentStepDelegated: true } : {}),
      ...(asksVerdict ? { asksVerdict: true } : {}),
      // What this render actually told the model. Reported rather than re-derived: the
      // verification stage may only block on a header the prompt named, and asking phases.yaml
      // after the fact cannot answer that — it is the same source the guard already reads.
      //
      // Reported even when EMPTY, since P4.111. "This render declared nothing" and "no render
      // recorded anything" are different facts and the guard acts on them differently: the first
      // is a step that declined the framework and must be graded against nothing, the second is a
      // node whose declaration was never written and which still falls back to the run's. An
      // omitted key spells both, which is why the opt-out could not be told from a gap.
      declaredSections: declaredSections.map((section) => section.header),
    };
  }

  private renderSimpleGateGuidance(
    gateIds: readonly string[],
    inlineGuidanceText?: string
  ): string {
    const inlineGateIds = gateIds.filter((gateId) => this.isInlineGateId(gateId));
    const frameworkGateIds = gateIds.filter((gateId) => !this.isInlineGateId(gateId));
    const hasInlineGuidance =
      inlineGateIds.length > 0 ||
      Boolean(inlineGuidanceText && inlineGuidanceText.trim().length > 0);
    const filteredFrameworkGateIds = hasInlineGuidance
      ? frameworkGateIds.filter((id) => id === 'framework-compliance')
      : frameworkGateIds;
    const sections: string[] = ['\n\n---\n\n##  Quality Enhancement Gates'];

    if (inlineGateIds.length > 0 || (inlineGuidanceText && inlineGuidanceText.trim().length > 0)) {
      sections.push('\n\n###  Inline Gates (PRIMARY)\n');
      if (inlineGuidanceText && inlineGuidanceText.trim().length > 0) {
        sections.push(inlineGuidanceText.trim());
      }
      if (inlineGateIds.length > 0) {
        sections.push('\n\n' + inlineGateIds.map((id) => `- ${id}`).join('\n'));
      }
    }

    if (filteredFrameworkGateIds.length > 0) {
      sections.push('\n\n---\n\n###  Framework Standards');
      sections.push('\n\n' + filteredFrameworkGateIds.map((id) => `- ${id}`).join('\n'));
    }

    sections.push('\n\n' + GATE_ATTESTATION_LINE);
    sections.push('---');

    return sections.join('');
  }

  /**
   * Determine whether gate guidance injection is enabled for the current chain context.
   */
  private isGateGuidanceEnabled(chainContext: Record<string, unknown>): boolean {
    const injectionState = chainContext['injectionState'] as
      { gateGuidance?: { inject?: boolean } } | undefined;

    return injectionState?.gateGuidance?.inject !== false;
  }

  /**
   * The step's system message with the run's selected style guidance appended when the RENDERED
   * step's style decision says inject (R162 amended) — read here, where the system prompt's
   * decision is read, because on a resume that decision exists only after stage 16 moved the
   * run. A first call's prompts already carry the line (stage 15), which appends nothing twice.
   */
  private withRenderedStepStyle(
    systemMessage: string | undefined,
    chainContext: Record<string, unknown>
  ): string | undefined {
    const styleGuidance = chainContext['selectedStyleGuidance'];
    const injectionState = chainContext['injectionState'] as InjectionState | undefined;
    if (typeof styleGuidance !== 'string' || injectionState?.styleGuidance?.inject !== true) {
      return systemMessage;
    }
    return withResponseStyle(systemMessage, styleGuidance);
  }

  /**
   * Determine whether framework injection is enabled for a gate review render.
   *
   * Reads the recorded decision's `inject` only. The decision service already matched the target
   * against the call's execution context, and under R63 a review render of a step is a step render
   * for the target, so `'steps'` includes it; re-checking the target here would hide the block on
   * a decision that said inject.
   */
  private isFrameworkInjectionEnabledForGates(chainContext: Record<string, unknown>): boolean {
    const injectionState = chainContext['injectionState'] as InjectionState | undefined;
    const decision = injectionState?.systemPrompt;
    return decision === undefined || decision.inject;
  }

  /**
   * Determine whether framework injection should be suppressed for normal steps.
   * Returns true if injection should be skipped (target is 'gates' only).
   */
  private shouldSuppressFrameworkForSteps(chainContext: Record<string, unknown>): boolean {
    const injectionState = chainContext['injectionState'] as InjectionState | undefined;
    if (!injectionState?.systemPrompt) {
      return false; // Default to not suppressing
    }

    const decision = injectionState.systemPrompt;
    if (!decision.inject) {
      return true; // Explicitly disabled
    }

    // Check target - 'gates' only means suppress on steps
    const target = decision.target ?? 'both';
    return target === 'gates';
  }

  private async buildFrameworkGuidance(
    step: ChainStepPrompt,
    input: ChainStepExecutionInput
  ): Promise<string | null> {
    const context = await this.resolveFrameworkContext(step, input);
    const systemPrompt = context?.systemPrompt?.trim();
    const frameworkName = context?.selectedFramework?.name?.trim();

    if (!systemPrompt || !frameworkName) {
      return null;
    }

    // Framework display names are inconsistent about the word: "C.A.G.E.E.R.F Framework" and
    // "SCAMPER Framework" carry it, "LIQUESCENT Creative Flow" does not. Appending it
    // unconditionally reads "… Framework Framework Active"; the previous literal hardcoded that
    // doubling with no name at all.
    const heading = /\bframeworks?\b/i.test(frameworkName)
      ? `## 🎯 ${frameworkName} Active`
      : `## 🎯 ${frameworkName} Framework Active`;

    return ['---', '', heading, '', `**${frameworkName}**`, '', systemPrompt, '', '---', ''].join(
      '\n'
    );
  }

  /**
   * Declared phase-guard headers for the framework active on this step, or `[]` when the
   * framework system prompt is not injected for this render, no provider is wired, no framework
   * resolves, or the framework declares no guards. Reads through on every call — no cache — so
   * framework hot-reload keeps working.
   *
   * The opt-out test is `isFrameworkInjected` over THIS step's own modifiers and `injection`
   * block — the same predicate `GateEnhancementService` already runs for the same step to decide
   * whether that step's framework GATES apply, so a step's gates and its section vocabulary now
   * answer to one declaration instead of two.
   *
   * Deliberately NOT the recorded `injectionState.systemPrompt.inject`: measured on this tree,
   * that flag is already `false` on a chain's later steps for reasons that are not an opt-out
   * (global-config frequency), so reading it withheld the headers from every step past the first,
   * opted out or not — verified by the positive control in the drive. It answers "is the system
   * prompt being emitted on THIS turn", not "did this prompt decline the framework".
   *
   * A step that declined the framework is not shown its system prompt, so declaring its section
   * vocabulary would hand the model a contract from a framework it was never given; stage 19 then
   * reads the same absence back (nothing recorded for that node) and grades it against nothing.
   * Emission and grading follow one declaration (P4.111 / R85).
   */
  private async resolveDeclaredSections(
    step: ChainStepPrompt | undefined,
    input: ChainStepExecutionInput
  ): Promise<DeclaredSection[]> {
    const provider = this.collaborators?.declaredSectionsProvider;
    // A step a remainder contributed has no plan and may have no converted prompt of its own (it
    // is built from its node): it reads the run's modifiers and its prompt from the catalog, as a
    // planned step reads both from itself (R79).
    const contributed = step?.contributed === true;
    const prompt =
      step?.convertedPrompt ??
      (contributed ? this.convertedPrompts.find((p) => p.id === step.promptId) : undefined);
    const modifiers = contributed ? input.runModifiers : step?.executionPlan?.modifiers;
    // Two opt-outs, one answer: the step declined the framework itself, or its prompt turned the
    // framework's gates off (R22) — the sections are graded, so they are a gate.
    const declinesFramework =
      !isFrameworkInjected({ modifiers, promptInjection: prompt?.injection }) ||
      !declaresFrameworkSections(prompt);
    if (!provider || declinesFramework) {
      return [];
    }

    // `.id`, not `.type` — `getFrameworkGuide` lowercases its argument, so `type` happens to
    // resolve for CAGEERF ('CAGEERF' → 'cageerf') but would silently miss any framework whose
    // discriminator is not its lowercased id. `19-phase-guard-verification-stage` resolves on
    // `.id` for the same reason, and the two must agree or the declaration names other headers
    // than the guard grades.
    //
    // A contributed step carries no framework context, so it resolves its framework as its
    // framework GUIDANCE does (`resolveFrameworkContext`: the run's framework decision): a step
    // shown a framework's guidance is declared that framework's sections, and the phase guard
    // binds it as it binds a planned step (R79, R88). Reading the step's own context alone
    // declared nothing for it.
    const frameworkContext = contributed
      ? await this.resolveFrameworkContext(step, input)
      : step?.frameworkContext;
    const frameworkId = frameworkContext?.selectedFramework?.id ?? '';
    if (frameworkId === '') {
      this.logger.debug('[SymbolicChain] No resolved framework id — declaring no sections', {
        promptId: step?.promptId,
      });
      return [];
    }

    return provider(frameworkId);
  }

  /**
   * The framework a step renders under: its own resolved context, else the fallback resolver's.
   *
   * A contributed step asks the fallback for the RUN's framework decision (`runFrameworkId`), the
   * one stage 19 grades it on (R88): resolving the active framework instead showed a step under
   * an operator override one framework's headers and graded it on another's phases, so nothing
   * blocked. An inserted step asks for it too (R92): under an override it was shown the ACTIVE
   * framework's guidance in a run deciding another. With no run decision the fallback resolves the
   * active framework, as before.
   */
  private async resolveFrameworkContext(
    step: ChainStepPrompt | undefined,
    input: ChainStepExecutionInput
  ): Promise<StepFrameworkContext | null> {
    if (!step) {
      return null;
    }

    if (step.frameworkContext) {
      const category = step.convertedPrompt?.category;
      return {
        selectedFramework: step.frameworkContext.selectedFramework,
        ...(category !== undefined && { category }),
        systemPrompt: step.frameworkContext.systemPrompt,
      };
    }

    if (!this.getFrameworkContext) {
      return null;
    }

    try {
      const addedMidRun = step.contributed === true || step.inserted === true;
      const runFrameworkId = addedMidRun ? input.runFrameworkId : undefined;
      return await this.getFrameworkContext(step.promptId, input.scope, runFrameworkId);
    } catch (error) {
      this.logger.debug('[ChainOperatorExecutor] Failed to resolve framework context', {
        promptId: step.promptId,
        error,
      });
      return null;
    }
  }

  /**
   * Assemble the worker-facing EXECUTION BRIEF body for a delegated CURRENT step (R-1).
   * `workerLines` are the already-rendered inline sections (intent, unknowns, framework,
   * system message, template with prior output substituted per visibility). History (S1) and
   * per-step gate text (S4) are appended here; the result contract (R-2) closes the brief.
   */
  /**
   * Visibility-admitted prior outputs for a delegated step's brief (S1): steps BEFORE the
   * previous one — the previous step's output already reaches the worker via
   * `{{previous_step_output}}` in the template. Withheld history returns empty, not a summary
   * (P5 semantics); the brief's manifest line names what was withheld.
   */
  private collectBriefHistory(
    stepPrompts: readonly ChainStepPrompt[],
    currentStepIndex: number,
    chainContext: Record<string, unknown>,
    withheld: ReadonlySet<VisibilityItem>
  ): BriefHistoryEntry[] {
    if (withheld.has('chain_history')) {
      return [];
    }
    const entries: BriefHistoryEntry[] = [];
    for (let i = 0; i < currentStepIndex - 1; i++) {
      const prior = stepPrompts[i];
      if (prior === undefined) continue;
      const output = this.getStoredStepResult(chainContext, prior.stepNumber);
      if (output !== undefined && output.length > 0) {
        entries.push({
          stepNumber: prior.stepNumber,
          stepName: this.getPromptDisplayName(prior),
          output,
        });
      }
    }
    return entries;
  }

  /**
   * Build the NEXT-step delegation advisory using the existing DelegationRenderer
   * infrastructure. Emits a one-line preview (S7) — the full handoff is phase-shifted here: it
   * would describe step N+1 while "Pass ALL content above" points at step N's content. The
   * authoritative handoff renders one resume later, with the delegated step's own brief
   * (`buildCurrentStepHandoff`).
   *
   * Takes the whole `stepPrompts` array plus the delegated step's index rather than the step
   * alone: the payload's `promptName`/`stepNumber` describe the step being HANDED OFF, which is
   * a decision over that step's identity, not over the step currently rendering.
   */
  private buildDelegationCTA(
    stepPrompts: readonly ChainStepPrompt[],
    nextStepIndex: number,
    gateGuidanceEnabled: boolean,
    chainContext: Record<string, unknown>
  ): string {
    const nextStep = stepPrompts[nextStepIndex];
    if (nextStep === undefined) {
      return '';
    }
    const totalSteps = stepPrompts.length;
    const agentType = nextStep.agentType ?? nextStep.convertedPrompt?.agentType;
    const subagentModel = nextStep.subagentModel ?? nextStep.convertedPrompt?.subagentModel;
    const clientProfile = this.extractClientProfile(chainContext);

    const payload: DelegationPayload = {
      stepNumber: nextStep.stepNumber,
      totalSteps,
      promptName: this.getPromptDisplayName(nextStep),
      ...(agentType != null ? { agentType } : {}),
      ...(clientProfile != null ? { clientProfile } : {}),
      ...(subagentModel != null ? { subagentModel } : {}),
      gateCount: 0,
      hasGates: gateGuidanceEnabled,
      nodeToken: handoffNodeToken(nextStep),
      mode: 'blocking',
    };

    return new DelegationRenderer().renderNextStepAdvisory(payload);
  }

  private extractClientProfile(
    chainContext: Record<string, unknown>
  ): RequestClientProfile | undefined {
    const fromIdentityContext = this.asRequestClientProfile(
      (
        chainContext['requestIdentityContext'] as
          { clientProfile?: RequestClientProfile } | undefined
      )?.clientProfile ??
        (
          chainContext['requestIdentityContext'] as
            { identity?: { clientProfile?: RequestClientProfile } } | undefined
        )?.identity?.clientProfile
    );
    if (fromIdentityContext != null) {
      return fromIdentityContext;
    }

    return this.asRequestClientProfile(chainContext['clientProfile']);
  }

  private asRequestClientProfile(value: unknown): RequestClientProfile | undefined {
    if (value == null || typeof value !== 'object' || Array.isArray(value)) {
      return undefined;
    }
    const candidate = value as Partial<RequestClientProfile>;
    if (
      typeof candidate.clientFamily !== 'string' ||
      typeof candidate.clientId !== 'string' ||
      typeof candidate.clientVersion !== 'string' ||
      typeof candidate.delegationProfile !== 'string'
    ) {
      return undefined;
    }
    return {
      clientFamily: candidate.clientFamily,
      clientId: candidate.clientId,
      clientVersion: candidate.clientVersion,
      delegationProfile: candidate.delegationProfile,
    };
  }

  /**
   * Resolve the P5 visibility decision for the step at `stepIndex`.
   *
   * The projection this builds is the whole of Tier 3's contract with the policy: prior
   * declarations are the steps BEFORE `stepIndex` in run order (their `withhold` reaches this
   * step), and `step` is the step itself (only its `expose` is read — its own `withhold` is
   * about LATER steps and must never reach its own call). `decideVisibility` trusts the slice
   * and does not re-derive order, so the slice is computed here and nowhere else.
   *
   * `stepPrompts` is the node-driven render plan (`planNodeDrivenRender().steps`), not the
   * parse-time array, so an inserted node (P4) counts as a prior step exactly as a planned one
   * does. An inserted node carries no `visibility` of its own, which reads as "declares
   * nothing" — correct: a mutation-inserted step never withheld anything.
   */
  private resolveStepVisibility(
    stepPrompts: readonly ChainStepPrompt[],
    stepIndex: number
  ): VisibilityDecision {
    const current = stepPrompts[stepIndex];
    return decideVisibility({
      step: current?.visibility != null ? { visibility: current.visibility } : {},
      priorDeclarations: stepPrompts
        .slice(0, Math.max(stepIndex, 0))
        .map((step) => (step.visibility != null ? { visibility: step.visibility } : {})),
    });
  }

  /**
   * Remove the accumulated chain-history surface from a render context.
   *
   * These are the keys `TextReferenceStore.buildChainVariables` and
   * `ChainSessionStore.getChainContext` publish for PRIOR steps' results. Deliberately NOT
   * including `previous_step_output` / `previous_step_result`: those are a separate
   * {@link VisibilityItem}, and a step that withholds history while leaving the immediately
   * preceding output in place is a declaration the vocabulary is designed to allow.
   *
   * Named outputs (`outputMapping`) go with the history, because they ARE the history: a named
   * output is a prior step's whole content under an author-chosen name. They used to be spread
   * flat and so could not be told apart from an ordinary argument — the P5-F2 leak. Publishing
   * them under the reserved {@link NAMED_OUTPUT_NAMESPACE} object makes the withhold one delete.
   *
   * Withheld with `chain_history` and NOT with `previous_step_output`, deliberately: a named
   * output is the same content `step{N}_result` publishes positionally, and `previous_step_output`
   * leaves `step{N}_result` in place by design (see the paragraph above). Stripping the named
   * view while the positional view of identical bytes survives would be a stricter rule for the
   * alias than for the thing it aliases — a withhold that depends on which name the author chose.
   */
  private stripChainHistory(templateContext: Record<string, unknown>): void {
    delete templateContext['step_results'];
    delete templateContext['previous_step_results'];
    delete templateContext[NAMED_OUTPUT_NAMESPACE];
    for (const key of Object.keys(templateContext)) {
      if (/^step\d+_result$/.test(key)) {
        delete templateContext[key];
      }
    }
  }

  /**
   * Neutral stand-in for a withheld previous-step output, mirroring the voice of the
   * `**[CONTEXT INSTRUCTION]**` fallback used when the output exists but was not stored.
   * The step is told the output is missing and why — silence would leave the template's
   * `{{previous_step_output}}` rendering as an empty string with no way to tell the two apart.
   */
  private buildWithheldOutputInstruction(
    stepPrompts: readonly ChainStepPrompt[],
    stepIndex: number
  ): string {
    const previousStep = stepPrompts[stepIndex - 1];
    const label = previousStep === undefined ? '' : ` (${this.getPromptDisplayName(previousStep)})`;
    return `**[CONTEXT WITHHELD]**: Step ${stepIndex}${label}'s output was withheld by its visibility declaration. Proceed without it.`;
  }

  /**
   * Apply a withheld set to a render context: strip chain history, and replace any
   * previous-step output already present with the neutral instruction.
   *
   * Used by the gate-review path, where the context is `{...chainContext, ...stepArgs}` and the
   * previous output arrives pre-seeded from `getChainContext` rather than being assigned by an
   * explicit branch as it is on the normal step path.
   */
  private applyWithheldToTemplateContext(
    templateContext: Record<string, unknown>,
    withheld: ReadonlySet<VisibilityItem>,
    stepPrompts: readonly ChainStepPrompt[],
    stepIndex: number
  ): void {
    if (withheld.has('chain_history')) {
      this.stripChainHistory(templateContext);
    }
    // `stepIndex > 0` cannot be false in practice — an item is only withheld when a PRIOR step
    // declared it, which requires at least one — but the instruction text names the preceding
    // ordinal, so it is guarded rather than allowed to render "Step 0".
    if (withheld.has('previous_step_output') && stepIndex > 0) {
      const instruction = this.buildWithheldOutputInstruction(stepPrompts, stepIndex);
      templateContext['previous_step_output'] = instruction;
      templateContext['previous_step_result'] = instruction;
    }
  }

  /**
   * Build the Original Request Intent section: the request this step must satisfy.
   *
   * A node's OWN args win (P6.41). The run's `original_args` are its invocation args, which a
   * compiled workflow or a `-->`/`==>` chain takes from its FIRST node, so reading them alone gave
   * every delegated brief row 1's request. They remain the fallback for a node declaring no args
   * of its own. Raw args, not `normalizeStepArgs` output: a prompt's defaults were not requested.
   */
  private buildOriginalIntentSection(
    chainContext: Record<string, unknown>,
    nodeArgs: Record<string, unknown> | undefined
  ): string | null {
    const ownRequest = nodeArgs !== undefined && Object.keys(nodeArgs).length > 0;
    const requestArgs = ownRequest
      ? nodeArgs
      : (chainContext['original_args'] as Record<string, unknown> | undefined);
    if (!requestArgs || Object.keys(requestArgs).length === 0) {
      return null;
    }

    const lines: string[] = [
      '### Original Request Intent',
      '',
      ownRequest
        ? 'This step was given the following request. Your work must satisfy this intent:'
        : 'This chain was initiated with the following request. Your work must satisfy this intent:',
      '',
    ];

    for (const [key, value] of Object.entries(requestArgs)) {
      const truncated =
        String(value).length > 200 ? String(value).substring(0, 200) + '...' : String(value);
      lines.push(`- **${key}**: ${truncated}`);
    }

    return lines.join('\n');
  }

  /**
   * Build Unknowns Ledger section from chainContext unknowns_ledger.
   * Surfaces run-scoped unknowns declared via the `observations` parameter so each
   * step sees what remains open. Absent entirely when the ledger is missing or empty —
   * `getChainContext` only sets `unknowns_ledger` on the context while non-empty.
   */
  private buildUnknownsSection(chainContext: Record<string, unknown>): string | null {
    const ledger = chainContext['unknowns_ledger'] as UnknownLedgerEntry[] | undefined;
    if (!ledger || ledger.length === 0) {
      return null;
    }

    const blocking = ledger.filter((entry) => entry.state === 'active' && entry.blocking);
    const active = ledger.filter((entry) => entry.state === 'active' && !entry.blocking);
    const resolved = ledger.filter((entry) => entry.state === 'resolved');

    const lines: string[] = [
      '### Unknowns Ledger',
      '',
      'Unknowns declared so far in this run. Resolve blocking unknowns before proceeding where possible:',
      '',
    ];

    for (const entry of [...blocking, ...active]) {
      const flag = entry.blocking ? ' **[BLOCKING]**' : '';
      lines.push(`- **${entry.id}**${flag}: ${this.truncateForLedger(entry.statement)}`);
    }

    for (const entry of resolved) {
      const resolution = entry.resolution ?? 'resolved';
      const resolutionText = entry.resolutionStatement ?? entry.statement;
      lines.push(`- ~~${entry.id}~~ (${resolution}): ${this.truncateForLedger(resolutionText)}`);
    }

    return lines.join('\n');
  }

  /** Matches buildOriginalIntentSection's 200-char truncation convention. */
  private truncateForLedger(value: string): string {
    return value.length > 200 ? value.substring(0, 200) + '...' : value;
  }

  /**
   * Build Required Response Format section for structured delivery verification. `coverage` adds
   * the per-gate lines and `verdictLine` the overall verdict line. A normal render passes its
   * step's verdict request for both: every render of a gated step asks, and no render of an
   * ungated one does, since it has no gate to grade (R171). A review render keeps its own
   * rule: its verdict block above asks, and the line closes only its final step.
   */
  private buildResponseFormatSection(
    request: { readonly coverage: boolean; readonly verdictLine: boolean },
    declaredSections: readonly DeclaredSection[] = []
  ): string {
    const lines: string[] = [
      '---',
      '',
      '### Required Response Format',
      '',
      '**Summary**: What was implemented (2-3 sentences)',
      '',
    ];

    // Declared section headers — derived from the framework's phases.yaml, which is the same
    // source `19-phase-guard-verification-stage` grades this response against. Emitting the
    // vocabulary (not a fill-in skeleton) is what makes the guard satisfiable.
    if (declaredSections.length > 0) {
      lines.push(
        '**Required Sections** — emit these headers verbatim; they are graded structurally:'
      );
      for (const section of declaredSections) {
        const qualifier = section.required ? 'required' : 'optional';
        const criteria = section.criteria.length > 0 ? `; ${section.criteria.join('; ')}` : '';
        lines.push(`- \`${section.header}\` (${qualifier}${criteria})`);
      }
      lines.push('');
    }

    if (request.coverage) {
      lines.push(
        '**Gate Coverage**:',
        '- [1] PASS|FAIL: rationale',
        '- [2] PASS|FAIL: rationale',
        ''
      );
    }

    if (request.verdictLine) {
      lines.push('**GATE_REVIEW: PASS|FAIL - overall assessment**');
    }

    return lines.join('\n');
  }

  private isInlineGateId(gateId: string): boolean {
    if (!gateId) {
      return false;
    }
    return gateId.startsWith('temp_') || gateId.startsWith('inline_gate_');
  }

  private getStoredStepResult(
    chainContext: Record<string, unknown>,
    stepNumber: number
  ): string | undefined {
    if (!chainContext) {
      return undefined;
    }

    const stepResults = chainContext['step_results'] as Record<string, string> | undefined;
    if (stepResults) {
      const key = String(stepNumber);
      if (typeof stepResults[key] === 'string' && stepResults[key].trim().length > 0) {
        return stepResults[key];
      }
    }

    const previous = chainContext['previous_step_output'];
    if (typeof previous === 'string' && previous.trim().length > 0) {
      return previous;
    }

    const stepResultKey = `step${stepNumber}_result`;
    const alternate = chainContext[stepResultKey];
    if (typeof alternate === 'string' && alternate.trim().length > 0) {
      return alternate;
    }

    return undefined;
  }

  private normalizeStepArgs(
    argsInput?: Record<string, unknown>,
    prompt?: ConvertedPrompt
  ): Record<string, unknown> {
    const defaults: Record<string, unknown> = {};
    if (prompt?.arguments) {
      for (const arg of prompt.arguments) {
        if (arg.defaultValue !== undefined) {
          defaults[arg.name] = arg.defaultValue;
        }
      }
    }

    const result =
      !argsInput || typeof argsInput !== 'object' ? defaults : { ...defaults, ...argsInput };

    if (prompt?.arguments) {
      for (const arg of prompt.arguments) {
        if (arg.required && (result[arg.name] === undefined || result[arg.name] === '')) {
          this.logger.warn(
            `[SymbolicChain] Required argument "${arg.name}" missing for prompt "${prompt.id}"`
          );
        }
      }
    }

    return result;
  }

  private async renderTemplateString(
    templateString: string,
    templateContext: Record<string, unknown>,
    promptId: string,
    promptDir?: string
  ): Promise<string> {
    try {
      // Use reference resolver if available, otherwise fall back to standard template processing
      const referenceResolver = this.collaborators?.referenceResolver;
      const scriptReferenceResolver = this.collaborators?.scriptReferenceResolver;
      if (referenceResolver || scriptReferenceResolver) {
        const result = await processTemplateWithRefs(
          templateString,
          templateContext,
          {},
          referenceResolver,
          // `promptDir` enables prompt-local script lookup (WorkspaceScriptLoader tries
          // `${promptDir}/tools/${id}/` before workspace `resources/scripts/${id}/`). Omitting
          // it made a prompt with its own tool render standalone but fail as a chain step,
          // naming only the workspace path. 18-execution-stage always passed it.
          { scriptResolver: scriptReferenceResolver, promptDir }
        );
        return result.content;
      }

      // Fallback: standard synchronous template processing
      const rendered = processTemplate(templateString, templateContext, {});
      return rendered;
    } catch (error) {
      this.logger.error(`[SymbolicChain] Template rendering failed for ${promptId}:`, error);
      return `[ERROR] Template rendering failed for ${promptId}. Describe how you would proceed manually.`;
    }
  }

  private getPromptDisplayName(step: ChainStepPrompt): string {
    return step.convertedPrompt?.name || step.promptId;
  }

  private resolveReviewStep(
    stepPrompts: readonly ChainStepPrompt[],
    chainContext: Record<string, unknown>,
    review: ReviewRenderFacts
  ): ChainStepPrompt | undefined {
    if (stepPrompts.length === 0) {
      return undefined;
    }

    // The node the review grades first (`GateReview.nodeId`, the key it is stored under): an
    // ordinal stamped before a mid-run node insertion no longer points at the step it named, while
    // the id does. Falls through rather than clamping when the id names no step here (a step list
    // parsed before node-id minting), so it resolves by ordinal, not to position 0.
    const byNodeId = stepPrompts.find((step) => step.nodeId === review.nodeId);
    if (byNodeId !== undefined) return byNodeId;

    if (review.stepIndex !== undefined) {
      return stepPrompts[this.clampStepIndex(review.stepIndex, stepPrompts.length)];
    }

    const contextStep = this.extractStepIndexFromContext(chainContext);
    if (typeof contextStep === 'number') {
      return stepPrompts[this.clampStepIndex(contextStep, stepPrompts.length)];
    }

    return undefined;
  }

  private extractStepIndexFromContext(chainContext: Record<string, unknown>): number | undefined {
    const raw = chainContext['current_step'];
    if (typeof raw === 'number' && Number.isFinite(raw)) {
      return raw > 0 ? raw - 1 : 0;
    }
    if (typeof raw === 'string') {
      const parsed = Number.parseInt(raw, 10);
      if (!Number.isNaN(parsed)) {
        return parsed > 0 ? parsed - 1 : 0;
      }
    }
    return undefined;
  }

  private clampStepIndex(index: number, totalSteps: number): number {
    const normalizedIndex = Number.isFinite(index) ? Math.floor(index) : totalSteps - 1;
    if (normalizedIndex < 0) {
      return 0;
    }
    if (normalizedIndex >= totalSteps) {
      return totalSteps - 1;
    }
    return normalizedIndex;
  }

  private collectReviewGateIds(
    review: ReviewRenderFacts,
    additionalGateIds: readonly string[],
    reviewStep?: ChainStepPrompt
  ): { gateIds: string[]; explicitGateIds: string[] } {
    const gateSet = new Set<string>();
    const explicitSet = new Set<string>();
    const addGate = (gateId: unknown, explicit = false) => {
      if (typeof gateId !== 'string' || gateId.trim().length === 0) {
        return;
      }
      gateSet.add(gateId);
      if (explicit) {
        explicitSet.add(gateId);
      }
    };

    review.gateIds.forEach((gateId) => addGate(gateId));
    additionalGateIds?.forEach((gateId) => addGate(gateId));
    reviewStep?.inlineGateIds?.forEach((gateId) => addGate(gateId, true));
    review.explicitGateIds.forEach((gateId) => addGate(gateId, true));

    return {
      gateIds: Array.from(gateSet),
      explicitGateIds: Array.from(explicitSet),
    };
  }
}
