// @lifecycle canonical - Factory for PromptExecutionPipeline stage wiring.
/**
 * Pipeline Builder — Factory for PromptExecutionPipeline.
 *
 * Extracted from PromptExecutor to isolate the 23+ service instantiations
 * and stage wiring that constitute pipeline construction. Every new pipeline
 * service adds wiring here, keeping PromptExecutor focused on execution.
 *
 * Architecture:
 *   PromptExecutor (orchestration)
 *     └── PipelineBuilder (factory)
 *           └── PromptExecutionPipeline (coordinator)
 *                 └── PipelineStage[] — the `stages` array below is the contract;
 *                     its length is the stage count
 */

import { describeUndeclaredParameterRefusal } from '../../shared/undeclared-parameters.js';

import type { GateService } from '#engine/gates/services/gate-service-interface.js';
import type { PipelineDependencies } from './pipeline-dependencies.js';

import { RemainderProcessor } from '#engine/execution/capture/remainder-processor.js';
import { StepCaptureService } from '#engine/execution/capture/step-capture-service.js';
import { UnknownObservationProcessor } from '#engine/execution/capture/unknown-observation-processor.js';
import { resolveHandoffEvidenceMode } from '#engine/execution/delegation/handoff-contract.js';
import { ResponseAssembler } from '#engine/execution/formatting/response-assembler.js';
import {
  ChainBlueprintResolver,
  SymbolicCommandBuilder,
  WorkflowCommandBuilder,
} from '#engine/execution/parsers/index.js';
import { GateEnforcementAuthority } from '#engine/execution/pipeline/decisions/index.js';
import {
  // Core pipeline
  PromptExecutionPipeline,
  type PipelineStage,
  // Stages 01-03: Initialization
  RequestNormalizationStage,
  ExecutionLifecycleStage,
  IdentityResolutionStage,
  // Stages 04-09: Parsing, Planning, Scripts
  CommandParsingStage,
  InlineGateExtractionStage,
  OperatorValidationStage,
  ExecutionPlanningStage,
  ScriptExecutionStage,
  ScriptAutoExecuteStage,
  // Stages 10-15: Judge, Gates, Framework, Session, Injection
  GateEnhancementStage,
  FrameworkResolutionStage,
  JudgeSelectionStage,
  PromptGuidanceStage,
  SessionManagementStage,
  InjectionControlStage,
  // Stages 16-22: Capture, Execution, Review, Formatting
  StepResponseCaptureStage,
  createShellVerificationStage,
  StepExecutionStage,
  createPhaseGuardVerificationStage,
  GateReviewStage,
  ResponseFormattingStage,
} from '#engine/execution/pipeline/index.js';
import { resolveDeclaredSections } from '#engine/frameworks/declared-sections.js';
import { getDefaultRuntimeLoader } from '#engine/frameworks/definitions/index.js';
import {
  JudgeMenuFormatter,
  type FrameworkJudgePromptProvider,
} from '#engine/gates/judge/judge-menu-formatter.js';
import { JudgeResourceCollector } from '#engine/gates/judge/judge-resource-collector.js';
import { GateEnhancementService } from '#engine/gates/services/gate-enhancement-service.js';
import { GateMetricsRecorder } from '#engine/gates/services/gate-metrics-recorder.js';
import { runGateReviewEvidence } from '#engine/gates/services/gate-review-evidence.js';
import { GateServiceFactory } from '#engine/gates/services/gate-service-factory.js';
import { GateVerdictProcessor } from '#engine/gates/services/gate-verdict-processor.js';
import { InlineGateProcessor } from '#engine/gates/services/inline-gate-processor.js';
import { createRunStepViewProvider } from '#engine/gates/services/run-step-view.js';
import { TemporaryGateRegistrar } from '#engine/gates/services/temporary-gate-registrar.js';
import {
  createShellVerifyExecutor,
  createVerifyActiveStateStore,
} from '#engine/gates/shell/index.js';
import { createToolDetectionService } from '#modules/automation/detection/tool-detection-service.js';
import { createScriptExecutor } from '#modules/automation/execution/script-executor.js';
import { createToolTriggerFilter } from '#modules/automation/execution/tool-trigger-filter.js';
import { retargetGates } from '#modules/workflow-ir/chain-prompt-expansion.js';
import { compileWorkflowIR } from '#modules/workflow-ir/compiler.js';
import { DEFAULT_WORKFLOW_CAPS } from '#modules/workflow-ir/node-schema.js';
import { validateWorkflowIR } from '#modules/workflow-ir/validator.js';

/**
 * Factory that constructs and wires the PromptExecutionPipeline.
 *
 * Receives a typed PipelineDependencies bag and produces a fully-wired
 * pipeline with every stage (the `stages` array below is the contract; its
 * length is the stage count) and its intermediate services.
 */
export class PipelineBuilder {
  private readonly deps: PipelineDependencies;

  constructor(deps: PipelineDependencies) {
    this.deps = deps;
  }

  build(): PromptExecutionPipeline {
    const { deps } = this;
    const temporaryGateRegistry = deps.lightweightGateSystem.getTemporaryGateRegistry();
    if (!temporaryGateRegistry) {
      throw new Error('Temporary gate registry unavailable');
    }

    // ── Stages 01-03: Initialization ──

    const requestStage = new RequestNormalizationStage(
      deps.chainSessionRouter ?? null,
      deps.routeToTool,
      deps.logger
    );

    // Depends only on services this builder already holds, so it is built once
    // here and handed to the pipeline rather than reconstructed per request.
    const gateEnforcement = new GateEnforcementAuthority(
      deps.chainSessionStore,
      deps.logger,
      deps.lightweightGateSystem.gateLoader
    );

    const lifecycleStage = new ExecutionLifecycleStage(temporaryGateRegistry, deps.logger);

    const identityResolutionStage = new IdentityResolutionStage(() => {
      // No "did the operator configure identity?" guard any more: the loader resolves the whole
      // section (row 6.2 / R57), so `mode` is always set and the guard that used to stand here
      // could only ever be false. It was not inert — a config with launch defaults but no
      // explicit `identity.mode` (what `applyRuntimeIdentityOverrides` produces for every
      // ordinary launch) took the `null` branch, and the stage then resolved identity with NO
      // launch defaults and NO transport, discarding the derived workspace id.
      const identityConfig = deps.configManager.getConfig().identity;
      return {
        mode: identityConfig.mode,
        allowPerRequestOverride: identityConfig.allowPerRequestOverride,
        launchDefaults: identityConfig.launchDefaults,
        // Not `getConfig().transport` — `Config` carries no such member (transport is
        // launch-time-only, Ruling R30). `getTransportMode()` is the launch-option-aware read.
        transportMode: deps.configManager.getTransportMode(),
      };
    }, deps.logger);

    // ── Stages 04-09: Parsing, Planning, Scripts ──

    // The composition root is the only layer that may name both sides: `engine/` cannot
    // value-import `modules/workflow-ir/` (dependency-cruiser `engine-no-modules-or-mcp-value`,
    // error severity), and these functions are pure, so passing them as a port costs nothing at
    // runtime and keeps the layer edge honest. ONE port for BOTH command builders (row A.2,
    // P6.105): an arrow-chain and a submitted IR are the same representation, so they validate,
    // compile and retarget through the same functions rather than two that agree by hand.
    // Constructed per pipeline, holding no state — the Streamable HTTP transport rebuilds the
    // server per request, so anything cached here would exist on STDIO and vanish on HTTP.
    const workflowIrPort = {
      validate: validateWorkflowIR,
      compile: compileWorkflowIR,
      retargetGates,
    };
    const symbolicCommandBuilder = new SymbolicCommandBuilder(
      deps.parsingSystem.argumentParser,
      deps.logger,
      workflowIrPort
    );
    const blueprintResolver = new ChainBlueprintResolver(deps.chainSessionStore, deps.logger);
    const workflowCommandBuilder = new WorkflowCommandBuilder(workflowIrPort, deps.logger);
    const commandParsingStage = new CommandParsingStage(
      deps.parsingSystem.commandParser,
      deps.parsingSystem.argumentParser,
      deps.getConvertedPrompts,
      deps.logger,
      symbolicCommandBuilder,
      { blueprintResolver, workflowCommandBuilder }
    );

    const inlineGateProcessor = new InlineGateProcessor(
      temporaryGateRegistry,
      deps.gateReferenceResolver,
      deps.logger,
      deps.chainSessionStore
    );
    const inlineGateStage = new InlineGateExtractionStage(inlineGateProcessor, deps.logger);
    const operatorValidationStage = new OperatorValidationStage(
      deps.frameworkValidator ?? null,
      deps.logger
    );
    const planningStage = new ExecutionPlanningStage(
      deps.executionPlanner,
      deps.getFrameworkStateEnabled,
      deps.logger
    );

    // Script execution stage
    const scriptExecutor = createScriptExecutor({ debug: false });
    const toolDetectionService = createToolDetectionService({ debug: false });
    const toolTriggerFilter = createToolTriggerFilter({ debug: false });
    const scriptExecutionStage = new ScriptExecutionStage(
      scriptExecutor,
      toolDetectionService,
      toolTriggerFilter,
      deps.logger
    );

    // Script auto-execute stage
    const scriptAutoExecuteStage = new ScriptAutoExecuteStage(
      this.resolveResourceManagerHandler(),
      deps.logger,
      // The same refusal the tool boundary runs, injected because layer 2 may not import layer 4.
      (params) => describeUndeclaredParameterRefusal('resource_manager', params)
    );

    // ── Stages 10-15: Judge, Gates, Framework, Session, Injection ──

    const frameworkStage = this.createFrameworkStage();

    const frameworksProvider = () => {
      try {
        const loader = getDefaultRuntimeLoader();
        const ids = loader.discoverFrameworks();
        return ids
          .map((id) => {
            const def = loader.loadFramework(id);
            if (!def || def.enabled === false) return null;
            const description =
              (def as unknown as Record<string, unknown>)['description'] ??
              def.systemPromptGuidance?.trim().split('\n')[0] ??
              'Framework';
            return {
              id: (def.type || def.id).toLowerCase(),
              name: def.name || def.type || def.id,
              description: String(description),
              category: 'guidance' as const,
              userMessageTemplate: '',
              arguments: [],
              registerWithMcp: false,
            };
          })
          .filter((r): r is NonNullable<typeof r> => r !== null);
      } catch {
        return [];
      }
    };

    const judgePromptProvider: FrameworkJudgePromptProvider = (frameworkId) => {
      try {
        const loader = getDefaultRuntimeLoader();
        const definition = loader.loadFramework(frameworkId);
        return definition?.judgePrompt;
      } catch {
        return undefined;
      }
    };

    const judgeResourceCollector = new JudgeResourceCollector(
      deps.getConvertedPrompts,
      deps.lightweightGateSystem.gateLoader,
      deps.logger,
      frameworksProvider,
      deps.styleManager ?? null,
      // Per call, no cache: the manager can be late-bound or reloaded after this stage is built.
      (frameworkId) => deps.frameworkManager?.getFramework(frameworkId)
    );
    const judgeMenuFormatter = new JudgeMenuFormatter(deps.logger, judgePromptProvider);
    const judgeSelectionStage = new JudgeSelectionStage(
      judgeResourceCollector,
      judgeMenuFormatter,
      deps.configManager,
      deps.logger
    );

    const promptGuidanceStage = new PromptGuidanceStage(
      deps.promptGuidanceService ?? null,
      deps.styleManager ?? null,
      deps.logger
    );

    const gateService = this.createGateService();
    // One read model of the live run, two consumers: the registrar resolves an ordinal target to
    // a node id against it, and the enhancement service matches by that id and drops gates whose
    // target node the mutation policy retired (P4 row 4.1 / OQ-P4-3).
    const runStepViewProvider = createRunStepViewProvider(deps.chainSessionStore);
    const gateEnhancementService = new GateEnhancementService(
      gateService,
      temporaryGateRegistry,
      (scope) => deps.frameworkManager?.selectFramework({ scope })?.id,
      () => deps.gateManager,
      deps.lightweightGateSystem.gateLoader,
      new GateMetricsRecorder(deps.getAnalyticsService),
      deps.logger,
      runStepViewProvider,
      // A contributed step's prompt (P6.101): its node has no parse-time step to carry one.
      (promptId) => deps.getConvertedPrompts().find((prompt) => prompt.id === promptId)
    );
    const temporaryGateRegistrar = new TemporaryGateRegistrar(
      temporaryGateRegistry,
      deps.gateReferenceResolver,
      deps.logger,
      runStepViewProvider
    );
    const gateStage = new GateEnhancementStage(
      gateEnhancementService,
      temporaryGateRegistrar,
      () => deps.configManager.getGatesConfig(),
      deps.logger,
      (scope) => deps.lightweightGateSystem.isGateSystemEnabled(scope)
    );

    const sessionStage = new SessionManagementStage(deps.chainSessionStore, deps.logger);
    const injectionControlStage = new InjectionControlStage(
      () => deps.configManager.getInjectionConfig(),
      deps.logger
    );

    // ── Stages 16-22: Capture, Execution, Review, Formatting ──

    // One executor for BOTH shell paths — the inline `:: verify:` stage below and the
    // gate-YAML `shell_verify` criteria (stage 20, and a detached node's review in stage 16).
    // They used to hold different instances (this one, and a module singleton), which is how
    // row 1.5's control could have covered one and silently missed the other.
    const shellVerifyExecutor = createShellVerifyExecutor({
      debug: false,
      gateSystemEnabled: (scope) => deps.lightweightGateSystem.isGateSystemEnabled(scope),
    });
    const gateVerdictProcessor = new GateVerdictProcessor(
      deps.chainSessionStore,
      deps.logger,
      deps.hookRegistry,
      deps.notificationEmitter,
      // A detached node's review runs its gates' checks against the node's recorded output
      // (row 4.8, R10.3) through the same runners and executor stage 20 uses.
      async (gateIds, agentResponse, scope) =>
        (
          await runGateReviewEvidence(
            gateIds,
            deps.lightweightGateSystem.gateLoader,
            agentResponse,
            { shellVerifyExecutor, scriptToolRuntime: deps.scriptToolRuntime },
            scope
          )
        ).checkResults
    );
    const stepCaptureService = new StepCaptureService(
      deps.chainSessionStore,
      deps.logger,
      deps.executionRecordStore,
      deps.hookRegistry,
      deps.notificationEmitter
    );
    const unknownObservationProcessor = new UnknownObservationProcessor(
      deps.chainSessionStore,
      deps.logger
    );
    // Row 2.3. Same composition-root reason as `workflowCommandBuilder` above: the validator and
    // the caps are Layer 3 and stage 16 is Layer 2, so this is the only place allowed to name
    // both. Stateless per pipeline, like everything else built here — a Streamable HTTP request
    // rebuilds it, and nothing it holds outlives the call.
    const remainderProcessor = new RemainderProcessor(
      deps.chainSessionStore,
      { validate: validateWorkflowIR, defaultCaps: DEFAULT_WORKFLOW_CAPS },
      deps.getConvertedPrompts,
      deps.logger
    );

    // Phase guard verification stage — built before stage 16, which hands it a detached node's
    // late report to grade (row 3.8): stage 16 answers that call, so stage 19 never runs on it.
    // Stage 16 also takes its grade of an ordinary answer before the advance (R170).
    const phaseGuardVerificationStage = createPhaseGuardVerificationStage(
      () => deps.frameworkManager,
      // Resolved by the config loader, not here: the literal that used to sit on this line was
      // one of three statements of the same pair (row 6.2 / R57).
      () => deps.configManager.getConfig().phaseGuards,
      deps.chainSessionStore,
      deps.logger
    );

    const responseCaptureStage = new StepResponseCaptureStage(
      gateVerdictProcessor,
      stepCaptureService,
      deps.chainSessionStore,
      unknownObservationProcessor,
      deps.logger,
      // P5-F6: post-advance review re-evaluation reuses the SAME GateEnhancementService instance
      // stage 11 uses — its `temporaryGateRegistry`/`runStepViewProvider` wiring is what the
      // step-target lookup needs, and nothing about it is per-call state.
      {
        gateEnhancementService,
        remainderProcessor,
        // A getter, not a resolved value: `config.json` hot-reloads, and the identity stage
        // above reads its config the same way for the same reason. Resolving once here would
        // pin the mode to whatever was on disk when this pipeline was built.
        handoffEvidenceMode: () =>
          resolveHandoffEvidenceMode(deps.configManager.getConfig().execution.delegation?.evidence),
        gradeLateReport: (context, sessionId, node, review, recordedOutput) =>
          phaseGuardVerificationStage.gradeLateReport(
            context,
            sessionId,
            node,
            review,
            recordedOutput
          ),
        // R144: the same stage 14 instance decides again once this stage has moved the run.
        redecideInjection: (context, position) =>
          injectionControlStage.redecideAt(context, position),
        // R170: the same stage 19 instance grades the answer before this stage decides the
        // advance; stage 19 then opens its review from that grade, never grading twice.
        gradeAnswer: (context) => phaseGuardVerificationStage.gradeAnswer(context),
      }
    );

    // The runtime root, not the package: the Python Stop hook finds this file beside `state.db`,
    // and a package-relative one ignored MCP_RUNTIME_ROOT and was wiped by every plugin update.
    const verifyActiveStateStore = createVerifyActiveStateStore(deps.logger, {
      runtimeStateDir: deps.configManager.getRuntimeStateDirectory(),
    });
    const shellVerificationStage = createShellVerificationStage(
      shellVerifyExecutor,
      verifyActiveStateStore,
      deps.chainSessionStore,
      gateVerdictProcessor,
      deps.logger
    );

    // Lifecycle hook: clean up verify-state when sessions are cleared
    deps.chainSessionStore.onSessionCleared(async (_sessionId: string, session) => {
      if (session.pendingShellVerification?.shellVerify?.loop === true) {
        await verifyActiveStateStore.clearState(session.chainId);
      }
    });

    const executionStage = new StepExecutionStage(
      deps.chainOperatorExecutor,
      deps.chainSessionStore,
      deps.logger,
      deps.referenceResolver,
      deps.scriptReferenceResolver,
      deps.executionRecordStore
    );

    const gateReviewStage = new GateReviewStage(
      deps.chainOperatorExecutor,
      deps.chainSessionStore,
      deps.lightweightGateSystem.gateLoader,
      deps.logger,
      () => deps.configManager.getConfig().gates,
      {
        executionRecordStore: deps.executionRecordStore,
        scriptToolRuntime: deps.scriptToolRuntime,
        shellVerifyExecutor,
      }
    );
    // Third consumer of the same run read model (P6 Tier 2): the handoff CTA and its P5
    // visibility envelope resolve the handed-off step by node identity, so they need the run's
    // node order and its retired nodes — the parse array alone answers a positional question the
    // mutation policy has already invalidated (P6-F1).
    const responseAssembler = new ResponseAssembler(
      runStepViewProvider,
      // Phase-guard declared headers for gated single prompts (Tier 2.5, OQ-1). Read through
      // `deps.frameworkManager` per call — no cache — matching the chain path's identical
      // wiring at `prompt-executor.ts:createChainOperatorExecutor`, so hot-reload keeps working
      // for this consumer too.
      (frameworkId: string) => resolveDeclaredSections(() => deps.frameworkManager, frameworkId)
    );
    const formattingStage = new ResponseFormattingStage(
      deps.responseFormatter,
      responseAssembler,
      deps.logger,
      deps.executionRecordStore,
      deps.chainSessionStore
    );
    // A run's temporary gates live as long as the run (R47): the pipeline hands a call's gates
    // to its run, and they are released here when the run ends.
    deps.chainSessionStore.onRunEnded((sessionId) => {
      temporaryGateRegistry.releaseRun(sessionId);
    });

    // Execution order. The array IS the contract — the pipeline runs it front to
    // back and does no reordering of its own.
    //
    // Constraints this order encodes, each of which breaks something if inverted.
    // The first three are also declared as `requires`/`provides` on the stages
    // themselves, so inverting one throws from the pipeline constructor rather
    // than failing at runtime; the last two are enforced by this comment only.
    //   - JudgeSelection before PromptGuidance, which reads the
    //     state.framework.clientSelectedStyle that JudgeSelection writes.
    //   - SessionManagement before InjectionControl, which needs currentStep.
    //   - InjectionControl before PromptGuidance, which reads the injection
    //     decisions InjectionControl writes to context.state.injection.
    //   - ScriptExecution before ScriptAutoExecute, so auto-executed tool output
    //     is available to the template context that follows.
    //   - ShellVerification before StepExecution, enabling verify loops where a
    //     shell command grades the previous response.
    //
    // JudgeSelection also runs before GateEnhancement and FrameworkResolution so
    // the judge phase (%judge) returns a clean resource menu with no framework or
    // gate injection. That one is a property of the early return, not of a context
    // key, so it has no `requires` declaration to carry it.
    const stages: readonly PipelineStage[] = [
      requestStage,
      lifecycleStage,
      identityResolutionStage,
      commandParsingStage,
      inlineGateStage,
      operatorValidationStage,
      planningStage,
      scriptExecutionStage,
      scriptAutoExecuteStage,
      judgeSelectionStage,
      gateStage,
      frameworkStage,
      sessionStage,
      injectionControlStage,
      promptGuidanceStage,
      responseCaptureStage,
      shellVerificationStage,
      executionStage,
      phaseGuardVerificationStage,
      gateReviewStage,
      formattingStage,
    ];

    return new PromptExecutionPipeline(stages, {
      logger: deps.logger,
      metricsProvider: deps.getAnalyticsService,
      hookRegistry: deps.hookRegistry,
      gateEnforcement,
      // Stages take `| null`; PipelinePorts is uniformly optional, so normalize here
      // rather than admitting both empty representations into the ports interface.
      executionRecordStore: deps.executionRecordStore ?? undefined,
      chainSessionStore: deps.chainSessionStore,
      temporaryGateRegistry,
    });
  }

  /**
   * Real framework stage when a manager is wired, otherwise an inert stage that
   * keeps the position occupied so the order stays stable.
   */
  private createFrameworkStage(): PipelineStage {
    const { deps } = this;
    if (!deps.frameworkManager) {
      return {
        name: 'FrameworkResolution',
        execute: async () => {
          deps.logger.debug(
            '[PipelineBuilder] Framework stage skipped (framework manager unavailable)'
          );
        },
      };
    }

    return new FrameworkResolutionStage(
      deps.frameworkManager,
      deps.getFrameworkStateEnabled,
      deps.logger,
      deps.lightweightGateSystem.gateLoader
    );
  }

  private resolveResourceManagerHandler(): ReturnType<
    NonNullable<NonNullable<PipelineDependencies['mcpToolsManager']>['getResourceManagerHandler']>
  > | null {
    return this.deps.mcpToolsManager?.getResourceManagerHandler?.() ?? null;
  }

  private createGateService(): GateService {
    const { deps } = this;
    const factory = new GateServiceFactory(
      deps.logger,
      deps.configManager,
      deps.gateGuidanceRenderer
    );
    return factory.createGateService();
  }
}
